import { Badge } from "~/components/ui/badge";
import { Checkbox } from "~/components/ui/checkbox";
import { Label } from "~/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "~/components/ui/select";

interface HashTagPreset {
  id: string;
  name: string;
  tags: string;
  description?: string | null;
}

interface QueueType {
  id: string;
  name: string;
  hashTagPreset?: HashTagPreset | null;
}

interface HashtagPresetToggleProps {
  presets: HashTagPreset[];
  selectedPresetId?: string | null;
  onSelect: (presetId: string | null, hashtags: string) => void;
  disabled?: boolean;
  showQueuePreset?: boolean;
  queueType?: QueueType | null;
  useHashtagPresets?: boolean;
  onUseHashtagPresetsChange?: (enabled: boolean) => void;
}

export function HashtagPresetToggle({
  presets,
  selectedPresetId,
  onSelect,
  disabled = false,
  showQueuePreset = false,
  queueType = null,
  useHashtagPresets = false,
  onUseHashtagPresetsChange,
}: HashtagPresetToggleProps) {
  const selectedPreset = presets.find((p) => p.id === selectedPresetId);

  const handlePresetChange = (value: string) => {
    if (value === "none") {
      onSelect(null, "");
    } else {
      const preset = presets.find((p) => p.id === value);
      onSelect(preset?.id ?? null, preset?.tags ?? "");
    }
  };

  const countHashtags = (tags: string): number => {
    return tags
      .split(/\s+/)
      .filter((tag) => tag.startsWith("#") && tag.length > 1).length;
  };

  return (
    <div className="space-y-4">
      {/* Toggle checkbox for hashtag presets */}
      <div className="flex items-center space-x-2">
        <Checkbox
          id="use-hashtag-presets"
          checked={useHashtagPresets}
          onCheckedChange={(checked) => onUseHashtagPresetsChange?.(!!checked)}
          disabled={disabled}
        />
        <Label
          htmlFor="use-hashtag-presets"
          className="cursor-pointer text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          Use Hashtag Presets
        </Label>
      </div>

      {/* Show queue type's hashtag preset info when available */}
      {showQueuePreset && queueType?.hashTagPreset ? (
        <div
          className={`rounded-lg p-3 ${
            useHashtagPresets
              ? "border border-gray-200 bg-gray-50 dark:border-gray-700 dark:bg-gray-800"
              : "border border-green-200 bg-green-50 dark:border-green-800 dark:bg-green-900/20"
          }`}
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                {useHashtagPresets ? "Queue Default:" : "Using Queue Default:"}
              </span>
              <Badge variant="secondary" className="text-xs">
                {queueType.hashTagPreset.name}
              </Badge>
              <span className="text-xs text-gray-500 dark:text-gray-400">
                ({countHashtags(queueType.hashTagPreset.tags)} tags)
              </span>
            </div>
          </div>
          {!useHashtagPresets ? (
            <div className="mt-2 flex flex-wrap gap-1">
              {queueType.hashTagPreset.tags
                .split(/\s+/)
                .filter((tag) => tag.startsWith("#") && tag.length > 1)
                .slice(0, 4)
                .map((tag, index) => (
                  <Badge
                    key={index}
                    variant="outline"
                    className="px-2 py-0.5 text-xs"
                  >
                    {tag}
                  </Badge>
                ))}
              {countHashtags(queueType.hashTagPreset.tags) > 4 ? (
                <Badge variant="outline" className="px-2 py-0.5 text-xs">
                  +{countHashtags(queueType.hashTagPreset.tags) - 4} more
                </Badge>
              ) : null}
            </div>
          ) : null}
        </div>
      ) : null}

      {/* Hashtag preset selector */}
      {useHashtagPresets ? (
        <div className="space-y-3">
          {presets.length === 0 ? (
            <div className="rounded-lg border border-yellow-200 bg-yellow-50 p-3 dark:border-yellow-800 dark:bg-yellow-900/20">
              <p className="text-sm text-yellow-700 dark:text-yellow-300">
                No hashtag presets available. Create some in Settings to reuse
                hashtags across your posts.
              </p>
            </div>
          ) : (
            <>
              <div className="space-y-2">
                <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  Choose Hashtag Preset
                </Label>
                <Select
                  value={selectedPresetId || "none"}
                  onValueChange={handlePresetChange}
                  disabled={disabled}
                >
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Select a hashtag preset" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">
                      <span className="text-gray-500">No hashtag preset</span>
                    </SelectItem>
                    {presets.map((preset) => (
                      <SelectItem key={preset.id} value={preset.id}>
                        <div className="flex w-full items-center justify-between">
                          <span className="font-medium">{preset.name}</span>
                          <Badge variant="secondary" className="ml-2 text-xs">
                            {countHashtags(preset.tags)}
                          </Badge>
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {/* Selected preset preview */}
              {selectedPreset ? (
                <div className="rounded-lg border border-gray-200 bg-gray-50 p-3 dark:border-gray-700 dark:bg-gray-800">
                  <div className="mb-2 flex items-center gap-2">
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                      {selectedPreset.name}
                    </span>
                    <Badge variant="secondary" className="text-xs">
                      {countHashtags(selectedPreset.tags)} tags
                    </Badge>
                  </div>
                  {selectedPreset.description ? (
                    <p className="mb-2 text-xs text-gray-500 dark:text-gray-400">
                      {selectedPreset.description}
                    </p>
                  ) : null}
                  <div className="flex flex-wrap gap-1">
                    {selectedPreset.tags
                      .split(/\s+/)
                      .filter((tag) => tag.startsWith("#") && tag.length > 1)
                      .slice(0, 6)
                      .map((tag, index) => (
                        <Badge
                          key={index}
                          variant="outline"
                          className="px-2 py-0.5 text-xs"
                        >
                          {tag}
                        </Badge>
                      ))}
                    {countHashtags(selectedPreset.tags) > 6 ? (
                      <Badge variant="outline" className="px-2 py-0.5 text-xs">
                        +{countHashtags(selectedPreset.tags) - 6} more
                      </Badge>
                    ) : null}
                  </div>
                </div>
              ) : null}
            </>
          )}
        </div>
      ) : null}
    </div>
  );
}

import { useState, useRef, useEffect } from "react";
import type React from "react";
interface MediaPlayerProps {
  src: string;
  alt?: string;
  className?: string;
  controls?: boolean;
  autoPlay?: boolean;
  muted?: boolean;
  loop?: boolean;
  poster?: string; // For video poster image
}

// Helper function to determine if URL is a video based on file extension or MIME hints
const isVideoUrl = (url: string): boolean => {
  const videoExtensions = [
    ".mp4",
    ".webm",
    ".ogg",
    ".mov",
    ".avi",
    ".mkv",
    ".m4v",
  ];
  const lowerUrl = url.toLowerCase();

  // Check for video file extensions
  return videoExtensions.some((ext) => lowerUrl.includes(ext));
};

export default function MediaPlayer({
  src,
  alt = "Media content",
  className = "",
  controls = true,
  autoPlay = false,
  muted = true,
  loop = false,
  poster,
}: MediaPlayerProps) {
  const [isVideo, setIsVideo] = useState<boolean | null>(null);
  const [hasError, setHasError] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    // Initial guess based on URL
    setIsVideo(isVideoUrl(src));
  }, [src]);

  const handleImageLoad = () => {
    setIsLoading(false);
    setIsVideo(false);
  };

  const handleImageError = () => {
    // If image fails to load, it might be a video
    setIsLoading(false);
    setIsVideo(true);
    setHasError(false);
  };

  const handleVideoLoad = () => {
    setIsLoading(false);
    setIsVideo(true);
    setHasError(false);
  };

  const handleVideoError = () => {
    setIsLoading(false);
    setHasError(true);
  };

  if (hasError) {
    return (
      <div
        className={`flex items-center justify-center bg-gray-200 dark:bg-gray-700 ${className}`}
      >
        <div className="text-center">
          <div className="mb-2 text-gray-500">
            <svg
              className="mx-auto h-8 w-8"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9.172 16.172a4 4 0 015.656 0M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h10a2 2 0 012 2v14a2 2 0 01-2 2z"
              />
            </svg>
          </div>
          <p className="text-sm text-gray-500">Unable to load media</p>
        </div>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div
        className={`flex animate-pulse items-center justify-center bg-gray-200 dark:bg-gray-700 ${className}`}
      >
        <div className="text-gray-500">
          <svg className="h-8 w-8 animate-spin" fill="none" viewBox="0 0 24 24">
            <circle
              className="opacity-25"
              cx="12"
              cy="12"
              r="10"
              stroke="currentColor"
              strokeWidth="4"
            ></circle>
            <path
              className="opacity-75"
              fill="currentColor"
              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
            ></path>
          </svg>
        </div>
      </div>
    );
  }

  // If we determined it's a video or our initial guess was video
  if (isVideo) {
    return (
      <video
        ref={videoRef}
        className={className}
        controls={controls}
        autoPlay={autoPlay}
        muted={muted}
        loop={loop}
        poster={poster}
        onLoadedMetadata={handleVideoLoad}
        onError={handleVideoError}
        preload="metadata"
      >
        <source src={src} type="video/mp4" />
        <source src={src} type="video/webm" />
        <source src={src} type="video/ogg" />
        <track kind="captions" srcLang="en" label="English" />
        Your browser does not support the video tag.
      </video>
    );
  }

  // Default to image
  return (
    <img
      src={src}
      alt={alt}
      className={className}
      onLoad={handleImageLoad}
      onError={handleImageError}
      loading="lazy"
    />
  );
}

// Utility component for media thumbnails with play button overlay
export function MediaThumbnail({
  src,
  alt = "Media thumbnail",
  className = "w-full h-48 object-cover",
  onClick,
}: {
  src: string;
  alt?: string;
  className?: string;
  onClick?: () => void;
}) {
  const isVideo = isVideoUrl(src);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (onClick && (e.key === "Enter" || e.key === " ")) {
      e.preventDefault();
      onClick();
    }
  };

  return (
    <div 
      className="group relative cursor-pointer" 
      onClick={onClick}
      onKeyDown={onClick ? handleKeyDown : undefined}
      role={onClick ? "button" : undefined}
      tabIndex={onClick ? 0 : undefined}
    >
      <MediaPlayer
        src={src}
        alt={alt}
        className={className}
        controls={false}
        autoPlay={false}
        muted={true}
      />
      {isVideo ? (
        <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-30 transition-all duration-200 group-hover:bg-opacity-50">
          <div className="rounded-full bg-white bg-opacity-90 p-3 transition-all duration-200 group-hover:bg-opacity-100">
            <svg
              className="h-8 w-8 text-gray-800"
              fill="currentColor"
              viewBox="0 0 24 24"
            >
              <path d="M8 5v14l11-7z" />
            </svg>
          </div>
        </div>
      ) : null}
      {/* Media type indicator */}
      <div className="absolute left-2 top-2 rounded bg-black bg-opacity-70 px-2 py-1 text-xs text-white">
        {isVideo ? "🎥" : "🖼️"}
      </div>
    </div>
  );
}

// Utility component for full-screen media modal
export function MediaModal({
  src,
  alt = "Media content",
  isOpen,
  onClose,
}: {
  src: string;
  alt?: string;
  isOpen: boolean;
  onClose: () => void;
}) {
  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener("keydown", handleEscape);
      document.body.style.overflow = "hidden";
    }

    return () => {
      document.removeEventListener("keydown", handleEscape);
      document.body.style.overflow = "unset";
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-90">
      <div className="relative max-h-full max-w-7xl p-4">
        <button
          onClick={onClose}
          className="absolute right-4 top-4 z-10 rounded-full bg-black bg-opacity-50 p-2 text-white transition-all hover:bg-opacity-70"
        >
          <svg
            className="h-6 w-6"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M6 18L18 6M6 6l12 12"
            />
          </svg>
        </button>
        <MediaPlayer
          src={src}
          alt={alt}
          className="max-h-[90vh] max-w-full object-contain"
          controls={true}
          autoPlay={isVideoUrl(src)}
          muted={false}
        />
      </div>
    </div>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState } from "react";

import { Button } from "~/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "~/components/ui/card";
import { Label } from "~/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "~/components/ui/select";
import { timeZonesList } from "~/lib/date";

interface TimezoneSettingsProps {
  timezone: string | null;
}

interface FetcherData {
  success?: boolean;
  error?: string;
}

export function TimezoneSettings({ timezone }: TimezoneSettingsProps) {
  const fetcher = useFetcher<FetcherData>();
  const [selectedTimezone, setSelectedTimezone] = useState(
    timezone || "Etc/UTC",
  );

  const isSubmitting = fetcher.state === "submitting";
  const hasChanged = selectedTimezone !== timezone;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData();
    formData.set("_action", "update_timezone");
    formData.set("timezone", selectedTimezone);
    fetcher.submit(formData, { method: "post" });
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Timezone</CardTitle>
        <CardDescription>
          Set your timezone for scheduling posts
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="timezone">Select Timezone</Label>
            <Select
              value={selectedTimezone}
              onValueChange={setSelectedTimezone}
              disabled={isSubmitting}
            >
              <SelectTrigger id="timezone">
                <SelectValue placeholder="Select a timezone" />
              </SelectTrigger>
              <SelectContent>
                {timeZonesList.map((tz) => (
                  <SelectItem key={tz} value={tz}>
                    {tz}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <Button
            type="submit"
            disabled={isSubmitting || !hasChanged}
            className="w-full"
          >
            {isSubmitting ? "Saving..." : "Save Timezone"}
          </Button>

          {fetcher.data?.success ? (
            <p className="text-sm text-green-600">
              Timezone updated successfully!
            </p>
          ) : null}
          {fetcher.data?.error ? (
            <p className="text-sm text-destructive">{fetcher.data.error}</p>
          ) : null}
        </form>
      </CardContent>
    </Card>
  );
}

import { PlayIcon } from "@heroicons/react/20/solid";
import React from "react";
interface MediaThumbnailProps {
  src: string | undefined | null;
  alt?: string;
  className?: string;
  onClick?: () => void;
  forceType?: "image" | "video";
  onError?: () => void;
  fallback?: React.ReactNode;
  hidePlayButton?: boolean;
}

const MediaThumbnail: React.FC<MediaThumbnailProps> = ({
  src,
  alt = "Media thumbnail",
  className = "",
  onClick,
  forceType,
  onError,
  fallback,
  hidePlayButton = false,
}) => {
  const [hasError, setHasError] = React.useState(false);

  // Reset error state when src changes
  React.useEffect(() => {
    setHasError(false);
  }, [src]);

  // Determine if the source is a video based on extension, unless forceType is provided
  const isVideo = React.useMemo(() => {
    if (forceType === "video") return true;
    if (forceType === "image") return false;
    // Handle undefined/null src safely
    if (!src || typeof src !== "string") return false;
    const lower = src.toLowerCase();
    const videoExtensions = [
      ".mp4",
      ".webm",
      ".ogg",
      ".mov",
      ".avi",
      ".mkv",
      ".m4v",
    ];
    return videoExtensions.some((ext) => lower.includes(ext));
  }, [src, forceType]);

  // Handle missing src early
  if (!src || typeof src !== "string") {
    if (fallback) return <>{fallback}</>;
    return (
      <div
        className={`flex items-center justify-center bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400 ${className}`}
      >
        NO MEDIA
      </div>
    );
  }

  const handleImageError = () => {
    setHasError(true);
    onError?.();
  };

  const handleImageLoad = () => {
    // Image loaded successfully
  };

  // Return fallback if there's an error
  if (hasError && fallback) {
    return <>{fallback}</>;
  }

  // Return generic fallback for broken images
  if (hasError) {
    return (
      <div
        className={`flex items-center justify-center bg-gray-100 text-xs font-medium text-gray-500 dark:bg-gray-700 dark:text-gray-400 ${className}`}
      >
        TEXT
      </div>
    );
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (onClick && (e.key === "Enter" || e.key === " ")) {
      e.preventDefault();
      onClick();
    }
  };

  if (!isVideo) {
    // Render image thumbnail
    return (
      // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions
      <img
        src={src}
        alt={alt}
        className={`${className} ${onClick ? "cursor-pointer hover:opacity-75" : ""}`}
        onClick={onClick}
        onKeyDown={onClick ? handleKeyDown : undefined}
        role={onClick ? "button" : undefined}
        tabIndex={onClick ? 0 : undefined}
        loading="lazy"
        onError={handleImageError}
        onLoad={handleImageLoad}
      />
    );
  }

  // Render video thumbnail with play button overlay
  return (
    <div
      className={`relative ${className} ${onClick ? "cursor-pointer hover:opacity-75" : ""}`}
      onClick={onClick}
      onKeyDown={onClick ? handleKeyDown : undefined}
      role={onClick ? "button" : undefined}
      tabIndex={onClick ? 0 : undefined}
    >
      { }
      <video
        src={src}
        className="h-full w-full object-cover"
        preload="metadata"
        muted
        controls={false}
        disablePictureInPicture
        onError={handleImageError}
        onLoadedData={handleImageLoad}
      />
      {!hidePlayButton ? <div className="absolute inset-0 flex items-center justify-center">
          <div className="rounded-full bg-black bg-opacity-60 p-2 shadow-lg">
            <PlayIcon className="h-6 w-6 text-white drop-shadow-sm" />
          </div>
        </div> : null}
    </div>
  );
};

export default MediaThumbnail;

import { useState } from "react";

import { Button } from "~/components/ui/button";
import { Input } from "~/components/ui/input";
import type { Asset } from "~/features/assets/types";
interface AssetBrowserProps {
  assets: Asset[];
  onAssetsSelected: (selectedAssets: Asset[]) => void;
  onClose: () => void;
}

export default function AssetBrowser({
  assets,
  onAssetsSelected,
  onClose,
}: AssetBrowserProps) {
  const [selectedAssets, setSelectedAssets] = useState<string[]>([]);
  const [searchTerm, setSearchTerm] = useState("");

  const filteredAssets = assets.filter((asset) => {
    const searchLower = searchTerm.toLowerCase();
    return (
      asset.title?.toLowerCase().includes(searchLower) ||
      asset.content?.toLowerCase().includes(searchLower) ||
      asset.tags?.some((tag) => tag.toLowerCase().includes(searchLower))
    );
  });

  const handleAssetSelect = (assetId: string) => {
    setSelectedAssets((prev) =>
      prev.includes(assetId)
        ? prev.filter((id) => id !== assetId)
        : [...prev, assetId],
    );
  };

  const handleSelectAll = () => {
    if (selectedAssets.length === filteredAssets.length) {
      setSelectedAssets([]);
    } else {
      setSelectedAssets(filteredAssets.map((asset) => asset.id));
    }
  };

  const handleConfirmSelection = () => {
    const selectedAssetObjects = assets.filter((asset) =>
      selectedAssets.includes(asset.id),
    );
    onAssetsSelected(selectedAssetObjects);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="max-h-[90vh] w-full max-w-6xl overflow-hidden rounded-lg bg-white dark:bg-gray-800">
        <div className="border-b border-gray-200 p-6 dark:border-gray-700">
          <div className="flex items-center justify-between">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
              Select Assets
            </h2>
            <button
              onClick={onClose}
              className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
            >
              ×
            </button>
          </div>

          <div className="mt-4 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <div className="relative max-w-md flex-1">
              <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                <svg
                  className="h-5 w-5 text-gray-400"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                  />
                </svg>
              </div>
              <Input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
                placeholder="Search assets by title, content, or tags..."
              />
            </div>

            <div className="flex items-center gap-2">
              {filteredAssets.length > 0 ? (
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={handleSelectAll}
                >
                  {selectedAssets.length === filteredAssets.length
                    ? "Deselect All"
