import { connectToPrimalCache } from "~/features/cache/primalCache.server";
import type { RelatedEvent, PrimalEvent } from "~/features/giveaway/types";
/**
 * Fetches all engagement events for giveaway participation
 * Uses a hybrid approach:
 * - thread_view for replies, zaps, and aggregated stats (efficient)
 * - event_actions for individual likes and reposts (to include all participants)
 *
 * @param eventIds - Single event ID or array of event IDs
 * @returns Object containing relatedEvents array (kinds 1, 6, 7, 9735), count, and stats
 */
export const fetchGiveawayParticipants = async (
  eventIds: string | string[],
): Promise<{

  relatedEvents: RelatedEvent[];
  count: number;
  stats: {
    likes: number;
    reposts: number;
    zaps: number;
    satszapped: number;
    total: number;
  };
}> => {
  try {
    // Normalize input to array
    const eventIdArray = Array.isArray(eventIds) ? eventIds : [eventIds];

    if (eventIdArray.length === 0) {
      throw new Error("At least one event ID is required");
    }

    const allRelatedEvents: RelatedEvent[] = [];
    const aggregatedStats = {
      likes: 0,
      reposts: 0,
      zaps: 0,
      satszapped: 0,
      total: 0,
    };

    // Fetch all data for each event ID in parallel
    const fetchPromises = eventIdArray.map(async (eventId) => {
      const events: RelatedEvent[] = [];

      try {
        // 1. Fetch thread_view for replies, zaps, and stats
        const threadResponse = await connectToPrimalCache("thread_view", {
          event_id: eventId,
        });

        // Process thread_view response
        (threadResponse as PrimalEvent[]).forEach((item: PrimalEvent) => {
          if (!Array.isArray(item) || item[0] !== "EVENT" || !item[2]) return;

          const event = item[2];
          if (typeof event !== "object" || Array.isArray(event) || !("kind" in event)) return;

          // Extract zap receipts (kind 9735)
          if (event.kind === 9735) {
            events.push(event as RelatedEvent);

            // Extract zap amount for stats
            try {
              const tags = event.tags;
              const descriptionTag = Array.isArray(tags) ? tags.find(
                (tag: string[]) => Array.isArray(tag) && tag[0] === "description",
              ) : undefined;
              if (descriptionTag && Array.isArray(descriptionTag) && descriptionTag[1] && typeof descriptionTag[1] === "string") {
                const zapRequestParsed: unknown = JSON.parse(descriptionTag[1]);
                if (zapRequestParsed && typeof zapRequestParsed === "object" && !Array.isArray(zapRequestParsed) && "tags" in zapRequestParsed) {
                  const zapRequest = zapRequestParsed as { tags?: string[][] };
                  const amountTag = Array.isArray(zapRequest.tags) ? zapRequest.tags.find(
                    (tag: string[]) => Array.isArray(tag) && tag[0] === "amount",
                  ) : undefined;
                  if (amountTag && Array.isArray(amountTag) && amountTag[1] && typeof amountTag[1] === "string") {
                    const amount = parseInt(amountTag[1], 10);
                    if (!isNaN(amount)) {
                      aggregatedStats.satszapped += amount / 1000 || 0; // Convert millisats to sats
                    }
                  }
                }
              }
            } catch (_e) {
              // Error parsing zap amount - skip
            }
          }

          // Extract reply events (kind 1) that reference our event
          if (event.kind === 1 && "id" in event && event.id !== eventId) {
            const eTag = ("tags" in event && Array.isArray(event.tags)) ? event.tags.find(
              (tag: string[]) => tag[0] === "e" && tag[1] === eventId,
            ) : undefined;
            if (eTag) {
              events.push(event as RelatedEvent);
            }
          }

          // Extract stats from kind 10000100
          if (event.kind === 10000100 && event.content && typeof event.content === "string") {
            try {
              const statsContentParsed: unknown = JSON.parse(event.content);
              if (statsContentParsed && typeof statsContentParsed === "object" && !Array.isArray(statsContentParsed)) {
                const statsContent = statsContentParsed as { event_id?: string; likes?: number; reposts?: number; zaps?: number };
                if (statsContent.event_id === eventId) {
                  aggregatedStats.likes += typeof statsContent.likes === "number" ? statsContent.likes : 0;
                  aggregatedStats.reposts += typeof statsContent.reposts === "number" ? statsContent.reposts : 0;
                  aggregatedStats.zaps += statsContent.zaps || 0;
                  // Don't add satszapped here as we already calculated it from actual zap events
                }
              }
            } catch (_e) {
              // Error parsing stats - skip
            }
          }
        });

        // 2. Fetch individual likes (kind 7) via event_actions
        try {
          const likesResponse = await connectToPrimalCache("event_actions", {
            event_id: eventId,
            kind: 7,
          });

          const likeEvents = (likesResponse as PrimalEvent[])
            .filter(
              (item: PrimalEvent) =>
                Array.isArray(item) &&
                item[0] === "EVENT" &&
                item[2] &&
                typeof item[2] === "object" &&
                !Array.isArray(item[2]) &&
                "kind" in item[2] &&
                item[2].kind === 7,
            )
            .map((item: PrimalEvent) => item[2] as RelatedEvent);

          events.push(...likeEvents);
        } catch (error) {
          console.error(`Error fetching likes for event ${eventId}:`, error);
        }

        // 3. Fetch individual reposts (kind 6) via event_actions
        try {
          const repostsResponse = await connectToPrimalCache("event_actions", {
            event_id: eventId,
            kind: 6,
          });

          const repostEvents = (repostsResponse as PrimalEvent[])
            .filter(
              (item: PrimalEvent) =>
                Array.isArray(item) &&
                item[0] === "EVENT" &&
                item[2] &&
                typeof item[2] === "object" &&
                !Array.isArray(item[2]) &&
                "kind" in item[2] &&
                item[2].kind === 6,
            )
            .map((item: PrimalEvent) => item[2] as RelatedEvent);

          events.push(...repostEvents);
        } catch (error) {
          console.error(`Error fetching reposts for event ${eventId}:`, error);
        }
      } catch (error) {
        console.error(
          `Error fetching engagement data for event ${eventId}:`,
          error,
        );
      }

      return events;
    });

    // Wait for all fetches to complete
    const results = await Promise.all(fetchPromises);

    // Flatten results
    results.forEach((events) => {
      allRelatedEvents.push(...events);
    });

    // Update total count
    aggregatedStats.total = allRelatedEvents.length;

    return {
      relatedEvents: allRelatedEvents,
      count: allRelatedEvents.length,
      stats: aggregatedStats,
    };
  } catch (error) {
    console.error("Error fetching giveaway participants:", error);
    throw error;
  }
};

import { useNavigate } from "@remix-run/react";
import { useEffect, useState } from "react";

import { usePaymentPolling } from "./usePaymentPolling";
interface InvoiceData {
  invoice: string;
  paymentHash: string;
  amount: number;
  amountUsd: number;
  paymentId: string;
  expiresAt: string;
  planName: string;
  planId: string;
}

interface ActionData {
  success?: boolean;
  paid?: boolean;
  invoice?: string;
  paymentHash?: string;
  amount?: number;
  amountUsd?: number;
  paymentId?: string;
  expiresAt?: string;
  planName?: string;
  planId?: string;
  error?: string;
}

interface UsePlansStateProps {
  user: { id: string; isEnabled: boolean } | null;
  actionData: ActionData | null;
}

/**
 * Custom hook for managing plans page state and operations
 */
export function usePlansState({ user, actionData }: UsePlansStateProps) {
  const navigate = useNavigate();
  const [showInvoice, setShowInvoice] = useState(false);
  const [invoiceData, setInvoiceData] = useState<InvoiceData | null>(null);
  const [paymentComplete, setPaymentComplete] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<string | null>(null);
  const [timeRemaining, setTimeRemaining] = useState<number>(0);

  const { isPolling, startPaymentPolling } =
    usePaymentPolling({
      paymentId: invoiceData?.paymentId ?? null,
      onPaymentComplete: () => {
        setPaymentComplete(true);
        setShowInvoice(false);
      },
    });

  // Handle action data (invoice creation or payment status)
  useEffect(() => {
    if (actionData?.success) {
      // Handle paid plan payment completion
      if (actionData.paid) {
        setPaymentComplete(true);
        setShowInvoice(false);
        setTimeout(() => {
          navigate("/dashboard", { replace: true });
        }, 2000);
        return;
      }

      // Handle paid plan invoice creation
      if (actionData.invoice && actionData.invoice !== "free_plan") {
        // Convert ActionData to InvoiceData (all required fields must be present)
        if (actionData.paymentHash && actionData.amount !== undefined && actionData.amountUsd !== undefined && 
            actionData.paymentId && actionData.expiresAt && actionData.planName && actionData.planId) {
          const invoice: InvoiceData = {
            invoice: actionData.invoice,
            paymentHash: actionData.paymentHash,
            amount: actionData.amount,
            amountUsd: actionData.amountUsd,
            paymentId: actionData.paymentId,
            expiresAt: actionData.expiresAt,
            planName: actionData.planName,
            planId: actionData.planId,
          };
          setInvoiceData(invoice);
          setShowInvoice(true);
          // Set initial time remaining
          setTimeRemaining(new Date(actionData.expiresAt).getTime() - Date.now());
          // Start automatic payment status polling
          startPaymentPolling(actionData.paymentId);
        }
      }
    }
  }, [actionData, navigate, startPaymentPolling]);

  // Countdown timer effect
  useEffect(() => {
    if (showInvoice && invoiceData) {
      const timer = setInterval(() => {
        const remaining =
          new Date(invoiceData.expiresAt).getTime() - Date.now();
        setTimeRemaining(Math.max(0, remaining));

        if (remaining <= 0) {
          clearInterval(timer);
          setShowInvoice(false);
        }
      }, 1000);

      return () => clearInterval(timer);
    }
  }, [showInvoice, invoiceData]);

  // Function to handle plan selection
  const handlePlanSelection = (
    event: React.MouseEvent<HTMLButtonElement>,
    planId: string,
  ) => {
    if (!user) {
      // Prevent form submission and redirect to login if not authenticated
      event.preventDefault();
      navigate("/login", { replace: true });
      return false;
    }
    setSelectedPlan(planId);
    return true;
  };

  // Function to copy invoice to clipboard
  const copyToClipboard = (text: string) => {
    void navigator.clipboard.writeText(text);
  };

  return {
    showInvoice,
    invoiceData,
    paymentComplete,
    selectedPlan,
    timeRemaining,
    isPolling,
    setSelectedPlan,
    handlePlanSelection,
    copyToClipboard,
  };
}

/**
 * Subscription renewal service layer
 * Handles subscription checking and automatic renewal for cron jobs
 */

import { NWCClient } from "@getalby/sdk";
import { LN, USD } from "@getalby/sdk/lnclient";

import { getBitcoinRate } from "~/features/payments/btc.rate";
import { decrypt } from "~/lib/encryption.server";
import { createErrorResponse } from "~/lib/error-handler.server";
import { normalizeError } from "~/lib/errors";
import { sendNostrDirectMessage } from "~/lib/nostr.messenger.server";
import {
  createRenewalPayment,
  updateUserSubscription,
} from "~/models/payment.server";
import {
  disableUserAccount,
  getEnabledUsersWithSubscriptions,
} from "~/models/user.server";

interface RenewalResults {
  checked: number;
  expired: number;
  disabled: number;
  renewalAttempted: number;
  renewalSuccess: number;
  renewalFailed: number;
  errors: string[];
}

/**
 * Check and renew subscriptions for all users
 */
export async function checkAndRenewSubscriptions(): Promise<{
  success: boolean;
  timestamp: string;
} & RenewalResults> {
  const results: RenewalResults = {
    checked: 0,
    expired: 0,
    disabled: 0,
    renewalAttempted: 0,
    renewalSuccess: 0,
    renewalFailed: 0,
    errors: [],
  };

  try {
    // Get all enabled users with their subscriptions
    const users = await getEnabledUsersWithSubscriptions();

    results.checked = users.length;

    for (const user of users) {
      try {
        const subscription = user.Subscription;

        // Skip if user has no subscription
        if (!subscription) {
          continue;
        }

        // Skip lifetime plans
        if (subscription.Plan?.enableLifetimeAccess) {
          continue;
        }

        const now = new Date();
        const isExpired =
          subscription.currentPeriodEnd &&
          new Date(subscription.currentPeriodEnd) < now;

        if (isExpired) {
          results.expired++;

          // If user has NWC enabled, attempt automatic renewal
          if (user.nwcEnabled && user.encryptedNwc) {
            results.renewalAttempted++;

            try {
              if (!user.encryptedNwc) {
                throw new Error("User NWC credentials not available");
              }
              await attemptRenewal({ ...user, encryptedNwc: user.encryptedNwc }, {
                planId: subscription.planId,
                plan: subscription.plan,
                Plan: subscription.Plan ? {
                  name: subscription.Plan.name,
                  price: String(subscription.Plan.price),
                } : null,
              });
              results.renewalSuccess++;
            } catch (renewalError: unknown) {
              results.renewalFailed++;
              const errorMsg = `Failed to renew subscription for user ${user.id}: ${renewalError instanceof Error
                ? renewalError.message
                : String(renewalError)
                }`;
              results.errors.push(errorMsg);
              console.error(`[CRON] ${errorMsg}`, renewalError);

              // Disable account due to failed renewal
              await disableUserAccount(user.id);
              results.disabled++;

              // Send failure notification
              const planName = subscription.Plan?.name ?? "subscription";
              await sendRenewalNotification(
                user.npub,
                false,
                planName,
                `Your ${planName} subscription renewal failed. Please update your payment method to continue using the service.`,
              );
            }
          } else {
            // No NWC enabled, disable account
            await disableUserAccount(user.id);
            results.disabled++;

            // Send notification about expiration
            const planName = subscription.Plan?.name ?? "subscription";
            await sendRenewalNotification(
              user.npub,
              false,
              planName,
              `Your ${planName} subscription has expired. Please renew to continue using the service.`,
            );
          }
        }
      } catch (userError: unknown) {
        const errorMsg = `Error processing user ${user.id}: ${userError instanceof Error ? userError.message : String(userError)
          }`;
        results.errors.push(errorMsg);
        console.error(errorMsg, userError);
      }
    }

    return {
      success: true,
      timestamp: new Date().toISOString(),
      ...results,
    };
  } catch (error: unknown) {
    // Use centralized error handling but preserve results
    const normalizedError = normalizeError(error);
    const [errorResponse] = createErrorResponse(normalizedError);

    return {
      success: false,
      timestamp: new Date().toISOString(),
      ...results,
      errors: [...results.errors, typeof errorResponse.error === "string" ? errorResponse.error : errorResponse.error.message ?? String(errorResponse.error)],
    };
  }
}

/**
 * Attempt to renew a user's subscription
 */
async function attemptRenewal(
  user: { id: string; npub: string; encryptedNwc: string | null },
  subscription: {
    planId: string | null;
    plan: string | null;
    Plan: { name: string; price: string } | null;
  },
): Promise<void> {
  // Decrypt user's NWC credentials
  if (!user.encryptedNwc) {
    throw new Error("User NWC credentials not available");
  }
  const decryptedNwc = decrypt(user.encryptedNwc);

  // Get user's current plan
  const planId = subscription.planId ?? subscription.plan;
  if (!planId) {
    throw new Error("No plan ID found for subscription");
  }

  const plan = subscription.Plan;
  if (!plan) {
    throw new Error(`Plan ${planId} not found`);
  }

  // Skip free plans
  if (Number(plan.price) === 0) {
    // Renew free plan automatically
    const paymentId = `free_renewal_${Date.now()}_${user.id}`;
    await createRenewalPayment({
      paymentId,
      userId: user.id,
      amount: 0,
      amountUsd: 0,
      invoice: "free_plan_renewal",
      paymentHash: "free_plan_renewal",
      description: `Free plan renewal`,
    });
    await updateUserSubscription(user.id, planId, paymentId);

    // Send success message
    await sendRenewalNotification(
      user.npub,
      true,
      plan.name,
      "Free plan renewed successfully",
    );

    return;
  }

  // Create invoice using owner's NWC (to receive payment)
  const ownerNwc = process.env.OWNER_NWC;
  if (!ownerNwc) {
    throw new Error("Owner NWC credentials not configured");
  }

  const amountUsd = Number(plan.price);

  const ownerLn = new LN(ownerNwc);
  let invoiceRequest;
  try {
    // Create payment request using Alby SDK - owner receives payment
    invoiceRequest = await ownerLn.requestPayment(USD(amountUsd));
  } catch (error) {
    console.error("[CRON] Failed to request make_invoice", error);
    throw new Error(
      `Failed to create invoice: ${error instanceof Error ? error.message : String(error)
      }`,
    );
  }

  // Extract invoice, paymentHash and amount from the request object structure
  // Cast to unknown then to Record to access properties that may exist on ReceiveInvoice
  const requestAny: Record<string, unknown> = invoiceRequest && typeof invoiceRequest === "object" && !Array.isArray(invoiceRequest) ? invoiceRequest as unknown as Record<string, unknown> : {};
  const invoiceValue = requestAny.invoice;
  const invoiceString =
    typeof invoiceValue === "string"
      ? invoiceValue
      : (invoiceValue && typeof invoiceValue === "object" && !Array.isArray(invoiceValue) && "paymentRequest" in invoiceValue && typeof (invoiceValue as { paymentRequest?: unknown }).paymentRequest === "string"
          ? (invoiceValue as { paymentRequest: string }).paymentRequest
          : "");
  const invoiceObj = invoiceValue && typeof invoiceValue === "object" && !Array.isArray(invoiceValue) ? invoiceValue as Record<string, unknown> : null;
  const paymentHashString =
    typeof requestAny.paymentHash === "string"
      ? requestAny.paymentHash
      : (invoiceObj && "paymentHash" in invoiceObj
          ? String(invoiceObj.paymentHash)
          : "");

  // Extract amount in sats - try multiple possible locations
  let amountSats = 0;
  if (requestAny.amount && typeof requestAny.amount === "number") {
    amountSats = requestAny.amount;
  } else if (invoiceObj && "satoshi" in invoiceObj) {
    amountSats = Number(invoiceObj.satoshi) || 0;
  } else if (requestAny.satoshi && typeof requestAny.satoshi === "number") {
    amountSats = requestAny.satoshi;
  } else {
    // Parse the Lightning invoice to get the exact amount
    try {
      if (typeof invoiceString !== "string") {
        throw new Error("Invoice string is not a string");
      }
      const invoiceStr = invoiceString.toLowerCase();
      if (invoiceStr.startsWith("lnbc")) {
        // Extract amount from Lightning invoice - amounts are encoded after 'lnbc'
        const amountMatch = invoiceStr.match(
          /lnbc([0-9]+)([munp]?)/,
        );
        if (amountMatch && amountMatch[1]) {
          const baseAmount = parseInt(amountMatch[1], 10);
          const unit = amountMatch[2];

          // Convert to satoshis based on unit
          if (unit === "m") {
            amountSats = baseAmount * 100000; // 1 mBTC = 100,000 sats
          } else if (unit === "u") {
            amountSats = baseAmount * 100; // 1 µBTC = 100 sats
          } else if (unit === "n") {
            amountSats = Math.round(baseAmount * 0.1); // 1 nBTC = 0.1 sats
          } else if (unit === "p") {
            amountSats = Math.round(baseAmount * 0.0001); // 1 pBTC = 0.0001 sats
          } else {
            amountSats = baseAmount * 100000000; // 1 BTC = 100,000,000 sats
          }
        }
      }
    } catch (error) {
      console.error(
        "[CRON] Error parsing Lightning invoice amount:",
        error,
      );
    }

    // If we still don't have an amount, use live Bitcoin rate as fallback
    if (amountSats === 0) {
      try {
        amountSats = await getBitcoinRate(amountUsd);
      } catch (error) {
        console.error(
          "[CRON] Failed to fetch Bitcoin rate, using fallback:",
          error,
        );
        // Fallback approximation: $1 ≈ 2,500 sats (at $40,000 per BTC)
        amountSats = Math.round(amountUsd * 2500);
      }
    }
  }

  if (!invoiceString || !paymentHashString) {
    console.error(
      "[CRON] Failed to extract invoice or paymentHash from request:",
      {
        invoiceString,
        paymentHashString,
        requestStructure: Object.keys(invoiceRequest as unknown as Record<string, unknown>),
      },
    );
    throw new Error(
      "Invalid response from payment provider - missing invoice or paymentHash",
    );
  }

  // Use user's NWC to pay the invoice
  const nwcClient = new NWCClient({
    nostrWalletConnectUrl: decryptedNwc,
  });

  // Pay the invoice using user's NWC
  const paymentResult = await nwcClient.payInvoice({
    invoice: invoiceString,
  });

  // Extract payment hash from result
  const paymentResultObj = paymentResult && typeof paymentResult === "object" && !Array.isArray(paymentResult) ? paymentResult as Record<string, unknown> : {};
  const preimageValue = paymentResultObj.preimage;
  const paymentHash =
    (typeof preimageValue === "string" ? preimageValue : null) ??
    paymentHashString ??
    `payment_${Date.now()}`;

  // Create payment record
  const paymentId = `renewal_${planId}_${Date.now()}_${user.id}`;
  await createRenewalPayment({
    paymentId,
    userId: user.id,
    amount: amountSats,
    amountUsd,
    invoice: invoiceString,
    paymentHash: paymentHash,
    description: `${plan.name} plan renewal`,
  });

  // Update subscription
  await updateUserSubscription(user.id, planId, paymentId);

  // Send success notification
  await sendRenewalNotification(
    user.npub,
    true,
    plan.name,
    `Your ${plan.name} subscription has been renewed successfully. Thank you!`,
  );
}

/**
 * Send renewal notification via Nostr DM
 */
async function sendRenewalNotification(
  pubkeyHex: string,
  _success: boolean,
  _planName: string,
  message: string,
): Promise<void> {
  try {
    await sendNostrDirectMessage(pubkeyHex, message);
  } catch (error) {
    console.error(`[CRON] Failed to send notification to ${pubkeyHex}:`, error);
    // Don't throw - notification failure shouldn't break the cron job
  }
}

import { redirect } from "@remix-run/node";

import {
  hasFeatureAccess,
  isNewUserWithoutSubscription,
  type FeatureName,
  type SubscriptionData,
} from "~/features/payments/types";
import { prisma } from "~/lib/prisma.server";
import { getUserSubscription } from "~/models/payment.server";

/**
 * Check if a user has access to a specific feature and redirect if not
 */
export async function requireFeatureAccess(
  userId: string,
  feature: FeatureName,
  redirectTo = "/plans",
): Promise<SubscriptionData> {
  // Get user's enabled status and subscription
  const [user, currentSubscription] = await Promise.all([
    prisma.user.findUnique({
      where: { id: userId },
      select: { isEnabled: true },
    }),
    getUserSubscription(userId),
  ]);

  // Check if user exists and is enabled
  if (!user?.isEnabled) {
    throw redirect(redirectTo);
  }

  const subscriptionData: SubscriptionData = {
    user: { id: userId, isEnabled: user.isEnabled },
    currentSubscription:
      currentSubscription && currentSubscription.planId
        ? {
            planId: currentSubscription.planId,
            status: currentSubscription.status,
            Plan: currentSubscription.Plan
              ? {
                  name: currentSubscription.Plan.name,
                  id: currentSubscription.Plan.id,
                }
              : undefined,
          }
        : null,
  };

  // Check if user has access to the feature
  if (!hasFeatureAccess(subscriptionData.currentSubscription, feature)) {
    throw redirect(redirectTo);
  }

  return subscriptionData;
}

/**
 * Check if user is new without subscription and redirect if accessing restricted routes
 */
export async function checkNewUserAccess(
  userId: string,
  redirectTo = "/plans",
): Promise<SubscriptionData> {
  // Get user's enabled status and subscription
  const [user, currentSubscription] = await Promise.all([
