/**
 * Server-side action handlers for bulk posts
 * Extracted from dashboard.bulkposts.tsx
 */
import { json, redirect } from "@remix-run/node";

import { requireUserId } from "~/features/auth/session.server";
import type { NostrEvent, SignedEvent } from "~/features/nostr/types";
import { resolveQueueTypeId } from "~/features/posts/services/queue-type-resolver.server";
import { logInfo } from "~/lib/error-logger.server";
import { createPost, updatePost } from "~/models/post.commands.server";
import { isVideoUrl } from "~/utils/media-helpers";
/**
 * Upload result from client-side upload system
 */
interface UploadResult {
    success: boolean;
    file?: {
        url: string;
        size: number;
        name: string;
        extension: string;
        sha256?: string;
        mimeType?: string;
        provider: "S3" | "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR";
    };
    error?: string;
}

/**
 * Handle file upload preview results from client-side upload system
 */
export async function handleUploadImagesPreview(formData: FormData) {
    try {
        const uploadResultsStrRaw = formData.get("uploadResults");
        const uploadResultsStr = typeof uploadResultsStrRaw === "string" ? uploadResultsStrRaw : null;
        if (!uploadResultsStr) {
            const { ValidationError } = await import("~/lib/errors");
            throw new ValidationError("Missing uploadResults");
        }

        let uploadResults: UploadResult[];
        try {
            const parsed: unknown = JSON.parse(uploadResultsStr);
            if (Array.isArray(parsed)) {
                uploadResults = parsed as unknown as UploadResult[];
            } else {
                throw new Error("uploadResults must be an array");
            }
        } catch (parseError) {
            const { ValidationError } = await import("~/lib/errors");
            throw new ValidationError("Invalid uploadResults JSON format", {
                error: parseError instanceof Error ? parseError.message : String(parseError),
            });
        }

        const scheduledDates = formData.getAll("scheduledDates");
        const queueTypes = formData.getAll("queueTypes");

        const fileUrls = uploadResults.map((result: UploadResult, index: number) => ({
            fileUrl: result.file?.url ?? "",
            scheduledFor: scheduledDates[index],
            queueType: queueTypes[index],
        }));

        return json({ success: true, fileUrls });
    } catch (error) {
        const { handleActionError } = await import("~/lib/error-handler.server");
        return handleActionError(error);
    }
}

/**
 * Handle sign and schedule posts action
 */
export async function handleSignAndSchedule(
    formData: FormData,
    userId: string,
    mode: string | null
) {
    try {
        // Parse signed events with error handling
        let signedEvents: SignedEvent[];
        try {
            const signedEventsRaw = formData.getAll("signedEvents");
            signedEvents = signedEventsRaw
                .map((event) => {
                    const parsed: unknown = typeof event === "string" ? JSON.parse(event) : null;
                    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
                        return parsed as unknown as SignedEvent;
                    }
                    throw new Error("Invalid signed event format");
                });
        } catch (parseError) {
            const { ValidationError } = await import("~/lib/errors");
            throw new ValidationError("Invalid signedEvents JSON format", {
                error: parseError instanceof Error ? parseError.message : String(parseError),
            });
        }

        let nostrEvents: NostrEvent[];
        try {
            const nostrEventsRaw = formData.getAll("nostrEvent");
            nostrEvents = nostrEventsRaw
                .map((event) => {
                    const parsed: unknown = typeof event === "string" ? JSON.parse(event) : null;
                    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
                        return parsed as unknown as NostrEvent;
                    }
                    throw new Error("Invalid nostr event format");
                });
        } catch (parseError) {
            const { ValidationError } = await import("~/lib/errors");
            throw new ValidationError("Invalid nostrEvent JSON format", {
                error: parseError instanceof Error ? parseError.message : String(parseError),
            });
        }

        let captions: string[];
        try {
            const captionsRaw = formData.getAll("caption");
            captions = captionsRaw
                .map((caption) => {
                    const parsed: unknown = typeof caption === "string" ? JSON.parse(caption) : null;
                    if (typeof parsed === "string") {
                        return parsed;
                    }
                    if (Array.isArray(parsed)) {
                        return parsed.join(" ");
                    }
                    return String(parsed ?? "");
                });
        } catch (parseError) {
            const { ValidationError } = await import("~/lib/errors");
            throw new ValidationError("Invalid caption JSON format", {
                error: parseError instanceof Error ? parseError.message : String(parseError),
            });
        }

        let fileUrls: string[];
        try {
            const fileUrlValues = formData.getAll("fileUrl");
            fileUrls = fileUrlValues.map((url) => {
                const urlStr = typeof url === "string" ? url : String(url);
                const parsed: unknown = JSON.parse(urlStr);
                return Array.isArray(parsed) ? parsed.filter((item): item is string => typeof item === "string") : [];
            }).flat();
        } catch (parseError) {
            const { ValidationError } = await import("~/lib/errors");
            throw new ValidationError("Invalid fileUrl JSON format", {
                error: parseError instanceof Error ? parseError.message : String(parseError),
            });
        }

    const queueTypes = formData.getAll("queueType");
    const isRecyclableFlags = formData.getAll("isRecyclable");
    const originalPostIds = formData
        .getAll("originalPostId")
        .filter((id) => id && id !== "");


    await Promise.all(
        signedEvents.map(async (signedEvent, index) => {
            // Parse content assuming format: "caption imageUrl1 imageUrl2 ..."
            let content = "";
            if (signedEvent.content && typeof signedEvent.content === "string") {
                const contentParts = signedEvent.content.split(" ");
                content = contentParts
                    .filter((part: string) => !part.startsWith("http"))
                    .join(" ");
            }

            // For recycled posts, use the caption as content if content is empty
            if (!content && captions[index]) {
                content = captions[index];
            }

            const fileUrl = fileUrls[index];
            const tags = signedEvent.tags.map((tagArray: string[]) => tagArray[1]);
            const queueType = (queueTypes[index] as string) || "unassigned";
            const isRecyclableFlag = isRecyclableFlags[index];
            const isRecyclable =
                isRecyclableFlag === "true" ||
                String(isRecyclableFlag).toLowerCase() === "true";

            // Enhanced detection for quote posts
            const hasEventTags = signedEvent.tags.some(
                (tag: string[]) => tag[0] === "e" && tag[3] === "mention"
            );
            const isQuotePost =
                mode === "quote" ||
                (signedEvent.kind === 1 && hasEventTags);
            logInfo("Calculated isQuotePost", {
                isQuotePost,
                mode,
                hasEventTags,
                userId,
            });

            // Determine post type based on file URL
            const isVideo = isVideoUrl(fileUrl);
            const postType = isVideo ? "VIDEO" : "IMAGE";

            // Resolve queue type ID in feature layer (business logic)
            const resolvedQueueTypeId = await resolveQueueTypeId(userId, null, queueType);

            const post = await createPost({
                userId,
                content,
                fileUrl: [fileUrl],
                scheduledFor: signedEvent.created_at.toString(),
                nostrEventId: signedEvent.id,
                signedEvent: signedEvent,
                nostrEvent: nostrEvents[index],
                tags: tags,
                caption: captions[index],
                isScheduled: true,
                isPosted: false,
                postType: postType,
                queueTypeId: resolvedQueueTypeId,
                repost: signedEvent.kind === 6, // Mark as repost if it's kind 6
                isQuotedPost: isQuotePost, // Use the calculated value
                isRecyclable,
            });

            logInfo("Created post", {
                postId: post?.id,
                index,
                queueTypeId: post?.queueTypeId,
                userId,
            });
            return post;
        })
    );

        // If this is a recycle mode (posts have original post IDs), mark original posts as non-recyclable
        if (mode === "recycle" && originalPostIds.length > 0) {
            await markOriginalPostsAsNonRecyclable(originalPostIds as string[], userId);
        }

        return redirect(`/dashboard/scheduled`);
    } catch (error) {
        const { handleActionError } = await import("~/lib/error-handler.server");
        return handleActionError(error);
    }
}

/**
 * Handle save as draft action
 */
export async function handleSaveAsDraft(
    formData: FormData,
    userId: string,
    mode: string | null
) {
    try {
        let fileUrls: string[];
        try {
            const fileUrlsRaw = formData.getAll("fileUrl");
            fileUrls = fileUrlsRaw.map((url) => {
                const parsed: unknown = typeof url === "string" ? JSON.parse(url) : null;
                    if (Array.isArray(parsed)) {
                        return parsed as unknown as string[];
                }
                return [];
            }).flat();
        } catch (parseError) {
            const { ValidationError } = await import("~/lib/errors");
            throw new ValidationError("Invalid fileUrl JSON format", {
                error: parseError instanceof Error ? parseError.message : String(parseError),
            });
        }

        let captions: string[];
        try {
            const captionsRaw = formData.getAll("caption");
            captions = captionsRaw
                .map((caption) => {
                    const parsed: unknown = typeof caption === "string" ? JSON.parse(caption) : null;
                    if (typeof parsed === "string") {
                        return parsed;
                    }
                    if (Array.isArray(parsed)) {
                        return parsed.join(" ");
                    }
                    return String(parsed ?? "");
                });
        } catch (parseError) {
            const { ValidationError } = await import("~/lib/errors");
            throw new ValidationError("Invalid caption JSON format", {
                error: parseError instanceof Error ? parseError.message : String(parseError),
            });
        }
    const queueTypes = formData.getAll("queueType");
    const isRecyclableFlags = formData.getAll("isRecyclable");
    const originalPostIds = formData
        .getAll("originalPostId")
        .filter((id) => id && id !== "");

    await Promise.all(
        fileUrls.map(async (fileUrl, index) => {
            const caption = captions[index];
            const queueType = (queueTypes[index] as string) || "unassigned";
            const isRecyclableFlag = isRecyclableFlags[index];
            const isRecyclable =
                isRecyclableFlag === "true" ||
                String(isRecyclableFlag).toLowerCase() === "true";

            // Determine post type based on file URL
            const isVideo = isVideoUrl(fileUrl);
            const postType = isVideo ? "VIDEO" : "IMAGE";

            // Resolve queue type ID in feature layer (business logic)
            const resolvedQueueTypeId = await resolveQueueTypeId(userId, null, queueType);

            const post = await createPost({
                userId,
                content: caption,
                caption: caption,
                fileUrl: [fileUrl],
                isScheduled: false,
                isPosted: false,
                postType: postType,
                tags: [],
                queueTypeId: resolvedQueueTypeId,
                draft: true,
                isRecyclable,
            });

            return post;
        })
    );

        // If this is a recycle mode (posts have original post IDs) and user saved as draft,
        // we might still want to mark them as non-recyclable to prevent confusion
        if (mode === "recycle" && originalPostIds.length > 0) {
            await markOriginalPostsAsNonRecyclable(originalPostIds as string[], userId, true);
        }

        return redirect(`/dashboard/drafts`);
    } catch (error) {
        const { handleActionError } = await import("~/lib/error-handler.server");
        return handleActionError(error);
    }
}

/**
 * Mark original posts as non-recyclable after recycling/reposting
 */
async function markOriginalPostsAsNonRecyclable(
    originalPostIds: string[],
    userId: string,
    isDraft = false,
) {
    logInfo(`Marking original posts as non-recyclable${isDraft ? " (draft)" : ""}`, {
        originalPostIds,
        userId,
        isDraft,
    });

    // Update all original posts to mark them as non-recyclable
    await Promise.all(
        originalPostIds.map(async (originalPostId) => {
            try {
                await updatePost({
                    id: originalPostId,
                    userId,
                    data: { isRecyclable: false },
                });
                logInfo(`Marked post as non-recyclable${isDraft ? " (draft)" : ""}`, {
                    postId: originalPostId,
                    userId,
                    isDraft,
                });
            } catch (error) {
                // Log but don't throw - marking as non-recyclable is non-critical
                const { logWarning } = await import("~/lib/error-logger.server");
                logWarning(`Failed to mark post as non-recyclable`, {
                    postId: originalPostId,
                    userId,
                    isDraft,
                    error: error instanceof Error ? error.message : String(error),
                });
            }
        })
    );
}

/**
 * Main action handler for bulk posts
 */
export async function bulkPostsAction({ request }: { request: Request }) {
    try {
        const userId = await requireUserId(request);
        if (!userId) {
            const { AuthenticationError } = await import("~/lib/errors");
            throw new AuthenticationError("User not authenticated");
        }

        const url = new URL(request.url);
        const mode = url.searchParams.get("mode");

        const formData = await request.formData();
        const _action = formData.get("_action");

        // Handle file upload results from client-side upload system
        if (_action === "_upload_images_preview") {
            return handleUploadImagesPreview(formData);
        }

        // Sign and schedule posts
        if (_action === "sign_and_schedule") {
            return handleSignAndSchedule(formData, userId, mode);
        }

        // Save as draft
        if (_action === "save_as_draft") {
            return handleSaveAsDraft(formData, userId, mode);
        }

        const { ValidationError } = await import("~/lib/errors");
        throw new ValidationError("Invalid action", { action: _action });
    } catch (error) {
        const { handleActionError } = await import("~/lib/error-handler.server");
        return handleActionError(error);
    }
}

/**
 * Utility functions for combining Post and LongFormPost data
 * Used by the "All" tab to display both types of content together
 */

import type { CombinedContent, PostData, LongFormPostData } from "~/features/posts/types";
// Re-export the type
export type { CombinedContent } from "~/features/posts/types";

/**
 * Converts a Post to CombinedContent format
 */
export function nullToUndefined<T>(value: T | null): T | undefined {
  return value ?? undefined;
}

export function postToCombinedContent(post: PostData): CombinedContent {
  return {
    id: post.id,
    type: "post",
    caption: nullToUndefined(post.caption),
    content: nullToUndefined(post.content),
    fileUrl: post.fileUrl,
    scheduledFor: nullToUndefined(post.scheduledFor),
    postedAt: nullToUndefined(post.postedAt),
    createdAt: post.createdAt,
    updatedAt: post.updatedAt,
    isScheduled: post.isScheduled,
    isPosted: post.isPosted,
    draft: post.draft,
    status: post.status,
    queueType: post.queueType && typeof post.queueType === "object" && "id" in post.queueType && "name" in post.queueType ? {
      id: typeof post.queueType.id === "string" ? post.queueType.id : String(post.queueType.id ?? ""),
      name: typeof post.queueType.name === "string" ? post.queueType.name : String(post.queueType.name ?? ""),
      color: "color" in post.queueType && post.queueType.color ? (typeof post.queueType.color === "string" ? post.queueType.color : String(post.queueType.color)) : undefined,
    } : undefined,
    queueTypeId: nullToUndefined(post.queueTypeId),
    userId: post.userId,
    tags: post.tags,
    signedEvent: nullToUndefined(post.signedEvent),
    nostrEvent: nullToUndefined(post.nostrEvent),
    nostrEventId: nullToUndefined(post.nostrEventId),
    manual_override: post.manual_override,
    postType: post.postType,
    repost: post.repost,
    isQuotedPost: post.isQuotedPost,
    isRecyclable: post.isRecyclable,
    templateId: nullToUndefined(post.templateId),
    originalData: post,
  };
}

/**
 * Converts a LongFormPost to CombinedContent format
 */
export function longFormPostToCombinedContent(
  longFormPost: LongFormPostData,
): CombinedContent {
  return {
    id: longFormPost.id,
    type: "longform",
    title: nullToUndefined(longFormPost.title),
    content: nullToUndefined(longFormPost.content),
    summary: nullToUndefined(longFormPost.summary),
    image: nullToUndefined(longFormPost.image),
    scheduledFor: nullToUndefined(longFormPost.scheduledFor),
    publishedAt: nullToUndefined(longFormPost.publishedAt),
    postedAt: nullToUndefined(longFormPost.publishedAt), // Map publishedAt to postedAt for consistency
    createdAt: longFormPost.createdAt,
    updatedAt: longFormPost.updatedAt,
    isScheduled: longFormPost.isScheduled,
    isPublished: longFormPost.isPublished,
    isPosted: longFormPost.isPublished, // Map isPublished to isPosted for consistency
    draft: longFormPost.draft,
    status: longFormPost.status,
    queueType: longFormPost.queueType ? {
      id: longFormPost.queueType.id,
      name: longFormPost.queueType.name,
      color: longFormPost.queueType.color ?? undefined,
    } : undefined,
    queueTypeId: nullToUndefined(longFormPost.queueTypeId),
    userId: longFormPost.userId,
    tags: longFormPost.tags,
    signedEvent: nullToUndefined(longFormPost.signedEvent),
    nostrEvent: nullToUndefined(longFormPost.nostrEvent),
    nostrEventId: nullToUndefined(longFormPost.nostrEventId),
    originalData: longFormPost,
  };
}

/**
 * Combines posts and longform posts into a single sorted array
 */
export function combineContent(
  posts: PostData[] = [],
  longFormPosts: LongFormPostData[] = [],
  sortBy = "createdAt",
  sortDirection: "asc" | "desc" = "desc",
): CombinedContent[] {
  const combinedPosts = posts.map(postToCombinedContent);
  const combinedLongForm = longFormPosts.map(longFormPostToCombinedContent);
  const combined = [...combinedPosts, ...combinedLongForm];

  // Sort the combined array
  return combined.sort((a, b) => {
    let aValue = 0;
    let bValue = 0;

    if (sortBy === "scheduledFor") {
      // Handle Unix timestamps for scheduledFor
      const aScheduled = a.scheduledFor;
      const bScheduled = b.scheduledFor;
      aValue = aScheduled ? (typeof aScheduled === "string" ? parseInt(aScheduled, 10) : typeof aScheduled === "number" ? aScheduled : 0) * 1000 : 0;
      bValue = bScheduled ? (typeof bScheduled === "string" ? parseInt(bScheduled, 10) : typeof bScheduled === "number" ? bScheduled : 0) * 1000 : 0;
    } else if (sortBy === "postedAt" || sortBy === "publishedAt") {
      // Handle dates for postedAt/publishedAt
      const aPosted = a.postedAt;
      const bPosted = b.postedAt;
      aValue = aPosted ? new Date(aPosted).getTime() : 0;
      bValue = bPosted ? new Date(bPosted).getTime() : 0;
    } else if (sortBy === "createdAt" || sortBy === "updatedAt") {
      // Handle dates for createdAt/updatedAt
      const aDate = a[sortBy];
      const bDate = b[sortBy];
      aValue = aDate ? new Date(aDate).getTime() : 0;
      bValue = bDate ? new Date(bDate).getTime() : 0;
    }

    if (sortDirection === "asc") {
      return aValue < bValue ? -1 : aValue > bValue ? 1 : 0;
    } else {
      return aValue > bValue ? -1 : aValue < bValue ? 1 : 0;
    }
  });
}

/**
 * Filters combined content by search term
 */
export function filterCombinedContent(
  content: CombinedContent[],
  searchTerm: string,
): CombinedContent[] {
  if (!searchTerm) return content;

  const searchLower = searchTerm.toLowerCase();
  return content.filter((item) => {
    return (
      item.caption?.toLowerCase().includes(searchLower) ||
      item.title?.toLowerCase().includes(searchLower) ||
      item.content?.toLowerCase().includes(searchLower) ||
      item.summary?.toLowerCase().includes(searchLower)
    );
  });
}

import { useFetcher } from "@remix-run/react";
import { useState } from "react";

import { ContentBulkActions } from "~/features/posts/components/ContentBulkActions";
import { ContentSearchBar } from "~/features/posts/components/ContentSearchBar";
import { ContentTableHeader } from "~/features/posts/components/ContentTableHeader";
import { ContentTableRow } from "~/features/posts/components/ContentTableRow";
import type {
  CombinedContent,
  LongFormPostData,
  PostData,
  PostFetcher,
} from "~/features/posts/types";

interface AllContentListingProps {
  content: CombinedContent[];
  type: "scheduled" | "draft" | "posted";
  searchTerm: string;
  onSearchChange: (term: string) => void;
  userTimezone?: string;
  onPostSelect?: (content: CombinedContent) => void;
  selectedItems?: Set<string>;
  onToggleSelection?: (id: string) => void;
  onToggleSelectAll?: () => void;
  showBulkActions?: boolean;
  onBulkDelete?: () => void;
  bulkDeleteState?: string;
  // Advanced actions for posted content
  individualRepostFetcher?: PostFetcher;
  longformRepostFetcher?: PostFetcher;
  longformQuoteFetcher?: PostFetcher;
  onBulkRepost?: () => void;
  onBulkScheduledRepost?: () => void;
  onBulkQuote?: () => void;
  repostFetcher?: PostFetcher;
  // Edit and reschedule actions for scheduled content
  onEditPost?: (post: PostData | LongFormPostData) => void;
  onReschedulePost?: (post: PostData | LongFormPostData) => void;
}

export default function AllContentListing({
  content,
  type,
  searchTerm,
  onSearchChange,
  userTimezone,
  onPostSelect,
  selectedItems = new Set(),
  onToggleSelection,
  onToggleSelectAll,
  showBulkActions = false,
  onBulkDelete,
  bulkDeleteState = "idle",
  // Advanced actions
  individualRepostFetcher,
  longformRepostFetcher,
  longformQuoteFetcher,
  onBulkRepost,
  onBulkScheduledRepost,
  onBulkQuote,
  repostFetcher,
  // Edit and reschedule actions
  onEditPost,
  onReschedulePost,
}: AllContentListingProps) {
  const deleteFetcher = useFetcher<{ success?: boolean; error?: string; needsSigning?: boolean; post?: PostData | LongFormPostData }>();
  const [sortConfig, setSortConfig] = useState<{
    key: string;
    direction: "asc" | "desc";
  }>({
    key:
      type === "posted"
        ? "postedAt"
        : type === "scheduled"
          ? "scheduledFor"
          : "createdAt",
    direction: "desc",
  });

  const requestSort = (key: string) => {
    setSortConfig((current) => ({
      key,
      direction:
        current.key === key && current.direction === "asc" ? "desc" : "asc",
    }));
  };

  const sortedContent = [...content].sort((a, b) => {
    let aValue: number | string;
    let bValue: number | string;

    if (sortConfig.key === "scheduledFor") {
      const aScheduled = a.scheduledFor;
      const bScheduled = b.scheduledFor;
      aValue = aScheduled && typeof aScheduled === "string" ? parseInt(aScheduled, 10) * 1000 : 0;
      bValue = bScheduled && typeof bScheduled === "string" ? parseInt(bScheduled, 10) * 1000 : 0;
    } else if (sortConfig.key === "postedAt") {
      const aPosted = a.postedAt;
      const bPosted = b.postedAt;
      aValue = aPosted ? new Date(aPosted).getTime() : 0;
      bValue = bPosted ? new Date(bPosted).getTime() : 0;
    } else if (
      sortConfig.key === "createdAt" ||
      sortConfig.key === "updatedAt"
    ) {
      const aKey = a[sortConfig.key];
      const bKey = b[sortConfig.key];
      aValue = aKey ? new Date(aKey).getTime() : 0;
      bValue = bKey ? new Date(bKey).getTime() : 0;
    } else {
      const aKey = a[sortConfig.key as keyof CombinedContent];
      const bKey = b[sortConfig.key as keyof CombinedContent];
      aValue = aKey ? (typeof aKey === "string" ? aKey : String(aKey)) : "";
      bValue = bKey ? (typeof bKey === "string" ? bKey : String(bKey)) : "";
    }

    if (aValue < bValue) {
      return sortConfig.direction === "asc" ? -1 : 1;
    }
    if (aValue > bValue) {
      return sortConfig.direction === "asc" ? 1 : -1;
    }
    return 0;
  });

  const filteredContent = sortedContent.filter(
    (item) =>
      item.caption?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.content?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.summary?.toLowerCase().includes(searchTerm.toLowerCase()),
  );


  return (
    <div>
      <ContentSearchBar searchTerm={searchTerm} onSearchChange={onSearchChange} />

      {showBulkActions ? (
        <ContentBulkActions
          type={type}
          selectedCount={selectedItems.size}
          onBulkDelete={onBulkDelete ?? (() => {})}
          onBulkRepost={onBulkRepost}
          onBulkScheduledRepost={onBulkScheduledRepost}
          onBulkQuote={onBulkQuote}
          bulkDeleteState={bulkDeleteState}
          repostFetcher={repostFetcher}
        />
      ) : null}

      {/* Content Table */}
      <div className="min-w-full overflow-x-auto rounded border border-gray-200 bg-white dark:border-gray-700 dark:bg-gray-800">
        <table className="min-w-full whitespace-nowrap align-middle text-sm">
          <ContentTableHeader
            type={type}
            showBulkActions={showBulkActions}
            sortConfig={sortConfig}
            filteredContentLength={filteredContent.length}
            selectedItemsSize={selectedItems.size}
            onToggleSelectAll={onToggleSelectAll}
            onRequestSort={requestSort}
          />
          <tbody>
            {filteredContent.map((item) => (
              <ContentTableRow
                key={`${item.type}-${item.id}`}
                item={item}
                type={type}
                userTimezone={userTimezone}
                showBulkActions={showBulkActions}
                selectedItems={selectedItems}
                onToggleSelection={onToggleSelection}
                onPostSelect={onPostSelect}
                onEditPost={onEditPost}
                onReschedulePost={onReschedulePost}
                deleteFetcher={deleteFetcher as unknown as PostFetcher}
                individualRepostFetcher={individualRepostFetcher}
                longformRepostFetcher={longformRepostFetcher}
                longformQuoteFetcher={longformQuoteFetcher}
              />
            ))}
          </tbody>
        </table>
      </div>

      {filteredContent.length === 0 ? (
        <div className="mt-8 text-center">
          <p className="text-gray-500 dark:text-gray-400">No content found.</p>
        </div>
      ) : null}
    </div>
  );
}

import { HashtagPresetToggle } from "~/components/dashboard/HashtagPresetToggle";
