import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

import { EditLongFormFormFields } from "./EditLongFormFormFields";
import { EditorJSStyles } from "./EditorJSStyles";
import { EditPostFormFields } from "./EditPostFormFields";
import { useEditPostModal } from "~/features/posts/hooks/useEditPostModal";
import type { PostData, LongFormPostData, QueueType, HashTagPreset, UserData } from "~/features/posts/types";
import { prepareEditPostSubmission } from "~/features/posts/utils/editPostSubmit.client";
interface EditPostModalProps {
  post: PostData | LongFormPostData;
  onClose: () => void;
  onConfirm: () => void;
  user?: UserData;
  queueTypes?: QueueType[];
  hashTagPresets?: HashTagPreset[];
}

interface FetcherData {
  success?: boolean;
  needsSigning?: boolean;
  error?: string;
}

export function EditPostModal({
  post,
  onClose,
  onConfirm,
  user,
  queueTypes = [],
  hashTagPresets = [],
}: EditPostModalProps) {
  const fetcher = useFetcher<FetcherData>();
  const [isSigningEvent, setIsSigningEvent] = useState(false);
  const [signingError, setSigningError] = useState<string | null>(null);

  // Determine if this is a longform post
  const isLongform = "title" in post && post.title !== undefined;

  // Use custom hook for form state management
  const {
    caption,
    setCaption,
    selectedQueueType,
    setSelectedQueueType,
    title,
    setTitle,
    summary,
    setSummary,
    content,
    setContent: _setContent,
    image,
    setImage,
    scheduledFor,
    setScheduledFor,
    existingImages,
    newFiles,
    isUploadingImages,
    setIsUploadingImages,
    useHashtagPresets,
    setUseHashtagPresets,
    selectedHashtagPresetId,
    selectedHashtagPresetTags,
    manualHashtags,
    setManualHashtags,
    editorReady,
    handleFileChange,
    removeExistingImage,
    removeNewFile,
    handleHashtagPresetSelect,
    formatDateTimeForInput,
  } = useEditPostModal({
    post,
    user,
    hashTagPresets,
    isLongform,
  });


  useEffect(() => {
    const dataRaw = fetcher.data;
    const data = dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw) ? dataRaw as { success?: unknown; needsSigning?: unknown; error?: unknown } : null;
    if (data && typeof data.success === "boolean" && data.success) {
      if (data.needsSigning && typeof data.needsSigning === "boolean" && data.needsSigning) {
        return; // Keep modal open for re-signing
      }
      onConfirm();
    }
    if (data && "error" in data && typeof data.error === "string") {
      setSigningError(data.error);
    }
  }, [fetcher.data, onConfirm]);

  const handleSubmit = async () => {
    if (!post) return;

    try {
      setIsSigningEvent(true);
      setSigningError(null);
      setIsUploadingImages(true);

      const formData = await prepareEditPostSubmission({
        post,
        isLongform,
        caption,
        title,
        summary,
        content,
        image,
        existingImages,
        newFiles,
        selectedHashtagPresetTags,
        manualHashtags,
        useHashtagPresets,
        selectedQueueType,
        selectedHashtagPresetId,
        scheduledFor,
        user,
      });

      setIsUploadingImages(false);
      fetcher.submit(formData, { method: "post" });
    } catch (error: unknown) {
      console.error("Error re-signing event:", error);
      setIsSigningEvent(false);
      setIsUploadingImages(false);
      const errorMessage = error instanceof Error 
        ? error.message 
        : "Failed to sign event. Please try again.";
      setSigningError(errorMessage);
    }
  };

  if (!post) return null;

  return (
    <>
      {/* EditorJS Custom Styles */}
      {isLongform ? <EditorJSStyles /> : null}

      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
        <div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-lg bg-white shadow-xl dark:bg-gray-800">
          <div className="p-6">
            {/* Header */}
            <div className="mb-6 flex items-center justify-between">
              <h3 className="text-xl font-semibold text-gray-900 dark:text-white">
                Edit {isLongform ? "Article" : "Post"}
              </h3>
              <button
                onClick={onClose}
                className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"
              >
                <svg
                  className="h-6 w-6"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M6 18L18 6M6 6l12 12"
                  />
                </svg>
              </button>
            </div>

            <div className="space-y-6">
              {isLongform ? (
                <EditLongFormFormFields
                  title={title}
                  setTitle={setTitle}
                  summary={summary}
                  setSummary={setSummary}
                  image={image}
                  setImage={setImage}
                  editorReady={editorReady}
                />
              ) : (
                <EditPostFormFields
                  caption={caption}
                  setCaption={setCaption}
                  existingImages={existingImages}
                  newFiles={newFiles}
                  onFileChange={(e) => void handleFileChange(e)}
                  onRemoveExistingImage={removeExistingImage}
                  onRemoveNewFile={removeNewFile}
                  hashTagPresets={hashTagPresets}
                  useHashtagPresets={useHashtagPresets}
                  setUseHashtagPresets={setUseHashtagPresets}
                  selectedHashtagPresetId={selectedHashtagPresetId}
                  selectedHashtagPresetTags={selectedHashtagPresetTags}
                  onHashtagPresetSelect={handleHashtagPresetSelect}
                  manualHashtags={manualHashtags}
                  setManualHashtags={setManualHashtags}
                  selectedQueueType={selectedQueueType}
                  setSelectedQueueType={setSelectedQueueType}
                  queueTypes={queueTypes}
                />
              )}

              {/* Schedule Date */}
              <div>
                <label htmlFor="edit-post-scheduled-for" className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300">
                  Scheduled For
                </label>
                <input
                  id="edit-post-scheduled-for"
                  type="datetime-local"
                  value={
                    scheduledFor ? formatDateTimeForInput(scheduledFor) : ""
                  }
                  onChange={(e) =>
                    setScheduledFor(
                      e.target.value ? new Date(e.target.value) : null,
                    )
                  }
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-gray-900 focus:border-blue-500 focus:ring-2 focus:ring-blue-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
              </div>

              {/* Re-signing notice */}
              <div className="rounded-lg border border-blue-200 bg-blue-50 p-4 dark:border-blue-800 dark:bg-blue-900/20">
                <div className="flex items-start space-x-2">
                  <svg
                    className="mt-0.5 h-5 w-5 flex-shrink-0 text-blue-600 dark:text-blue-400"
                    fill="currentColor"
                    viewBox="0 0 20 20"
                  >
                    <path
                      fillRule="evenodd"
                      d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z"
                      clipRule="evenodd"
                    />
                  </svg>
                  <div>
                    <div className="text-sm font-medium text-blue-800 dark:text-blue-200">
                      Editing this {isLongform ? "article" : "post"} requires
                      re-signing the Nostr event
                    </div>
                  </div>
                </div>
              </div>

              {/* Error display */}
              {fetcher.data?.error ?? signingError ? (
                <div className="rounded-lg border border-red-200 bg-red-50 p-4 dark:border-red-800 dark:bg-red-900/20">
                  <div className="text-sm text-red-800 dark:text-red-200">
                    {fetcher.data?.error ?? signingError}
                  </div>
                </div>
              ) : null}
            </div>

            {/* Actions */}
            <div className="mt-6 flex items-center justify-end space-x-3">
              <button
                onClick={onClose}
                className="px-4 py-2 text-sm font-medium text-gray-700 hover:text-gray-900 dark:text-gray-300 dark:hover:text-white"
              >
                Cancel
              </button>
              <button
                onClick={() => void handleSubmit()}
                disabled={
                  fetcher.state === "submitting" ||
                  isSigningEvent ||
                  isUploadingImages
                }
                className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
              >
                {isUploadingImages
                  ? "Uploading Images..."
                  : isSigningEvent
                    ? "Signing Event..."
                    : fetcher.state === "submitting"
                      ? "Saving..."
                      : "Save Changes"}
              </button>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect, useCallback } from "react";
import { toast } from "react-hot-toast";

import { getDynamicQueueStyle } from "~/features/posts/queueColors";
import type { QueueType } from "~/features/posts/types";
import { resizeImage } from "~/features/upload/image-resize";
import { useOptionalUser } from "~/lib/remix-utils";

interface PreparedEventData {
  content: string;
  type: "image";
  queueType: string;
}

interface ImagePostProps {
  files: File[];
  setFiles: React.Dispatch<React.SetStateAction<File[]>>;
  setShowImagePreview: (show: boolean) => void;
  setPreparedImageEvent: (data: PreparedEventData[]) => void;
  queueTypes?: (string | QueueType)[];
  onQueueTypeChange?: (queueType: string) => void;
}

export default function ImagePost({
  files,
  setFiles,
  setShowImagePreview,
  setPreparedImageEvent,
  queueTypes = [],
  onQueueTypeChange,
}: ImagePostProps) {
  interface FetcherData {
    success?: boolean;
    fileUrls?: { fileUrl: string; scheduledFor: string; queueType: string }[];
    error?: string;
  }

  const fetcher = useFetcher<FetcherData>();
  const user = useOptionalUser();

  const scheduleIntervals = user && typeof user === "object" && "scheduleInterval" in user ? user.scheduleInterval : null;
  const [scheduledFor, setScheduledFor] = useState("");
  const [timeError, setTimeError] = useState("");
  const [isRecyclable, setIsRecyclable] = useState(false);

  // Determine initial queue selection - default to "unassigned"
  const getInitialQueue = () => {
    return "unassigned";
  };

  const [selectedQueue, setSelectedQueue] = useState(getInitialQueue());

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = e.target.files ? Array.from(e.target.files) : [];

    // Process files to remove metadata for privacy
    try {
      const processedFiles = await Promise.all(
        selectedFiles.map(async (file) => {
          if (file.type.startsWith("image/")) {
            return await resizeImage(file);
          }
          return file;
        }),
      );
      setFiles((prev: File[]) => [...prev, ...processedFiles]);
    } catch (error: unknown) {
      const { handleAsyncErrorWithMessage } = await import("~/lib/error-handler.client");
      handleAsyncErrorWithMessage(
        error,
        "Error processing images. Using original files.",
        {
          component: "ImagePost",
          action: "handleFileChange",
        },
        false, // Don't show toast, we call toast.error instead
      );
      toast.error("Error processing images. Using original files.");
      setFiles((prev: File[]) => [...prev, ...selectedFiles]);
    }
  };

  const handleDrop = async (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const droppedFiles = Array.from(e.dataTransfer.files);
    if (droppedFiles.length > 0) {
      // Check if files are images
      const imageFiles = droppedFiles.filter((file) =>
        file.type.startsWith("image/"),
      );
      if (imageFiles.length === 0) {
        toast.error("Please drop only image files");
        return;
      }

      // Process files to remove metadata for privacy
      try {
        const processedFiles = await Promise.all(
          imageFiles.map(async (file) => await resizeImage(file)),
        );
        setFiles((prev: File[]) => [...prev, ...processedFiles]);
      } catch (error: unknown) {
        const { handleAsyncErrorWithMessage } = await import("~/lib/error-handler.client");
        handleAsyncErrorWithMessage(
          error,
          "Error processing images. Using original files.",
          {
            component: "ImagePost",
            action: "handleDrop",
          },
          false, // Don't show toast, we call toast.error instead
        );
        toast.error("Error processing images. Using original files.");
        setFiles((prev: File[]) => [...prev, ...imageFiles]);
      }
    }
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const handleImagePreview = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    // Check if scheduledFor is empty
    if (!scheduledFor) {
      setTimeError("Please set a scheduled time before uploading");
      toast.error("Please set a scheduled time before uploading");
      return;
    }

    setTimeError("");
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    formData.set("_action", "upload-images-preview");
    formData.set("queueType", selectedQueue);
    // Set isRecyclable checkbox state
    if (isRecyclable) {
      formData.set("isRecyclable", "on");
    }

    // Remove any existing files from formData
    formData.delete("files");

    // Append each file individually to formData
    files.forEach((file) => {
      formData.append("files", file);
    });

    fetcher.submit(formData, {
      method: "post",
      encType: "multipart/form-data",
    });
  };

  const calculateQueueScheduleTime = useCallback(async (queueTypeName: string) => {
    if (queueTypeName === "unassigned") {
      setScheduledFor("");
      return;
    }

    // Find the queue type object to get its ID
    const selectedQueueType = queueTypes.find(qt => {
      if (typeof qt === "string") {
        return qt === queueTypeName;
      }
      if (qt && typeof qt === "object" && "name" in qt && typeof qt.name === "string") {
        return qt.name === queueTypeName;
      }
      return false;
    });
    const queueTypeId = selectedQueueType && typeof selectedQueueType === "object" && "id" in selectedQueueType && typeof selectedQueueType.id === "string" ? selectedQueueType.id : null;

    try {
      const response = await fetch("/api/queue-schedule", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          queueTypeId,
          queueTypeName, // Keep for backward compatibility
          userId: user && typeof user === "object" && "id" in user && typeof user.id === "string" ? user.id : undefined,
        }),
      });

      if (response.ok) {
        const dataRaw: unknown = await response.json();
        const data = dataRaw && typeof dataRaw === "object" && !Array.isArray(dataRaw) ? dataRaw as { scheduledTime?: unknown } : {};
        const scheduledTime = typeof data.scheduledTime === "string" ? data.scheduledTime : undefined;
        if (scheduledTime) {
          setScheduledFor(scheduledTime);
        }
        setTimeError("");
      }
    } catch (error: unknown) {
      console.error("Error calculating schedule time:", error);
    }
  }, [queueTypes, user && typeof user === "object" && "id" in user && typeof user.id === "string" ? user.id : undefined]);

  useEffect(() => {
    if (selectedQueue !== "unassigned") {
      void calculateQueueScheduleTime(selectedQueue);
    }
    // Notify parent component of queue type change
    if (onQueueTypeChange) {
      onQueueTypeChange(selectedQueue);
    }
  }, [selectedQueue, onQueueTypeChange, calculateQueueScheduleTime]);

  const handleScheduleIntervalClick = (intervalHours: string | number) => {
    // Find the currently selected queue type
    const selectedQueueType = queueTypes.find(qt => {
      if (typeof qt === "string") {
        return qt === selectedQueue;
      }
      if (qt && typeof qt === "object" && "name" in qt && typeof qt.name === "string") {
        return qt.name === selectedQueue;
      }
      return false;
    });

    // If this is a fixed slot queue, use the API to get the next scheduled time instead
    if (selectedQueueType && typeof selectedQueueType === "object" && "scheduleType" in selectedQueueType && selectedQueueType.scheduleType === "FIXED_SLOTS") {
      // For fixed slot queues, recalculate the schedule time instead of adding hours
      void calculateQueueScheduleTime(selectedQueue);
      return;
    }

    const now = new Date();
    const intervalHoursNum = typeof intervalHours === "string" ? parseInt(intervalHours, 10) : intervalHours;
    const hoursLater = new Date(
      now.getTime() + intervalHoursNum * 60 * 60 * 1000,
    );

    // Format the date in the user's timezone
    const userTimezone = user && typeof user === "object" && "timezone" in user && typeof user.timezone === "string" ? user.timezone : "UTC";
    const formattedDate = hoursLater.toLocaleString("en-US", {
      timeZone: userTimezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });

    // Parse the formatted date back into components
    const [datePart, timePart] = formattedDate.split(", ");
    const [month, day, year] = datePart.split("/");
    const [hours, minutes] = timePart.split(":");

    // Create the datetime-local format (YYYY-MM-DDTHH:mm)
    const formattedForInput = `${year}-${month}-${day}T${hours}:${minutes}`;

    setScheduledFor(formattedForInput);
    setTimeError("");
  };

  // Handle fetcher success data
  const fetcherDataRaw = fetcher.data;
  const fetcherData = fetcherDataRaw && typeof fetcherDataRaw === "object" && !Array.isArray(fetcherDataRaw) ? fetcherDataRaw as { success?: unknown; fileUrls?: unknown; error?: unknown } : null;
  const isSuccess = fetcherData && typeof fetcherData.success === "boolean" && fetcherData.success;
  const fileUrls = fetcherData && "fileUrls" in fetcherData && Array.isArray(fetcherData.fileUrls) ? fetcherData.fileUrls : null;
  const error = fetcherData && typeof fetcherData.error === "string" ? fetcherData.error : null;

  if (isSuccess && fileUrls) {
    toast.success("Images uploaded successfully!");

    const preparedData: PreparedEventData[] = fileUrls.map((url: unknown) => {
      const urlObj = url && typeof url === "object" && !Array.isArray(url) ? url as { fileUrl?: unknown; scheduledFor?: unknown; queueType?: unknown } : {};
      const fileUrl = typeof urlObj.fileUrl === "string" ? urlObj.fileUrl : "";
      const queueType = typeof urlObj.queueType === "string" ? urlObj.queueType : selectedQueue;
      return {
        content: fileUrl,
        type: "image",
        queueType, // Include queue type information
      };
    });

    setShowImagePreview(true);
    setPreparedImageEvent(preparedData);
    setFiles([]);
  }

  // Add error handling
  if (fetcherData && typeof fetcherData.success === "boolean" && !fetcherData.success && error) {
    toast.error(error);
  }

  const isUploaded = Boolean(isSuccess && fileUrls);

  return (
    <fetcher.Form
      method="post"
      className="w-full"
      encType="multipart/form-data"
      onSubmit={(e) => { void handleImagePreview(e); }}
    >
      <input type="hidden" name="_action" value="upload-images-preview" />
      <label
        className={`block ${isUploaded ? "cursor-not-allowed" : "cursor-pointer"}`}
      >
        <input
          type="file"
          name="files"
          className="hidden"
          accept="image/*"
          multiple
          onChange={(e) => { void handleFileChange(e); }}
          disabled={fetcher.state !== "idle" || isUploaded}
        />
        <div
          className={`rounded-lg border-2 border-dashed border-gray-300 p-12 text-center ${!isUploaded && "hover:border-gray-400"}`}
          onDrop={!isUploaded ? (e) => { void handleDrop(e); } : undefined}
          onDragOver={!isUploaded ? handleDragOver : undefined}
        >
          {files.length > 0 ? (
            <div className="flex flex-wrap gap-4">
              {files.map((file, index) => (
                <div key={index} className="relative">
                  <img
                    src={URL.createObjectURL(file)}
                    alt="Preview"
                    className="h-32 w-32 object-cover"
                  />
                  <button
                    type="button"
                    onClick={() =>
                      setFiles(files.filter((_, i) => i !== index))
                    }
                    className="absolute -right-2 -top-2 rounded-full bg-red-500 p-1 text-white hover:bg-red-600"
                    disabled={fetcher.state !== "idle"}
                  >
                    ×
                  </button>
                </div>
              ))}
              <div className="flex h-32 w-32 items-center justify-center border-2 border-dashed border-gray-300 hover:border-gray-400">
                <span className="text-4xl text-gray-500">+</span>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-4">
              <div className="text-green-500">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-12 w-12"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
                  />
                </svg>
              </div>
              <div>
                <p className="text-xl font-medium text-gray-900 dark:text-gray-100">
                  Click to upload or drag and drop
                </p>
                <p className="mt-1 text-sm text-gray-500">
                  Multiple images (max 100MB total)
                </p>
              </div>
            </div>
          )}
        </div>
      </label>
      <div className="mt-4">
        <textarea
          name="caption"
          className="w-full rounded-lg border p-4 text-gray-900"
          placeholder="Add a caption to your image(s)..."
          rows={3}
          disabled={fetcher.state !== "idle" || isUploaded}
        />
      </div>
      <div className="mt-4 flex items-center justify-between gap-4">
        <div className="flex flex-col gap-2">
          <div className="mb-2">
            <label htmlFor="queue-type-selector" className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300">
              Queue Type
            </label>
            <div className="flex flex-wrap gap-2">
              {/* Unassigned option */}
              <button
                type="button"
                onClick={() => setSelectedQueue("unassigned")}
                disabled={fetcher.state !== "idle" || isUploaded}
                className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(null, selectedQueue === "unassigned")} disabled:cursor-not-allowed disabled:opacity-50`}
              >
                Unassigned
              </button>

              {/* Queue types */}
              {queueTypes
                .filter((queue) => {
                  const isEnabled =
                    typeof queue === "object"
                      ? queue.isEnabled !== false
                      : true;
                  return isEnabled;
                })
                .map((queue) => {
                  const queueName =
                    typeof queue === "string" ? queue : queue.name;
                  const queueColor =
                    typeof queue === "object" ? queue.color : null;
                  return (
                    <button
                      key={queueName}
                      type="button"
                      onClick={() => setSelectedQueue(queueName ?? "")}
                      disabled={fetcher.state !== "idle" || isUploaded}
                      className={`rounded-full px-4 py-2 text-sm ${getDynamicQueueStyle(queueColor ?? null, selectedQueue === queueName)} disabled:cursor-not-allowed disabled:opacity-50`}
                      style={{
                        backgroundColor: queueColor ?? undefined,
                        borderColor: queueColor ?? undefined,
                      }}
                    >
                      {queueName}
                    </button>
                  );
                })}
            </div>
            <input type="hidden" name="queueType" value={selectedQueue} />
          </div>
          <div className="mb-2 flex items-center gap-2">
            <input
              type="checkbox"
              id="isRecyclable"
              name="isRecyclable"
              checked={isRecyclable}
              onChange={(e) => setIsRecyclable(e.target.checked)}
              disabled={fetcher.state !== "idle" || isUploaded}
              className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <label
              htmlFor="isRecyclable"
              className="text-sm text-gray-700 dark:text-gray-300"
            >
              Make this post recyclable
            </label>
          </div>
          <div className="flex items-center gap-4">
            <input
              type="datetime-local"
              name="scheduledFor"
              value={scheduledFor}
              onChange={(e) => {
                setScheduledFor(e.target.value);
                setTimeError("");
              }}
              className={`rounded-md border ${timeError ? "border-red-500" : "border-gray-300"} p-2 text-gray-900`}
              disabled={fetcher.state !== "idle" || isUploaded}
            />
          </div>
          {timeError ? (
            <p className="text-sm text-red-500">{timeError}</p>
          ) : null}
          <div className="flex flex-wrap gap-2">
            {(() => {
              // Find the currently selected queue type
              const selectedQueueType = queueTypes.find(qt => {
                if (typeof qt === "string") {
                  return qt === selectedQueue;
                }
                if (qt && typeof qt === "object" && "name" in qt && typeof qt.name === "string") {
                  return qt.name === selectedQueue;
                }
                return false;
              });

              // For fixed slot queues, show a different UI
              if (selectedQueueType && typeof selectedQueueType === "object" && "scheduleType" in selectedQueueType && selectedQueueType.scheduleType === "FIXED_SLOTS") {
                return (
                  <button
                    type="button"
                    onClick={() => { void calculateQueueScheduleTime(selectedQueue); }}
                    className="rounded-md bg-blue-100 px-2.5 py-1.5 text-xs font-medium text-blue-700 hover:bg-blue-200 dark:bg-blue-800 dark:text-blue-300 dark:hover:bg-blue-700"
                    disabled={fetcher.state !== "idle" || isUploaded}
                  >
                    Next Slot
                  </button>
                );
              }

              // For interval-based queues, show the hour buttons
              if (scheduleIntervals && Array.isArray(scheduleIntervals)) {
                return scheduleIntervals.map((interval: unknown) => {
                  const intervalValue = typeof interval === "string" ? interval : (typeof interval === "number" ? String(interval) : "");
                  if (!intervalValue) return null;
                  return (
                    <button
                      key={intervalValue}
                      type="button"
                      onClick={() => handleScheduleIntervalClick(intervalValue)}
                      className="rounded-md bg-gray-100 px-2.5 py-1.5 text-xs font-medium text-gray-700 hover:bg-gray-200 dark:bg-gray-800 dark:text-gray-300 dark:hover:bg-gray-700"
                      disabled={fetcher.state !== "idle" || isUploaded}
                    >
                      +{intervalValue}h
                    </button>
                  );
                }).filter((button): button is JSX.Element => button !== null);
              }
              return null;
            })()}
          </div>
        </div>
        <button
          type="submit"
          className="rounded-lg bg-green-500 px-8 py-4 text-white hover:bg-green-600 disabled:opacity-50"
          disabled={
            fetcher.state !== "idle" || isUploaded || files.length === 0
          }
        >
          {fetcher.state !== "idle" ? "Uploading..." : "Upload Images →"}
        </button>
      </div>
    </fetcher.Form>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

import { Badge } from "~/components/ui/badge";
import { Button } from "~/components/ui/button";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";
import { Textarea } from "~/components/ui/textarea";
import { AssetBrowser, type Asset } from "~/features/assets";
import type { EditorJSBlock } from "~/features/posts/types";
import {
  signLongFormEvent,
  convertEditorJSToMarkdown,
  generateArticleIdentifier,
} from "~/lib/nostr";

import { useCoverImageUpload } from "../useCoverImageUpload";
import { useLongFormEditor } from "../useLongFormEditor";
import { useLongFormScheduling } from "../useLongFormScheduling";

import { LongFormActionButtons } from "./LongFormActionButtons";
import { LongFormCoverImage } from "./LongFormCoverImage";
import { LongFormEditorStyles } from "./LongFormEditorStyles";
import { LongFormPublishingOptions } from "./LongFormPublishingOptions";

interface QueueType {
  id?: string;
  name: string;
  color?: string | null;
  hashtags?: string | null;
  scheduleType?: string;
  isEnabled?: boolean;
}

interface HashTagPreset {
  id: string;
  name: string;
  tags: string;
  description?: string | null;
}

interface InitialData {
  title?: string;
  summary?: string;
  content?: string;
  image?: string;
  tags?: string[];
  queueType?: { name: string };
}

interface LongFormPostProps {
  queueTypes?: (string | QueueType)[];
  scheduleIntervals?: number[];
  userTags?: string;
  assets?: Asset[];
  uploadProvider?: string | null;
  userTimezone?: string;
  onQueueTypeChange?: (name: string) => void;
  onPreview?: (data: { title: string; summary: string; content: string; image: string }) => void;
  initialData?: InitialData | null;
  isEditing?: boolean;
  hashTagPresets?: HashTagPreset[];
  useHashtagPresets?: boolean;
  selectedHashtagPresetId?: string | null;
  selectedHashtags?: string;
  onUseHashtagPresetsChange?: (value: boolean) => void;
  onHashtagPresetChange?: (presetId: string | null, hashtags: string) => void;
}

export default function LongFormPost({
  queueTypes = [],
  scheduleIntervals = [],
  userTags = "",
  assets = [],
  uploadProvider = null,
  userTimezone = "UTC",
  onQueueTypeChange,
  onPreview,
  initialData = null,
  isEditing: _isEditing = false,
  hashTagPresets = [],
  useHashtagPresets = false,
  selectedHashtagPresetId = null,
  selectedHashtags = "",
  onUseHashtagPresetsChange,
  onHashtagPresetChange,
}: LongFormPostProps) {
  const fetcher = useFetcher();
  const [title, setTitle] = useState(initialData?.title ?? "");
  const [summary, setSummary] = useState(initialData?.summary ?? "");
  const [content, setContent] = useState(initialData?.content ?? "");
  const [customTags, setCustomTags] = useState(
    initialData?.tags?.join(", ") ?? "",
  );
  const [showAssetBrowser, setShowAssetBrowser] = useState("");

  // Use extracted hooks
  const {
    editorReady,
    loadInitialData,
    insertAssetIntoEditor,
    generateSummaryFromContent,
  } = useLongFormEditor({
    uploadProvider,
    onContentChange: setContent,
  });

  const {
    image,
    setImage,
    uploadError,
    uploadFetcherState,
    handleImageUpload,
    handleCoverImageAssets,
    handleFetcherData,
    handleFetcherStateChange,
  } = useCoverImageUpload({
    uploadProvider,
    initialImage: initialData?.image ?? "",
  });

  const {
    selectedQueueType,
    scheduledFor,
    setScheduledFor,
    displayedHashtags,
    updateDisplayedHashtags,
    handleScheduleIntervalClick,
    calculateQueueScheduleTime,
  } = useLongFormScheduling({
    queueTypes,
    scheduleIntervals,
    userTags,
    userTimezone,
    initialQueueType: initialData?.queueType?.name ?? "Unassigned",
    onQueueTypeChange,
  });

  // Handle upload fetcher responses
  useEffect(() => {
    handleFetcherData();
  }, [handleFetcherData]);

  // Clear upload errors when fetcher state changes
  useEffect(() => {
    handleFetcherStateChange();
  }, [handleFetcherStateChange]);

  // Handle initial data loading - wait for both editor ready and initial data
  useEffect(() => {
    if (editorReady && initialData?.content) {
      const timeoutId = setTimeout(() => {
        void loadInitialData(initialData.content!);
      }, 100);
      return () => clearTimeout(timeoutId);
    }
  }, [editorReady, initialData?.content, loadInitialData]);

  const handleAssetBrowserSelect = (selectedAssets: Asset[]) => {
    if (showAssetBrowser === "cover") {
      handleCoverImageAssets(selectedAssets.map(asset => ({
        assetType: asset.assetType,
        fileUrl: asset.fileUrl ?? undefined,
      })));
    } else {
      void insertAssetIntoEditor(selectedAssets.map(asset => ({
        assetType: asset.assetType,
        fileUrl: asset.fileUrl ?? undefined,
        content: asset.content ?? undefined,
        title: asset.title ?? undefined,
      })));
    }
    setShowAssetBrowser("");
  };

  const handleGenerateSummary = () => {
    const generatedSummary = generateSummaryFromContent(content);
    if (generatedSummary) {
      setSummary(generatedSummary);
    }
  };

  const handleSchedule = async (actionType: "schedule" | "publish") => {
    if (!title.trim() || !content.trim()) {
      return;
    }

    try {
      let markdownContent;
      try {
        const editorData = JSON.parse(content) as { blocks?: EditorJSBlock[] };
        markdownContent = convertEditorJSToMarkdown(editorData as { blocks: EditorJSBlock[] });
      } catch {
        markdownContent = content;
      }

      const finalSummary = summary || generateSummaryFromContent(content);
      const identifier = generateArticleIdentifier(title);

      let scheduledTimestamp;
      if (actionType === "schedule" && scheduledFor) {
        const scheduledTime = new Date(scheduledFor);
        scheduledTimestamp = Math.floor(scheduledTime.getTime() / 1000);
      }

      // Get effective hashtags - prioritize manual selection over queue defaults
      let effectiveHashtags = "";

      if (useHashtagPresets) {
        // Manual hashtag presets are enabled
        if (selectedHashtags) {
          // Use manually selected hashtag preset
          effectiveHashtags = selectedHashtags;
        }
        // If useHashtagPresets is true but no manual preset selected, use no hashtags
      } else {
        // Manual hashtag presets are disabled, use displayed hashtags (queue defaults)
        effectiveHashtags = displayedHashtags || "";
      }

      const hashtagsFromQueue = effectiveHashtags
        ? effectiveHashtags
          .split(" ")
          .map((tag) => tag.replace("#", "").trim())
          .filter(Boolean)
        : [];
      const customTagsList = customTags
        ? customTags
          .split(",")
          .map((tag) => tag.trim())
          .filter(Boolean)
        : [];
      // Combine and deduplicate tags (case insensitive)
      const allTags = [...hashtagsFromQueue, ...customTagsList];
      const uniqueTags = allTags.filter(
        (tag, index) =>
          allTags.findIndex((t) => t.toLowerCase() === tag.toLowerCase()) ===
          index,
      );

      const eventData = {
        title,
        content: markdownContent,
        summary: finalSummary,
        image,
        tags: uniqueTags,
        identifier,
        publishedAt:
          actionType === "publish"
            ? Math.floor(Date.now() / 1000)
            : scheduledTimestamp,
      };

      const { nostrEvent, signedEvent } = await signLongFormEvent(eventData);

      const form = document.createElement("form");
      form.method = "POST";
      form.style.display = "none";

      const fields: [string, string][] = [
        [
          "_action",
          actionType === "schedule" ? "schedule-longform" : "publish",
        ],
        ["title", title],
        ["content", content],
        ["summary", finalSummary],
        ["image", image],
        ["tags", uniqueTags.join(",")],
        ["queueType", selectedQueueType],
        [
          "scheduledFor",
          scheduledTimestamp ? scheduledTimestamp.toString() : "",
        ],
        ["signedEvent", JSON.stringify(signedEvent)],
        ["nostrEvent", JSON.stringify(nostrEvent)],
      ];

      fields.forEach(([name, value]) => {
        const input = document.createElement("input");
        input.type = "hidden";
        input.name = name;
        input.value = value || "";
        form.appendChild(input);
      });

      document.body.appendChild(form);
      form.submit();
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(error, {
        component: "LongFormPost",
        action: "handleSubmit",
      }, false); // Don't show toast, let component handle it
    }
  };

  const isFormValid = !!(title.trim() && summary.trim() && content.trim() && image);

  return (
    <>
      <LongFormEditorStyles />

      <div className="space-y-6">
        <div>
          <Label htmlFor="title">Title *</Label>
          <Input
            id="title"
            name="title"
            type="text"
            required
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Enter your post title"
            className="mt-1"
          />
        </div>

        <div>
          <Label htmlFor="summary">Summary *</Label>
          <div className="mt-1 flex gap-2">
            <Textarea
              id="summary"
              name="summary"
              required
              value={summary}
              onChange={(e) => setSummary(e.target.value)}
              placeholder="Brief description of your post"
              rows={3}
              className="flex-1"
            />
            <Button
              type="button"
              variant="outline"
              onClick={handleGenerateSummary}
              disabled={!content}
              className="whitespace-nowrap"
            >
              Auto-generate
            </Button>
          </div>
        </div>

        <LongFormCoverImage
          image={image}
          uploadError={uploadError}
          uploadProvider={uploadProvider}
          uploadFetcherState={uploadFetcherState}
          onImageUpload={(file) => void handleImageUpload(file)}
          onRemove={() => setImage("")}
          onOpenAssetBrowser={() => setShowAssetBrowser("cover")}
        />

        <div>
          <div className="mb-1 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <Label htmlFor="content">Content *</Label>
              {uploadProvider ? (
                <div className="flex items-center gap-1 text-xs text-gray-500">
                  <span>Images upload via:</span>
                  <span
                    className={`rounded px-2 py-1 text-xs font-medium ${uploadProvider.includes("BLOSSOM")
                      ? "bg-purple-100 text-purple-800"
                      : "bg-blue-100 text-blue-800"
                      }`}
                  >
                    {uploadProvider.includes("BLOSSOM")
                      ? `🌸 ${uploadProvider === "BLOSSOM_PRIMAL" ? "Primal" : "Blosstr"}`
                      : "☁️ S3"}
                  </span>
                </div>
              ) : null}
            </div>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => setShowAssetBrowser("content")}
              className="text-xs"
            >
              <svg
                xmlns="http://www.w3.org/2000/svg"
                className="mr-1 h-3 w-3"
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10"
                />
              </svg>
              Insert Assets
            </Button>
          </div>
          <div className="mt-1 rounded-lg border border-gray-300 focus-within:border-blue-500 focus-within:ring-1 focus-within:ring-blue-500 dark:border-gray-600">
            <div className="min-h-[500px] p-4">
              <div
                id="editorjs"
                className="prose prose-lg dark:prose-invert min-h-[460px] max-w-none"
              ></div>
            </div>
          </div>
          <input type="hidden" name="content" value={content} />
        </div>

        {/* Custom Tags Input */}
        <div>
          <Label htmlFor="customTags">Custom Tags</Label>
          <Input
            id="customTags"
            name="customTags"
            type="text"
            value={customTags}
            onChange={(e) => setCustomTags(e.target.value)}
            placeholder="Enter custom tags separated by commas (e.g. bitcoin, nostr, technology)"
            className="mt-1"
          />
          <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
            These tags will be added to the NOSTR event and combined with queue
            type hashtags if any
          </p>
        </div>

        {/* Hashtags Display */}
        {displayedHashtags ? (
          <div className="flex items-center gap-2">
            <Badge variant="secondary" className="text-xs">
              <svg
                className="hi-solid hi-hashtag mr-1 inline-block size-3 opacity-75"
                fill="currentColor"
                viewBox="0 0 20 20"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  fillRule="evenodd"
                  d="M9.243 3.03a1 1 0 01.727 1.213L9.53 6h2.94l.56-2.243a1 1 0 111.94.486L14.53 6H17a1 1 0 110 2h-2.97l-1 4H15a1 1 0 110 2h-2.47l-.56 2.242a1 1 0 11-1.94-.485L10.47 14H7.53l-.56 2.242a1 1 0 11-1.94-.485L5.47 14H3a1 1 0 110-2h2.97l1-4H5a1 1 0 110-2h2.47l.56-2.243a1 1 0 011.213-.727zM9.03 8l-1 4h2.938l1-4H9.031z"
                  clipRule="evenodd"
                />
              </svg>
              {displayedHashtags}
            </Badge>
          </div>
        ) : null}

        <LongFormPublishingOptions
          queueTypes={queueTypes}
          selectedQueueType={selectedQueueType}
          onQueueTypeChange={(name) => void updateDisplayedHashtags(name)}
          scheduledFor={scheduledFor}
          onScheduledForChange={setScheduledFor}
          scheduleIntervals={scheduleIntervals}
          onScheduleIntervalClick={(intervalHours) => void handleScheduleIntervalClick(intervalHours)}
          onNextSlotClick={() => {
            void calculateQueueScheduleTime(selectedQueueType);
          }}
          hashTagPresets={hashTagPresets}
          useHashtagPresets={useHashtagPresets}
          selectedHashtagPresetId={selectedHashtagPresetId}
          selectedHashtags={selectedHashtags}
          onHashtagPresetChange={onHashtagPresetChange || ((_id, _tags) => { void _id; void _tags; })}
          onUseHashtagPresetsChange={onUseHashtagPresetsChange || (() => { void 0; })}
        />

        <LongFormActionButtons
          fetcherState={fetcher.state}
          isFormValid={isFormValid}
          hasScheduledFor={!!scheduledFor}
          onPreview={() => {
            if (onPreview) {
              onPreview({
                title,
                summary: summary || generateSummaryFromContent(content),
                content,
                image,
              });
            }
          }}
          onSchedule={() => void handleSchedule("schedule")}
          onPublish={() => void handleSchedule("publish")}
        />

        {/* Asset Browser Modal */}
        {showAssetBrowser ? (
          <AssetBrowser
            assets={assets}
            onAssetsSelected={handleAssetBrowserSelect}
            onClose={() => setShowAssetBrowser("")}
          />
        ) : null}
      </div>
    </>
  );
}

import { useState, useEffect } from "react";
import { toast } from "react-hot-toast";

import { HashtagPresetToggle } from "~/components/dashboard/HashtagPresetToggle";
import { QueueSelector } from "~/features/posts/components/QueueSelector";
import { SchedulingSection } from "~/features/posts/components/SchedulingSection";
import { usePostScheduling } from "~/features/posts/hooks/usePostScheduling";
import type { QueueType, HashTagPreset } from "~/features/posts/types";
import {
  validateAndProcessFiles,
} from "~/features/posts/utils/file-processing.client";
import { uploadMultipleFiles } from "~/features/upload/upload.client";
import { useOptionalUser } from "~/lib/remix-utils";

interface PreparedEventData {
  content: {
    fileUrl: string;
    scheduledFor: string;
    caption: string;
    queueType: string;
  };
  type: "media";
  queueType: string;
}

interface MediaPostProps {
  files: File[];
  setFiles: React.Dispatch<React.SetStateAction<File[]>>;
  setShowImagePreview: (show: boolean) => void;
  setPreparedImageEvent: (data: PreparedEventData[]) => void;
  queueTypes?: (string | QueueType)[];
  hashTagPresets?: HashTagPreset[];
  selectedQueueType?: string;
  onQueueTypeChange?: (queueType: string) => void;
  selectedHashTagPresetId?: string | null;
  onHashtagPresetChange?: (presetId: string | null, hashtags: string) => void;
}

// Helper function to determine media type (kept for backward compatibility)
const getMediaType = (file: File) => {
  if (file.type.startsWith("image/")) return "image";
  if (file.type.startsWith("video/")) return "video";
  return "unknown";
};

// isAcceptableFile is now imported from file-processing.client.ts

export default function MediaPost({
  files,
  setFiles,
  setShowImagePreview,
  setPreparedImageEvent,
  queueTypes = [],
  hashTagPresets = [],
  onQueueTypeChange,
  selectedHashTagPresetId,
  onHashtagPresetChange,
}: MediaPostProps) {
  const user = useOptionalUser();

  const [isRecyclable, setIsRecyclable] = useState(false);
  const [useHashtagPresets, setUseHashtagPresets] = useState(false);
  const [selectedHashtagPresetId, setSelectedHashtagPresetId] = useState(
    selectedHashTagPresetId ?? null,
  );
  const [_selectedHashtags, setSelectedHashtags] = useState("");
  const [timeError, setTimeError] = useState<string | null>(null);

  // Use the shared scheduling hook
  const {
    selectedQueue,
    setSelectedQueue,
    scheduledFor,
    setScheduledFor,
    calculateQueueScheduleTime,
    handleScheduleIntervalClick,
    scheduleIntervals,
  } = usePostScheduling({
    queueTypes,
    scheduleIntervals: user?.scheduleInterval as number[] | undefined,
    userTimezone: user?.timezone ?? undefined,
    initialQueue: "unassigned",
    onQueueTypeChange,
    onTimeError: setTimeError,
  });

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = e.target.files ? Array.from(e.target.files) : [];

    // Use extracted utility for validation and processing
    const processedFiles = await validateAndProcessFiles(selectedFiles);

    if (processedFiles) {
      setFiles((prev: File[]) => [...prev, ...processedFiles]);
    }
  };

  const handleDrop = async (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const droppedFiles = Array.from(e.dataTransfer.files);

    if (droppedFiles.length > 0) {
      // Use extracted utility for validation and processing
      const processedFiles = await validateAndProcessFiles(droppedFiles);

      if (processedFiles) {
        setFiles((prev: File[]) => [...prev, ...processedFiles]);
      }
    }
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const [isUploading, setIsUploading] = useState(false);
  const [uploadProvider, setUploadProvider] = useState<string | null>(null);

  // Fetch upload provider on component mount
  useEffect(() => {
    void (async () => {
      try {
        const res = await fetch("/api/user-upload-provider");
        const data: unknown = await res.json();
        const provider = data && typeof data === "object" && !Array.isArray(data) && "provider" in data && typeof data.provider === "string" ? data.provider : null;
        setUploadProvider(provider);
      } catch (err) {

        const { handleErrorSafely } = require("~/lib/error-handler.client") as unknown as { handleErrorSafely: (error: unknown, context: { component: string; action: string }) => void };
        handleErrorSafely(err, {
          component: "MediaPost",
          action: "fetchUploadProvider",
        });
      }
    })();
  }, []);

  const handleImagePreview = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    // Check if scheduledFor is empty
    if (!scheduledFor) {
      setTimeError("Please set a scheduled time before uploading");
      toast.error("Please set a scheduled time before uploading");
      return;
    }

    if (files.length === 0) {
      toast.error("Please select files to upload");
      return;
    }

    setTimeError("");
    setIsUploading(true);

    // Get form data
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const caption = formData.get("caption") ?? "";

    try {
      // Use the new upload utility that handles both S3 and Blossom
      const uploadResults = await uploadMultipleFiles(files);

      // Check if all uploads were successful
      const failedUploads = uploadResults.filter((result) => !result.success);
      if (failedUploads.length > 0) {
        const errorMessages = failedUploads
          .map((result) => result.error)
          .join(", ");
        toast.error(`Upload failed: ${errorMessages}`);
        setIsUploading(false);
        return;
      }

      // Extract URLs from successful uploads
      const fileUrls = uploadResults
        .filter((result) => result.success && result.file)
        .map((result) => ({
          fileUrl: result.file!.url,
          scheduledFor,
          caption: caption,
          queueType: selectedQueue,
        }));

      if (fileUrls.length === 0) {
        toast.error("No files were successfully uploaded");
        setIsUploading(false);
        return;
      }

      toast.success("Media uploaded successfully!");

      const preparedData: PreparedEventData[] = fileUrls.map((url) => {
        return {
          content: {
            fileUrl: url.fileUrl,
            scheduledFor: url.scheduledFor,
            caption: typeof url.caption === "string" ? url.caption : String(url.caption ?? ""),
            queueType: url.queueType ?? selectedQueue,
          },
          type: "media",
          queueType: url.queueType ?? selectedQueue,
        };
      });

      setShowImagePreview(true);
      setPreparedImageEvent(preparedData);
      setFiles([]);
      setIsUploading(false);
    } catch (error) {
      const { handleAsyncError, getErrorMessage } = await import("~/lib/error-handler.client");
      const errorMessage = getErrorMessage(error) ?? "Unknown error";
      handleAsyncError(error, {
        component: "MediaPost",
        action: "handleImagePreview",
      }, false); // Don't show toast, we call toast.error instead
      toast.error(`Upload failed: ${errorMessage}`);
      setIsUploading(false);
    }
  };

  const handleHashtagPresetSelect = (
    presetId: string | null,
    hashtags: string,
  ) => {
    setSelectedHashtagPresetId(presetId);
    setSelectedHashtags(hashtags);
    if (onHashtagPresetChange) {
      onHashtagPresetChange(presetId, hashtags);
    }
  };

  const isUploaded = false; // Removed old fetcher logic

  return (
    <form className="w-full" onSubmit={(e) => void handleImagePreview(e)}>
      <input type="hidden" name="_action" value="upload-media-preview" />
      <label
        className={`block ${isUploaded ? "cursor-not-allowed" : "cursor-pointer"}`}
      >
        <input
          type="file"
          name="files"
          className="hidden"
          accept="image/*,video/*"
          multiple
          onChange={(e) => void handleFileChange(e)}
          disabled={isUploading || isUploaded}
        />
        <div
          className={`rounded-lg border-2 border-dashed border-gray-300 p-12 text-center ${!isUploaded && "hover:border-gray-400"}`}
          onDrop={!isUploaded ? ((e) => void handleDrop(e)) : undefined}
          onDragOver={!isUploaded ? handleDragOver : undefined}
        >
          {files.length > 0 ? (
            <div className="flex flex-wrap gap-4">
              {files.map((file, index) => {
                const mediaType = getMediaType(file);
                const objectURL = URL.createObjectURL(file);

                return (
                  <div key={index} className="relative">
                    {mediaType === "image" ? (
                      <img
                        src={objectURL}
                        alt="Preview"
                        className="h-32 w-32 rounded object-cover"
                      />
                    ) : mediaType === "video" ? (
                      <video
                        src={objectURL}
                        className="h-32 w-32 rounded object-cover"
                        muted
                        preload="metadata"
                      />
                    ) : (
                      <div className="flex h-32 w-32 items-center justify-center rounded bg-gray-200">
                        <span className="text-xs text-gray-500">
                          Unsupported
                        </span>
                      </div>
                    )}
                    <button
                      type="button"
                      onClick={() =>
                        setFiles(files.filter((_, i) => i !== index))
                      }
                      className="absolute -right-2 -top-2 rounded-full bg-red-500 p-1 text-white hover:bg-red-600"
                      disabled={isUploading}
                    >
                      ×
                    </button>
                    {/* Media type indicator */}
                    <div className="absolute bottom-1 left-1 rounded bg-black bg-opacity-70 px-2 py-1 text-xs text-white">
                      {mediaType === "video" ? "🎥" : "🖼️"}
                    </div>
                  </div>
                );
              })}
              <div className="flex h-32 w-32 items-center justify-center rounded border-2 border-dashed border-gray-300 hover:border-gray-400">
                <span className="text-4xl text-gray-500">+</span>
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-4">
              <div className="text-green-500">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-12 w-12"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
                  />
                </svg>
              </div>
              <div>
                <p className="text-xl font-medium text-gray-900 dark:text-gray-100">
                  Click to upload or drag and drop
                </p>
                <p className="mt-1 text-sm text-gray-500">
                  Images (10MB max) and Videos (100MB max)
                </p>
              </div>
            </div>
          )}
        </div>
      </label>
      <div className="mt-4">
        <textarea
          name="caption"
          className="w-full rounded-lg border p-4 text-gray-900"
          placeholder="Add a caption to your media..."
          rows={3}
          disabled={isUploading || isUploaded}
        />
      </div>
      <div className="mt-4 flex items-center justify-between gap-4">
        <div className="flex flex-col gap-2">
          <QueueSelector
            queueTypes={queueTypes}
            selectedQueue={selectedQueue}
            onQueueChange={setSelectedQueue}
            disabled={isUploading || isUploaded}
            className="mb-2"
          />

          {/* Hashtag Preset Toggle */}
          <HashtagPresetToggle
            presets={hashTagPresets}
            selectedPresetId={selectedHashtagPresetId}
            onSelect={handleHashtagPresetSelect}
            disabled={isUploading || isUploaded}
            useHashtagPresets={useHashtagPresets}
            onUseHashtagPresetsChange={setUseHashtagPresets}
            showQueuePreset={selectedQueue !== "unassigned"}
            queueType={(queueTypes.find(
              (q) => (typeof q === "string" ? q : q.name) === selectedQueue,
            ) ?? null) as QueueType | null | undefined}
          />
          <div className="mb-2 flex items-center gap-2">
            <input
              type="checkbox"
              id="isRecyclable"
              name="isRecyclable"
              checked={isRecyclable}
              onChange={(e) => setIsRecyclable(e.target.checked)}
              disabled={isUploading || isUploaded}
              className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <label
              htmlFor="isRecyclable"
              className="text-sm text-gray-700 dark:text-gray-300"
            >
              Make this post recyclable
            </label>
          </div>
          <SchedulingSection
            scheduledFor={scheduledFor}
            onScheduledForChange={setScheduledFor}
            scheduleIntervals={scheduleIntervals}
            queueTypes={queueTypes}
            selectedQueue={selectedQueue}
            onScheduleIntervalClick={(intervalHours) => void handleScheduleIntervalClick(intervalHours)}
            onCalculateNextSlot={() => {
              void calculateQueueScheduleTime(selectedQueue);
            }}
            disabled={isUploading || isUploaded}
            showTimeInput={true}
          />
          {timeError ? (
            <p className="text-sm text-red-500">{timeError}</p>
          ) : null}
        </div>
        <div className="flex flex-col items-end gap-2">
          {uploadProvider ? (
            <div className="flex items-center gap-1 text-xs text-gray-500">
              <span>Upload via:</span>
              <span
                className={`rounded px-2 py-1 text-xs font-medium ${
                  uploadProvider.includes("BLOSSOM")
                    ? "bg-purple-100 text-purple-800"
                    : "bg-blue-100 text-blue-800"
                }`}
              >
                {uploadProvider.includes("BLOSSOM")
                  ? `🌸 ${uploadProvider === "BLOSSOM_PRIMAL" ? "Primal" : "Blosstr"}`
                  : "☁️ S3"}
              </span>
            </div>
          ) : null}
          <button
            type="submit"
            className="rounded-lg bg-green-500 px-8 py-4 text-white hover:bg-green-600 disabled:opacity-50"
            disabled={isUploading || isUploaded || files.length === 0}
          >
            {isUploading ? "Uploading..." : "Upload Media →"}
          </button>
        </div>
      </div>
    </form>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";
import { toast } from "react-hot-toast";

import { Button } from "~/components/ui/button";
import { Checkbox } from "~/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "~/components/ui/dialog";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "~/components/ui/select";
import type { QueueType } from "~/features/posts/types";
import { isIntervalScheduleConfig, isFixedSlotsScheduleConfig } from "~/features/posts/types";

interface QueueTypeDialogQueueType extends QueueType {
  isDefault?: boolean;
  hashTagPreset?: {
    id: string;
    name: string;
    tags: string;
    description?: string;
  } | null;
  hashTagPresetId?: string;
}

interface QueueTypeDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  queueType?: QueueTypeDialogQueueType | null;
  hashTagPresets: {
    id: string;
    name: string;
    tags: string;
    description?: string;
  }[];
}

export function QueueTypeDialog({
  open,
  onOpenChange,
  queueType,
  hashTagPresets,
}: QueueTypeDialogProps) {
  interface FetcherData {
    success?: boolean;
    error?: string;
  }
  const fetcher = useFetcher<FetcherData>();
  const [scheduleType, setScheduleType] = useState<"INTERVAL" | "FIXED_SLOTS">(
    "INTERVAL",
  );
  const [hashTagPresetId, setHashTagPresetId] = useState<string>(
    queueType?.hashTagPresetId ?? "none",
  );

  const isEditing = !!queueType;
  const isSubmitting = fetcher.state === "submitting" || fetcher.state === "loading";

  useEffect(() => {
    if (queueType) {
      setScheduleType(queueType.scheduleType ?? "INTERVAL");
      setHashTagPresetId(queueType.hashTagPresetId ?? "none");
    } else {
      setScheduleType("INTERVAL");
      setHashTagPresetId("none");
    }
  }, [queueType]);

  useEffect(() => {
    const fetcherData = fetcher.data;
    if (fetcherData && typeof fetcherData === "object" && !Array.isArray(fetcherData)) {
      const data = fetcherData as FetcherData;
      if (typeof data.success === "boolean" && data.success) {
        const action = isEditing ? "updated" : "created";
        toast.success(`Queue type ${action} successfully!`);
      }
      if (typeof data.error === "string") {
        toast.error(data.error);
      }
    }
  }, [fetcher.data, isEditing]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const formData = new FormData(e.target as HTMLFormElement);

    if (isEditing) {
      formData.set("_action", "update_queue_type");
      formData.set("id", queueType.id);
    } else {
      formData.set("_action", "create_queue_type");
    }

    fetcher.submit(formData, { method: "post" });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>
            {isEditing ? "Edit Queue Type" : "Create Queue Type"}
          </DialogTitle>
          <DialogDescription>
            {isEditing
              ? "Update the queue type settings below."
              : "Create a new queue type with custom scheduling."}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="name">Name</Label>
            <Input
              id="name"
              name="name"
              defaultValue={queueType?.name ?? ""}
              placeholder="e.g., Tech News"
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Input
              id="description"
              name="description"
              defaultValue={queueType?.description ?? ""}
              placeholder="Optional description"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="color">Color</Label>
            <Input
              id="color"
              name="color"
              type="color"
              defaultValue={queueType?.color ?? "#3B82F6"}
              className="h-10 w-full"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="hashTagPresetId">Hashtag Preset (optional)</Label>
            <Select
              value={hashTagPresetId}
              onValueChange={setHashTagPresetId}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select a hashtag preset" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="none">No hashtag preset</SelectItem>
                {hashTagPresets.map((preset) => (
                  <SelectItem key={preset.id} value={preset.id}>
                    {preset.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {/* Hidden input to ensure form submission includes the value */}
            <input
              type="hidden"
              name="hashTagPresetId"
              value={hashTagPresetId}
            />
            <p className="text-xs text-muted-foreground">
              Posts in this queue will automatically use the selected hashtag
              preset
            </p>
          </div>

          {isEditing ? (
            <div className="flex items-center space-x-2">
              <Checkbox
                id="isEnabled"
                name="isEnabled"
                defaultChecked={queueType?.isEnabled}
              />
              <Label htmlFor="isEnabled" className="text-sm font-normal">
                Enabled
              </Label>
            </div>
          ) : null}

          <div className="space-y-2">
            <Label htmlFor="scheduleType">Schedule Type</Label>
            <Select
              name="scheduleType"
              value={scheduleType}
              onValueChange={(value) =>
                setScheduleType(value as "INTERVAL" | "FIXED_SLOTS")
              }
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="INTERVAL">Interval-based</SelectItem>
                <SelectItem value="FIXED_SLOTS">Fixed time slots</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {scheduleType === "INTERVAL" ? (
            <div className="space-y-4">
              <div className="flex items-center space-x-2">
                <Checkbox
                  id="useGlobalInterval"
                  name="useGlobalInterval"
                  defaultChecked={queueType?.scheduleConfig && isIntervalScheduleConfig(queueType.scheduleConfig) ? queueType.scheduleConfig.useGlobalInterval : false}
                />
                <Label
                  htmlFor="useGlobalInterval"
                  className="text-sm font-normal"
                >
                  Use global schedule intervals
                </Label>
              </div>
              <div className="space-y-2">
                <Label htmlFor="intervalHours">Hours between posts</Label>
                <Input
                  id="intervalHours"
                  name="intervalHours"
                  type="number"
                  min="1"
                  max="168"
                  defaultValue={queueType?.scheduleConfig && isIntervalScheduleConfig(queueType.scheduleConfig) ? (queueType.scheduleConfig.intervalHours || 4) : 4}
                />
              </div>
            </div>
          ) : null}

          {scheduleType === "FIXED_SLOTS" ? (
            <div className="space-y-2">
              <Label htmlFor="slots">
                Time slots (HH:MM format, comma separated)
              </Label>
              <Input
                id="slots"
                name="slots"
                defaultValue={
                  queueType?.scheduleConfig && isFixedSlotsScheduleConfig(queueType.scheduleConfig) ? (queueType.scheduleConfig.slots?.join(", ") || "") : ""
                }
                placeholder="08:00, 12:00, 18:00"
              />
              <p className="text-xs text-muted-foreground">
                Times are in your selected timezone
              </p>
            </div>
          ) : null}

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting ? <svg
                  className="animate-spin -ml-1 mr-2 h-4 w-4 text-white"
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  ></circle>
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                  ></path>
                </svg> : null}
              {isSubmitting
                ? isEditing
                  ? "Updating..."
                  : "Creating..."
                : isEditing
                  ? "Update"
                  : "Create"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useFetcher } from "@remix-run/react";
import { Plus } from "lucide-react";
import { useState, useEffect } from "react";
import { toast } from "react-hot-toast";

import { Button } from "~/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "~/components/ui/card";
import type { QueueType } from "~/features/posts/types";

import { QueueTypeCard } from "./QueueTypeCard";
import { QueueTypeDialog } from "./QueueTypeDialog";

interface QueueTypeSettings extends QueueType {
  isDefault: boolean;
  hashTagPreset?: {
    id: string;
    name: string;
    tags: string;
    description?: string;
  } | null;
  hashTagPresetId?: string;
}

interface QueueTypesSettingsProps {
  queueTypes: QueueTypeSettings[];
  hashTagPresets: {
    id: string;
    name: string;
    tags: string;
    description?: string;
  }[];
}

export function QueueTypesSettings({
  queueTypes,
  hashTagPresets,
}: QueueTypesSettingsProps) {
  interface FetcherData {
    success?: boolean;
    error?: string;
  }
  const createFetcher = useFetcher<FetcherData>();
  const updateFetcher = useFetcher<FetcherData>();
  const deleteFetcher = useFetcher<FetcherData>();

  const [queueTypesState, setQueueTypesState] = useState(queueTypes || []);
  const [showDialog, setShowDialog] = useState(false);
  const [editingQueueType, setEditingQueueType] = useState<QueueType | null>(
    null,
  );

  const _isCreating = createFetcher.state === "submitting";
  const _isUpdating = updateFetcher.state === "submitting";
  const isDeleting = deleteFetcher.state === "submitting";

  useEffect(() => {
    if (queueTypes) {
      setQueueTypesState(queueTypes);
    }
  }, [queueTypes]);

  // Close dialog on successful submission
  useEffect(() => {
    if (createFetcher.data?.success) {
      setShowDialog(false);
      toast.success("Queue type created successfully!");
    }
    if (createFetcher.data?.error) {
      toast.error(createFetcher.data.error);
    }
  }, [createFetcher.data]);

  useEffect(() => {
    if (updateFetcher.data?.success) {
      setEditingQueueType(null);
      toast.success("Queue type updated successfully!");
    }
    if (updateFetcher.data?.error) {
      toast.error(updateFetcher.data.error);
    }
  }, [updateFetcher.data]);

  useEffect(() => {
    if (deleteFetcher.data?.success) {
      toast.success("Queue type deleted successfully!");
    }
    if (deleteFetcher.data?.error) {
      toast.error(deleteFetcher.data.error);
    }
  }, [deleteFetcher.data]);

  const handleCreateNew = () => {
    setEditingQueueType(null);
    setShowDialog(true);
  };

  const handleEdit = (queueType: QueueType) => {
    setEditingQueueType(queueType);
    setShowDialog(true);
  };

  const handleDialogOpenChange = (open: boolean) => {
    if (!open) {
      setEditingQueueType(null);
    }
    setShowDialog(open);
  };

  return (
    <>
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Queue Types</CardTitle>
              <CardDescription>
                Manage your posting queues with custom scheduling
              </CardDescription>
            </div>
            <Button onClick={handleCreateNew}>
              <Plus className="mr-2 h-4 w-4" />
              Add Queue Type
            </Button>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          {queueTypesState.length === 0 ? (
            <p className="py-8 text-center text-muted-foreground">
              No queue types found. Create your first queue type to get started.
            </p>
          ) : (
            queueTypesState.map((queueType) => (
              <QueueTypeCard
                key={queueType.id}
                queueType={queueType}
                onEdit={handleEdit}
                isDeletingQueueType={isDeleting}
                deleteFetcher={deleteFetcher}
              />
            ))
          )}
        </CardContent>
      </Card>

      <QueueTypeDialog
        open={showDialog}
        onOpenChange={handleDialogOpenChange}
        queueType={editingQueueType}
        hashTagPresets={hashTagPresets}
      />
    </>
  );
}

import { useFetcher } from "@remix-run/react";
import { useState, useRef } from "react";
import { toast } from "react-hot-toast";

import { HashtagPresetToggle } from "~/components/dashboard/HashtagPresetToggle";
import { Button } from "~/components/ui/button";
import { Input } from "~/components/ui/input";
import { Label } from "~/components/ui/label";
import { Textarea } from "~/components/ui/textarea";
import AssetBrowser from "~/features/assets/components/AssetBrowser";
import type { Asset } from "~/features/assets/types";
import { QueueSelector } from "~/features/posts/components/QueueSelector";
import { SchedulingSection } from "~/features/posts/components/SchedulingSection";
import { usePostScheduling } from "~/features/posts/hooks/usePostScheduling";
import type { QueueType } from "~/features/posts/types";
import { signEventFn } from "~/lib/nostr";
import { useOptionalUser } from "~/lib/remix-utils";
interface TextPostProps {
  queueTypes?: (string | QueueType)[];
  assets?: Asset[];
  hashTagPresets?: { id: string; name: string; tags: string }[];
  onQueueTypeChange?: (queueType: string) => void;
  selectedHashTagPresetId?: string | null | undefined;
  onHashtagPresetChange?: (presetId: string | null, hashtags: string) => void;
}

export default function TextPost({
  queueTypes = [],
  assets = [],
  hashTagPresets = [],
  onQueueTypeChange,
  selectedHashTagPresetId,
  onHashtagPresetChange,
}: TextPostProps) {
  const fetcher = useFetcher();
  const user = useOptionalUser();
  // Note: User doesn't have hashTags property - this would need to come from hashTagPresets relation
  const tags: string[] = [];
  const [contentError, setContentError] = useState("");
  const [showAssetBrowser, setShowAssetBrowser] = useState(false);
  const [content, setContent] = useState("");
  const [isRecyclable, setIsRecyclable] = useState(false);
  const [useHashtagPresets, setUseHashtagPresets] = useState(false);
  const [selectedHashtagPresetId, setSelectedHashtagPresetId] = useState<string | undefined>(
    selectedHashTagPresetId ? selectedHashTagPresetId : undefined,
  );
  const [selectedHashtags, setSelectedHashtags] = useState("");
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Use the shared scheduling hook
  const {
    selectedQueue,
    setSelectedQueue,
    scheduledFor,
    setScheduledFor,
    calculateQueueScheduleTime,
    handleScheduleIntervalClick,
    scheduleIntervals,
  } = usePostScheduling({
    queueTypes,
    scheduleIntervals: user?.scheduleInterval as number[] | undefined,
    userTimezone: user?.timezone ?? undefined,
    initialQueue: "unassigned",
    onQueueTypeChange,
  });

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);
    const contentValue = formData.get("content");
    const scheduledFor = formData.get("scheduledFor");
    const submitter = (e.nativeEvent as SubmitEvent).submitter as HTMLButtonElement;
    const submitType = submitter?.value ?? "";

    // Ensure queueType is set from current state
    formData.set("queueType", selectedQueue);
    // Set isRecyclable checkbox state
    if (isRecyclable) {
      formData.set("isRecyclable", "on");
    }
    // Add hashtag preset selection
    if (useHashtagPresets && selectedHashtagPresetId) {
      formData.set("hashTagPresetId", selectedHashtagPresetId);
      formData.set("useHashtagPresets", "on");
    }

    // Check if content is empty (except for draft saves)
    if (
      submitType !== "draft-text" &&
      (!contentValue || (typeof contentValue === "string" && contentValue.trim() === ""))
    ) {
      setContentError("Post content cannot be empty");
      toast.error("Post content cannot be empty");
      return;
    }

    setContentError("");

    try {
      // For draft saves, we don't need to sign the event
      if (submitType === "draft-text") {
        formData.set("_action", submitType);
        fetcher.submit(formData, { method: "post" });
        return;
      }

      const userTimezone = user?.timezone ?? "UTC";
      let scheduledTime;

      if (submitType === "post-text") {
        scheduledTime = Date.now();
      } else {
        const scheduledForStr = typeof scheduledFor === "string" ? scheduledFor : "";

        // Only convert timezone if not UTC/Etc/GMT
        if (userTimezone !== "UTC" && userTimezone !== "Etc/GMT") {
          const utcDate = new Date(scheduledForStr);

          // Get timezone offset in minutes between user timezone and UTC
          const userDateStr = new Date(scheduledForStr).toLocaleString("en-US", {
            timeZone: userTimezone,
          });
          const userDate = new Date(userDateStr);
          const scheduledDate = new Date(scheduledForStr);
          const userOffset =
            (userDate.getTime() - scheduledDate.getTime()) / 60000;

          // Adjust the date by the offset
          utcDate.setMinutes(utcDate.getMinutes() - userOffset);
          scheduledTime = utcDate.getTime();
        } else {
          // Parse date string and ensure it's in UTC
          const dateObj = new Date(scheduledForStr + "Z");
          scheduledTime = dateObj.getTime();
        }
      }

      const scheduledForUnix = Math.floor(scheduledTime / 1000);

      // Get effective hashtags - prioritize manual selection over queue defaults
      let effectiveHashtags = "";

      if (useHashtagPresets) {
        // Manual hashtag presets are enabled
        if (selectedHashtags) {
          // Use manually selected hashtag preset
          effectiveHashtags = selectedHashtags;
        }
        // If useHashtagPresets is true but no manual preset selected, use no hashtags
        // This ensures manual hashtag preset selection overrides queue defaults
      } else {
        // Manual hashtag presets are disabled, use queue type's default hashtags
        // Find the queue type object to get its ID
        const selectedQueueType = queueTypes.find(qt => 
          (typeof qt === "string" ? qt : qt.name) === selectedQueue
        );
        const queueTypeId = typeof selectedQueueType === "object" ? selectedQueueType.id : null;

        try {
          const response = await fetch("/api/effective-hashtags", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              userId: user?.id,
              queueTypeId,
              queueTypeName: selectedQueue, // Keep for backward compatibility
            }),
          });

          if (response.ok) {
            const data = (await response.json()) as { hashtags?: string };
            effectiveHashtags = data.hashtags ?? "";
          } else {
            // Fallback to user's default hashtags
            effectiveHashtags = Array.isArray(tags)
              ? tags.join(" ")
              : tags ?? "";
          }
        } catch (error) {
          const { handleErrorSafely } = await import("~/lib/error-handler.client");
          handleErrorSafely(error, {
            component: "TextPost",
            action: "fetchEffectiveHashtags",
          });
          // Fallback to user's default hashtags
          effectiveHashtags = Array.isArray(tags) ? tags.join(" ") : tags || "";
        }
      }

      const tagArray = effectiveHashtags
        .split(" ")
        .filter((tag) => tag.length > 0)
        .map((tag) => ["t", tag.replace("#", "")]);

      const contentToSign = user?.showHashTagsinPosts
        ? `${typeof contentValue === "string" ? contentValue : ""}\n${effectiveHashtags}`
        : (typeof contentValue === "string" ? contentValue : "");

      const { nostrEvent, signedEvent } = await signEventFn({
        content: contentToSign,
        created_at: scheduledForUnix,
        kind: 1,
        tags: tagArray,
      });

      formData.append("nostrEvent", JSON.stringify(nostrEvent));
      formData.append("signedEvent", JSON.stringify(signedEvent));
      formData.append("scheduledFor", scheduledForUnix.toString());
      formData.set("_action", submitType);

      fetcher.submit(formData, { method: "post" });
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(error, {
        component: "TextPost",
        action: "handleSubmit",
      }, false); // Don't show toast, let component handle it
    }
  };


  const handleHashtagPresetSelect = (
    presetId: string | null,
    hashtags: string,
  ) => {
    setSelectedHashtagPresetId(presetId ?? undefined);
    setSelectedHashtags(hashtags);
    if (onHashtagPresetChange) {
      onHashtagPresetChange(presetId, hashtags);
    }
  };

  const handleAssetsSelected = (selectedAssets: Asset[]) => {
    // Separate text assets and image assets
    const textAssets: string[] = [];
    const imageAssets: string[] = [];

    selectedAssets.forEach((asset) => {
      if (asset.assetType === "TEXT") {
        const textContent = (asset.content ?? asset.title) ?? "";
        if (textContent) {
          textAssets.push(textContent);
        }
      } else if (asset.assetType === "IMAGE") {
        const imageUrl = asset.fileUrl ?? "";
        if (imageUrl) {
          imageAssets.push(imageUrl);
        }
      }
    });

    // Combine text assets first, then image URLs
    const allAssets = [...textAssets, ...imageAssets];
    const newContent = allAssets.join("\n");

    // Always append assets below existing content
    const updatedContent = content ? content + "\n" + newContent : newContent;
    setContent(updatedContent);

    // Update the textarea value
    if (textareaRef.current) {
      textareaRef.current.value = updatedContent;
    }
  };

  return (
    <fetcher.Form method="post" className="w-full" onSubmit={(e) => void handleSubmit(e)}>
      <div className="relative">
        <Textarea
          ref={textareaRef}
          name="content"
          className={contentError ? "border-red-500" : ""}
          placeholder="Start writing your post here..."
          rows={6}
          disabled={fetcher.state !== "idle"}
          value={content}
          onChange={(e) => {
            setContent(e.target.value);
            setContentError("");
          }}
        />
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => setShowAssetBrowser(true)}
          disabled={fetcher.state !== "idle"}
          className="absolute right-2 top-2"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className="mr-1 h-4 w-4"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012 2v2M7 7h10"
            />
          </svg>
          Assets
        </Button>
      </div>
      {contentError ? (
        <div className="mt-1 text-sm text-red-500">{contentError}</div>
      ) : null}
      <div className="mt-2 text-right text-sm text-gray-500">0/2200</div>
      <div className="mt-6 flex flex-col gap-6 sm:flex-row sm:items-center sm:justify-between">
        <div className="space-y-4">
          <QueueSelector
            queueTypes={queueTypes}
            selectedQueue={selectedQueue}
            onQueueChange={setSelectedQueue}
            disabled={fetcher.state !== "idle"}
            className="mb-2"
          />

          {/* Hashtag Preset Toggle */}
          <HashtagPresetToggle
            presets={hashTagPresets}
            selectedPresetId={selectedHashtagPresetId}
            onSelect={handleHashtagPresetSelect}
            disabled={fetcher.state !== "idle"}
            useHashtagPresets={useHashtagPresets}
            onUseHashtagPresetsChange={setUseHashtagPresets}
            showQueuePreset={selectedQueue !== "unassigned"}
            queueType={queueTypes.find(
              (q) => (typeof q === "string" ? q : q.name) === selectedQueue,
            ) as QueueType | undefined}
          />
          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="isRecyclable"
              name="isRecyclable"
              checked={isRecyclable}
              onChange={(e) => setIsRecyclable(e.target.checked)}
              disabled={fetcher.state !== "idle"}
              className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <Label
              htmlFor="isRecyclable"
              className="text-sm text-gray-700 dark:text-gray-300"
            >
              Make this post recyclable
            </Label>
          </div>
          <div className="flex flex-col gap-2">
            <Label htmlFor="scheduledFor">Schedule for later</Label>
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
              <Input
                type="datetime-local"
                id="scheduledFor"
                name="scheduledFor"
                value={scheduledFor ?? ""}
                onChange={(e) => {
                  setScheduledFor(e.target.value);
                }}
                disabled={fetcher.state !== "idle"}
              />
              <Button
                type="submit"
                value="schedule-text"
                name="_action"
                disabled={fetcher.state !== "idle"}
                className="text-white"
              >
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="mr-1.5 h-5 w-5"
                  viewBox="0 0 20 20"
                  fill="currentColor"
                >
                  <path
                    fillRule="evenodd"
                    d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z"
                    clipRule="evenodd"
                  />
                </svg>
                {fetcher.state !== "idle"
                  ? "Scheduling..."
                  : "Sign and Schedule"}
              </Button>
            </div>
            <SchedulingSection
              scheduledFor={scheduledFor}
              onScheduledForChange={setScheduledFor}
              scheduleIntervals={scheduleIntervals}
              queueTypes={queueTypes}
              selectedQueue={selectedQueue}
              onScheduleIntervalClick={(intervalHours) => void handleScheduleIntervalClick(intervalHours)}
              onCalculateNextSlot={() => {
                void calculateQueueScheduleTime(selectedQueue);
              }}
              disabled={fetcher.state !== "idle"}
              showTimeInput={false}
            />
          </div>
        </div>
