/**
 * Main action handler for new longform post page
 */
export async function handleNewLongFormAction(
  userId: string,
  request: Request,
): Promise<Response> {
  const user = await getUserById(userId);
  if (!user) {
    return new Response("User not found", { status: 404 });
  }
  const { userRelays, showHashTagsinPosts } = user;
  const sanitizedRelays = userRelays.map((relay: string) => relay.trim());

  const contentType = request.headers.get("Content-Type") ?? "";
  let formData: FormData;

  if (contentType.includes("multipart/form-data")) {
    const uploadHandler = composeUploadHandlers(
      createUploadHandler(userId),
      createMemoryUploadHandler(),
    );
    formData = await parseMultipartFormData(request, uploadHandler);
  } else {
    formData = await request.formData();
  }

  const _action = formData.get("_action") as string;
  const queueType = (formData.get("queueType") as string) ?? "Unassigned";
  const useHashtagPresets = formData.get("useHashtagPresets") === "on";
  const manualHashTagPresetId = useHashtagPresets
    ? ((formData.get("hashTagPresetId") as string) ?? null)
    : null;

  // Handle upload-image action first, before any validation
  if (_action === "upload-image") {
    return handleImageUpload(userId, formData);
  }

  // Get hashtag preset tags
  const { tags: hashTagPresetTags, presetId: hashTagPresetId } =
    await getHashtagPresetTags(
      userId,
      useHashtagPresets,
      manualHashTagPresetId,
      queueType,
    );

  // Handle different actions
  if (_action === "save-draft") {
    return handleSaveDraft(userId, formData, queueType, hashTagPresetId);
  }

  if (_action === "publish") {
    return handlePublish(
      userId,
      formData,
      queueType,
      hashTagPresetId,
      hashTagPresetTags,
      showHashTagsinPosts,
      sanitizedRelays,
    );
  }

  if (_action === "schedule-longform") {
    return handleScheduleLongform(
      userId,
      formData,
      queueType,
      hashTagPresetId,
      hashTagPresetTags,
      showHashTagsinPosts,
    );
  }

  return Response.json({ success: false });
}

