async function createImageUploadHandler(uploadProvider: string | null) {
  return async (file: File) => {
    try {
      logClientError(
        "Starting EditorJS image upload",
        {
          component: "createImageUploadHandler",
          action: "uploadImage",
          fileName: file.name,
          fileSize: file.size,
          uploadProvider,
        },
        "info",
      );

      // Check upload provider and use appropriate method
      if (uploadProvider && uploadProvider.includes("BLOSSOM")) {
        // Use client-side upload for Blossom
        const { uploadFile } = await import("~/features/upload/upload.client");
        const uploadResult = await uploadFile(file);

        if (uploadResult.success && uploadResult.file) {
          logClientError(
            "Blossom upload successful",
            {
              component: "createImageUploadHandler",
              action: "uploadImage",
              provider: "Blossom",
              fileUrl: uploadResult.file.url,
            },
            "info",
          );
          return {
            success: 1,
            file: {
              url: uploadResult.file.url,
              size: uploadResult.file.size || file.size,
              name: uploadResult.file.name || file.name,
              extension: uploadResult.file.extension || file.name.split(".").pop(),
            },
          };
        } else {
          const { logClientError } = await import("~/lib/error-handler.client");
          logClientError(
            new Error(uploadResult.error ?? "Blossom upload failed"),
            {
              component: "useLongFormEditor",
              action: "uploadImage",
              provider: "Blossom",
            },
            "warning",
          );
          throw new Error(uploadResult.error ?? "Blossom upload failed");
        }
      } else {
        // Use server-side upload for S3
        const formData = new FormData();
        formData.append("image", file);

        const response = await fetch(
          "/api/upload-editorjs-image",
          {
            method: "POST",
            body: formData,
          },
        );

        if (!response.ok) {
          const errorText = await response.text();
          const { logClientError } = await import("~/lib/error-handler.client");
          logClientError(
            new Error(`Server error: ${response.status}`),
            {
              component: "useLongFormEditor",
              action: "uploadImage",
              provider: "S3",
              serverResponse: errorText,
            },
            "error",
          );
          throw new Error(`Server error: ${response.status}`);
        }

        const result = (await response.json()) as {
          success?: number;
          file?: { url?: string; size?: number; name?: string; extension?: string };
          error?: string;
        };
        logClientError(
          "S3 EditorJS upload response",
          {
            component: "createImageUploadHandler",
            action: "uploadImage",
            provider: "S3",
            response: result,
          },
          "info",
        );

        if (result.success === 1 && result.file?.url) {
          logClientError(
            "S3 upload successful",
            {
              component: "createImageUploadHandler",
              action: "uploadImage",
              provider: "S3",
              fileUrl: result.file.url,
            },
            "info",
          );
          return {
            success: 1,
            file: {
              url: result.file.url,
              size: result.file.size ?? file.size,
              name: result.file.name ?? file.name,
              extension:
                result.file.extension ??
                file.name.split(".").pop(),
            },
          };
        } else {
          const { logClientError } = await import("~/lib/error-handler.client");
          logClientError(
            new Error(result.error ?? "Upload failed"),
            {
              component: "useLongFormEditor",
              action: "uploadImage",
              provider: "S3",
            },
            "warning",
          );
          throw new Error(result.error ?? "Upload failed");
        }
      }
    } catch (error) {
      const { handleAsyncError } = await import("~/lib/error-handler.client");
      handleAsyncError(error, {
        component: "useLongFormEditor",
        action: "uploadImage",
      }, false); // Don't show toast, let EditorJS handle it
      throw error;
    }
  };
}

/**
 * EditorJS content loading and manipulation utilities
 */


import type React from "react";

import type { EditorJSInstance, EditorJSBlock } from "~/features/posts/types/editorjs.types";
import { handleErrorSafely, logClientError } from "~/lib/error-handler.client";
import { convertMarkdownToEditorJS } from "~/lib/nostr";
/**
 * Load initial content into EditorJS
 */
export async function loadEditorJSContent(
  editorRef: React.RefObject<EditorJSInstance>,
  content: string,
  onContentChange: (content: string) => void,
) {
  if (!editorRef.current || !content) return;

  try {
    await editorRef.current.isReady;

    let parsedContent;

    // Try to parse as JSON first (for legacy EditorJS format)
    if (content.trim().startsWith("{")) {
      try {
        parsedContent = JSON.parse(content) as { blocks?: unknown[]; time?: number; version?: string };
        // Validate it has EditorJS structure
        if (
          !parsedContent.blocks ||
          !Array.isArray(parsedContent.blocks)
        ) {
          throw new Error("Not valid EditorJS format");
        }
      } catch (jsonError) {
        logClientError(
          jsonError instanceof Error ? jsonError : new Error(String(jsonError)),
          {
            component: "loadEditorJSContent",
            action: "parseContent",
            message: "Content is not valid EditorJS JSON, treating as markdown",
          },
          "warning",
        );
        // If JSON parsing fails, treat as markdown and convert to EditorJS
        parsedContent = convertMarkdownToEditorJS(content);
      }
    } else {
      // Content is in markdown format, convert to EditorJS
      logClientError(
        "Converting markdown content to EditorJS format",
        {
          component: "loadEditorJSContent",
          action: "convertMarkdown",
        },
        "info",
      );
      parsedContent = convertMarkdownToEditorJS(content);
    }

    await editorRef.current.render({ blocks: (parsedContent.blocks ?? []) as EditorJSBlock[], time: parsedContent.time, version: parsedContent.version });
    onContentChange(JSON.stringify(parsedContent));
  } catch (error) {
    const { handleAsyncError } = await import("~/lib/error-handler.client");
    handleAsyncError(error, {
      component: "useLongFormEditor",
      action: "loadInitialData",
    }, false);
    // Fallback to empty editor if all else fails
    try {
      const emptyContent = { blocks: [] };
      await editorRef.current.render(emptyContent);
      onContentChange(JSON.stringify(emptyContent));
    } catch (fallbackError) {
      const { handleAsyncError: handleFallbackError } = await import("~/lib/error-handler.client");
      handleFallbackError(fallbackError, {
        component: "useLongFormEditor",
        action: "loadInitialDataFallback",
      }, false);
    }
  }
}

/**
 * Insert assets into the editor
 */
export async function insertAssetsIntoEditor(
  editorRef: React.RefObject<EditorJSInstance>,
  selectedAssets: {
    assetType: string;
    fileUrl?: string;
    content?: string;
    title?: string;
  }[],
  onContentChange: (content: string) => void,
) {
  if (!editorRef.current) return;

  try {
    // Wait for editor to be ready
    await editorRef.current.isReady;

    // Get current editor data and insert at current block position
    const currentData = await editorRef.current.saver.save();
    const blocks = [...currentData.blocks];

    // Try to get current block index
    let insertIndex = blocks.length; // Default to end
    try {
      const currentBlockIndex =
        editorRef.current.blocks.getCurrentBlockIndex();
      if (currentBlockIndex >= 0) {
        insertIndex = currentBlockIndex + 1; // Insert after current block
      }
    } catch (error) {
      logClientError(
        "Using default insertion position at end",
        {
          component: "insertAssetsIntoEditor",
          action: "getCurrentBlockIndex",
          error: error instanceof Error ? error.message : String(error),
        },
        "info",
      );
    }

    // Create new blocks for assets
    const newBlocks: EditorJSBlock[] = [];
    for (const asset of selectedAssets) {
      if (asset.assetType === "TEXT") {
        const textContent = asset.content || asset.title || "";
        if (textContent) {
          newBlocks.push({
            id: Math.random().toString(36).substr(2, 9),
            type: "paragraph",
            data: {
              text: textContent,
            },
          });
        }
      } else if (asset.assetType === "IMAGE") {
        newBlocks.push({
          id: Math.random().toString(36).substr(2, 9),
          type: "image",
          data: {
            file: {
              url: asset.fileUrl,
            },
            caption: "",
            withBorder: false,
            withBackground: false,
            stretched: false,
          },
        });
      }
    }

    // Insert new blocks at the determined position
    blocks.splice(insertIndex, 0, ...newBlocks);

    // Render the updated data
    const updatedData = {
      ...currentData,
      blocks: blocks,
    };

    await editorRef.current.render(updatedData);
    onContentChange(JSON.stringify(updatedData));

    // Focus editor
    setTimeout(() => {
      editorRef.current?.focus();
    }, 100);
  } catch (error) {
    const { handleAsyncError } = await import("~/lib/error-handler.client");
    handleAsyncError(error, {
      component: "useLongFormEditor",
      action: "insertAssetIntoEditor",
    }, false);
    // Fallback to simple insertion
    try {
      for (const asset of selectedAssets) {
        if (asset.assetType === "TEXT") {
          const textContent = asset.content || asset.title || "";
          if (textContent) {
            editorRef.current.blocks.insert("paragraph", {
              text: textContent,
            });
          }
        } else if (asset.assetType === "IMAGE") {
          editorRef.current.blocks.insert("image", {
            file: {
              url: asset.fileUrl,
            },
            caption: "",
            withBorder: false,
            withBackground: false,
            stretched: false,
          });
        }
      }
      const saveResult = editorRef.current.saver.save();
      const isPromise = saveResult !== null && saveResult !== undefined && typeof saveResult === "object" && "then" in saveResult && typeof (saveResult as { then?: unknown }).then === "function";
      const updatedData = isPromise ? await (saveResult as Promise<unknown>) : (saveResult as unknown);
      onContentChange(JSON.stringify(updatedData));
    } catch (fallbackError) {
      const { handleAsyncError: handleFallbackError } = await import("~/lib/error-handler.client");
      handleFallbackError(fallbackError, {
        component: "useLongFormEditor",
        action: "insertAssetIntoEditorFallback",
      }, false);
    }
  }
}

/**
 * Generate summary from editor content
 */
export function generateSummaryFromContent(content: string): string {
  if (!content) return "";

  try {
    const parsed: unknown = JSON.parse(content);
    const editorData = parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as { blocks?: EditorJSBlock[] } : { blocks: [] };
    let textContent = "";

    if (Array.isArray(editorData.blocks)) {
      (editorData.blocks).forEach((block: EditorJSBlock) => {
        if (block.type === "paragraph" || block.type === "header") {
          const textValue = block.data && typeof block.data === "object" && "text" in block.data && typeof (block.data as { text?: unknown }).text === "string" ? (block.data as { text: string }).text : "";
          textContent += textValue + " ";
        } else if (block.type === "list") {
          if (Array.isArray(block.data.items)) {
            block.data.items.forEach((item: string) => {
              textContent += item + " ";
            });
          }
        }
      });
    }

    const plainText = textContent.replace(/<[^>]*>/g, "").trim();
    const generatedSummary =
      plainText.length > 280
        ? plainText.substring(0, 280) + "..."
        : plainText;

    return generatedSummary;
  } catch (error) {
    handleErrorSafely(error, {
      component: "useLongFormEditor",
      action: "generateSummaryFromContent",
    });
    return "";
  }
}

/**
 * EditorJS drag and drop functionality
 */

import type { EditorJSBlock, EditorJSInstance } from "~/features/posts/types/editorjs.types";
export function setupCustomDragDrop(
  editorRef: React.RefObject<EditorJSInstance>,
  editorElement: HTMLElement,
  onContentChange: (content: string) => void,
  disableCaptions: () => void,
) {
  let draggedBlockIndex: number | null = null;
  let draggedBlockData: EditorJSBlock | null = null;

  const addDragHandlers = () => {
    const blocks = editorElement.querySelectorAll(".ce-block");

    blocks.forEach((block, index) => {
      const blockElement = block as HTMLElement;
      // Remove existing handlers to avoid duplicates
      // Note: removeEventListener requires exact function reference match, so we skip removal
      // and rely on the event listener system to handle duplicates

      // Make blocks draggable
      blockElement.draggable = true;
      blockElement.dataset.blockIndex = String(index);

      // Add drag handlers
      blockElement.addEventListener("dragstart", (e) => { void handleDragStart(e); });
      blockElement.addEventListener("dragend", (e) => { handleDragEnd(e); });
      blockElement.addEventListener("dragover", (e) => { handleDragOver(e); });
      blockElement.addEventListener("drop", (e) => { void handleDrop(e); });
    });
  };

  const handleDragStart = async (e: Event) => {
    const dragEvent = e as DragEvent;
    const blockElement = (dragEvent.target as HTMLElement).closest(".ce-block") as HTMLElement;
    draggedBlockIndex = parseInt(blockElement.dataset.blockIndex || "0");

    // Get block data using EditorJS API
    try {
      const currentData = await editorRef.current!.saver.save();
      draggedBlockData = currentData.blocks[draggedBlockIndex];

      dragEvent.dataTransfer!.effectAllowed = "move";
      dragEvent.dataTransfer!.setData("text/html", blockElement.outerHTML);

      blockElement.style.opacity = "0.5";
      blockElement.classList.add("dragging");
    } catch (error) {
      const { handleErrorSafely } = await import("~/lib/error-handler.client");
      handleErrorSafely(error, {
        component: "useLongFormEditor",
        action: "handleDragStart",
      });
    }
  };

  const handleDragEnd = (e: Event) => {
    const blockElement = (e.target as HTMLElement).closest(".ce-block") as HTMLElement;
    if (blockElement) {
      blockElement.style.opacity = "1";
      blockElement.classList.remove("dragging");
    }

    // Clean up
    draggedBlockIndex = null;
    draggedBlockData = null;
  };

  const handleDragOver = (e: Event) => {
    e.preventDefault();
    const dragEvent = e as DragEvent;
    dragEvent.dataTransfer!.dropEffect = "move";

    const blockElement = (dragEvent.target as HTMLElement).closest(".ce-block") as HTMLElement;
    if (blockElement && draggedBlockIndex !== null) {
      blockElement.classList.add("drag-over");
    }
  };

  const handleDrop = async (e: Event) => {
    e.preventDefault();
    e.stopPropagation();

    const dropBlockElement = (e.target as HTMLElement).closest(".ce-block") as HTMLElement;
    if (
      !dropBlockElement ||
      draggedBlockIndex === null ||
      !draggedBlockData
    )
      return;

    const dropIndex = parseInt(dropBlockElement.dataset.blockIndex || "0");

    // Don't do anything if dropping on the same position
    if (draggedBlockIndex === dropIndex) return;

    try {
      // Get current editor data
      const currentData = await editorRef.current!.saver.save();
      const blocks = [...currentData.blocks];

      // Remove the dragged block from its original position
      blocks.splice(draggedBlockIndex, 1);

      // Calculate the new insertion index
      let newIndex = dropIndex;
      if (draggedBlockIndex < dropIndex) {
        newIndex = dropIndex - 1;
      }

      // Insert the block at the new position
      blocks.splice(newIndex, 0, draggedBlockData);

      // Update the editor with the new order
      const newData = {
        ...currentData,
        blocks: blocks,
      };

      await editorRef.current!.render(newData);
      onContentChange(JSON.stringify(newData));

      const { logClientError } = await import("~/lib/error-handler.client");
      logClientError(
        `Moved block from index ${draggedBlockIndex} to ${newIndex}`,
        {
          component: "editorjs-dragdrop",
          action: "handleDrop",
          draggedBlockIndex,
          newIndex,
        },
        "info",
      );
    } catch (error) {
      const { handleErrorSafely } = await import("~/lib/error-handler.client");
      handleErrorSafely(error, {
        component: "useLongFormEditor",
        action: "handleDrop",
      });
    } finally {
      // Clean up drag state
      dropBlockElement.classList.remove("drag-over");
      document.querySelectorAll(".ce-block").forEach((block) => {
        block.classList.remove("drag-over", "dragging");
      });
    }
  };

  // Initial setup
  addDragHandlers();

  // Re-add handlers when content changes
  const dragObserver = new MutationObserver(() => {
    setTimeout(() => {
      addDragHandlers();
      // Remove captions that might have been added
      setTimeout(disableCaptions, 50);
    }, 100);
  });

  dragObserver.observe(editorElement, {
    childList: true,
    subtree: true,
  });

  return dragObserver;
}

import { useFetcher, useLocation } from "@remix-run/react";
import { useState, useEffect, useRef } from "react";

import { type Asset, type AssetFetcher } from "~/features/assets";
import type { Template, ScheduleData, TemplateFetcher } from "~/features/templates/types";
import { resizeImageClient, uploadFile, uploadMultipleFiles } from "~/features/upload";

interface UseTemplatesStateProps {
  searchTerm: string;
}

/**
 * Custom hook for managing templates/assets state and operations
 */
export function useTemplatesState({ searchTerm }: UseTemplatesStateProps) {
  const [selectedTemplate, setSelectedTemplate] = useState<Template | null>(null);
  const [activeTab, setActiveTab] = useState<"assets" | "upload">("assets");
  const [selectedAssets, setSelectedAssets] = useState<string[]>([]);
  const [searchInput, setSearchInput] = useState(searchTerm || "");
  const [bulkUploadFiles, setBulkUploadFiles] = useState<File[]>([]);
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState("");
  const [uploadProvider, setUploadProvider] = useState<string | null>(null);
  const [singleFileUploading, setSingleFileUploading] = useState(false);
  const [bulkFileUploading, setBulkFileUploading] = useState(false);

  const textAssetFormRef = useRef<HTMLFormElement>(null);
  const imageAssetFormRef = useRef<HTMLFormElement>(null);
  const location = useLocation();

  const deleteFetcher = useFetcher();
  const scheduleFetcher: TemplateFetcher = useFetcher<{ scheduleData?: ScheduleData[] }>();
  const assetFetcher = useFetcher<{ success?: boolean; asset?: Asset; assets?: Asset[] }>() as AssetFetcher;

  // Fetch upload provider on component mount
  useEffect(() => {
    void (async () => {
      try {
        const res = await fetch("/api/user-upload-provider");
        const dataRaw: unknown = await res.json();
        const data = typeof dataRaw === "object" && dataRaw !== null && !Array.isArray(dataRaw) ? dataRaw as { provider?: unknown } : {};
        const provider = typeof data.provider === "string" ? data.provider : null;
        setUploadProvider(provider);
      } catch (err) {
        console.error("Failed to get upload provider:", err);
      }
    })();
  }, []);

  // Check if we're on a child route (edit page)
  const isOnChildRoute = location.pathname.includes("/edit/");

  // Handle schedule data response
  useEffect(() => {
    const fetcherData = scheduleFetcher.data;
    const scheduleData = fetcherData && typeof fetcherData === "object" && fetcherData !== null && "scheduleData" in fetcherData ? fetcherData.scheduleData : undefined;
    if (scheduleData && Array.isArray(scheduleData)) {
      sessionStorage.setItem(
        "repostData",
        JSON.stringify(scheduleData),
      );
      window.location.href = "/dashboard/bulkposts?mode=recycle";
    }
  }, [scheduleFetcher.data]);

  // Handle successful asset creation
  useEffect(() => {
    const fetcherData = assetFetcher.data;
    if (fetcherData && typeof fetcherData === "object" && fetcherData !== null && "success" in fetcherData && fetcherData.success) {
      if ("asset" in fetcherData && fetcherData.asset && typeof fetcherData.asset === "object" && "assetType" in fetcherData.asset) {
        const assetType = typeof fetcherData.asset.assetType === "string" ? fetcherData.asset.assetType : "asset";
        setToastMessage(
          `${assetType.toLowerCase()} asset created successfully!`,
        );
      } else if ("assets" in fetcherData && Array.isArray(fetcherData.assets)) {
        setToastMessage(
          `${fetcherData.assets.length} image assets uploaded successfully!`,
        );
      } else {
        setToastMessage("Asset created successfully!");
      }
      setShowToast(true);

      if (textAssetFormRef.current) {
        textAssetFormRef.current.reset();
      }
      if (imageAssetFormRef.current) {
        imageAssetFormRef.current.reset();
      }

      setBulkUploadFiles([]);
      setTimeout(() => setShowToast(false), 3000);
      window.location.reload();
    }
  }, [assetFetcher.data]);

  // Asset management ha??lers
  const handleAssetSelect = (assetId: string) => {
    setSelectedAssets((prev) =>
      prev.includes(assetId)
        ? prev.filter((id) => id !== assetId)
        : [...prev, assetId],
    );
  };

  const handleSelectAllAssets = (assets: Asset[]) => {
    if (selectedAssets.length === assets.length) {
      setSelectedAssets([]);
    } else {
      setSelectedAssets(assets.map((asset) => asset.id));
    }
  };

  const handleBulkPostAssets = (assets: Asset[]) => {
    if (selectedAssets.length === 0) return;

    const selectedAssetData = assets.filter((asset) =>
      selectedAssets.includes(asset.id),
    );

    const assetData = selectedAssetData.map((asset) => ({
      caption: asset.assetType === "TEXT" ? asset.content : asset.title || "",
      fileUrl:
        asset.assetType === "IMAGE" || asset.assetType === "VIDEO"
          ? asset.fileUrl
          : null,
      queueType: "unassigned",
      scheduledFor: new Date(Date.now() + 60 * 60 * 1000)
        .toISOString()
        .slice(0, 16),
    }));

    sessionStorage.setItem("repostData", JSON.stringify(assetData));
    window.location.href = "/dashboard/bulkposts?mode=recycle";
  };

  const handleBulkDeleteAssets = () => {
    if (selectedAssets.length === 0) return;

    if (
      !confirm(
        `Are you sure you want to delete ${selectedAssets.length} selected asset${selectedAssets.length > 1 ? "s" : ""}?`,
      )
    ) {
      return;
    }

    const formData = new FormData();
    formData.append("_action", "bulk_delete_assets");
    selectedAssets.forEach((assetId) => {
      formData.append("assetIds", assetId);
    });

    deleteFetcher.submit(formData, { method: "post" });
    setSelectedAssets([]);
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    const url = new URL(window.location.href);
    if (searchInput.trim()) {
      url.searchParams.set("search", searchInput.trim());
    } else {
      url.searchParams.delete("search");
    }
    url.searchParams.delete("page");
    window.location.href = url.toString();
  };

  const handlePageChange = (newPage: number) => {
    setSelectedAssets([]);
    const url = new URL(window.location.href);
    if (newPage === 1) {
      url.searchParams.delete("page");
    } else {
      url.searchParams.set("page", newPage.toString());
    }
    window.location.href = url.toString();
  };

  const handleDeleteAsset = (e: React.MouseEvent<HTMLButtonElement>, _assetId: string) => {
    if (!confirm("Are you sure you want to dele?? this asset?")) {
      e.preventDefault();
    }
  };

  // Upload handlers
  const handleSingleFileUpload = async (
    e: React.FormEvent,
    form: HTMLFormElement,
  ) => {
    e.preventDefault();
    setSingleFileUploading(true);

    try {
      const formData = new FormData(form);
      const fileInput = form.querySelector(
        'input[type="file"]',
      ) as HTMLInputElement;
      const file = fileInput?.files?.[0];

      if (!file) {
        throw new Error("No file selected");
      }

      const processedFile = file.type.startsWith("image/")
        ? await resizeImageClient(file)
        : file;

      const uploadResult = await uploadFile(processedFile);

      if (!uploadResult.success) {
        throw new Error(uploadResult.error || "Upload failed");
      }

      const serverFormData = new FormData();
      serverFormData.append("_action", formData.get("_action") as string);
      serverFormData.append("title", formData.get("title") as string);
      serverFormData.append("tags", formData.get("tags") as string);
      serverFormData.append("uploadResult", JSON.stringify(uploadResult));

      assetFetcher.submit(serverFormData, { method: "post" });
    } catch (error: unknown) {
      console.error("Upload error:", error);
      const errorMessage = error instanceof Error ? error.message : "Unknown error";
      setToastMessage(`Upload failed: ${errorMessage}`);
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } finally {
      setSingleFileUploading(false);
    }
  };

  const handleBulkFileUpload = async () => {
    if (bulkUploadFiles.length === 0) return;

    setBulkFileUploading(true);

    try {
      const uploadResults = await uploadMultipleFiles(bulkUploadFiles);

      const failedUploads = uploadResults.filter((result) => !result.success);
      if (failedUploads.length > 0) {
        const errorMessages = failedUploads
          .map((result) => result.error)
          .join(", ");
        throw new Error(`Upload failed: ${errorMessages}`);
      }

      const bulkForm = document.querySelector(
        "form[data-bulk-form]",
      ) as HTMLFormElement;
      if (!bulkForm) throw new Error("Bulk form not found");

      const formData = new FormData(bulkForm);
      const serverFormData = new FormData();
      serverFormData.append("_action", "bulk_create_media_assets");
      serverFormData.append("uploadResults", JSON.stringify(uploadResults));

      const titles = formData.getAll("titles");
      const tags = formData.getAll("tags");
      titles.forEach((title) =>
        serverFormData.append("titles", title as string),
      );
      tags.forEach((tag) => serverFormData.append("tags", tag as string));

      assetFetcher.submit(serverFormData, { method: "post" });
    } catch (error: unknown) {
      console.error("Bulk upload error:", error);
      const errorMessage = error instanceof Error ? error.message : "Unknown error";
      setToastMessage(`Bulk upload failed: ${errorMessage}`);
      setShowToast(true);
      setTimeout(() => setShowToast(false), 3000);
    } finally {
      setBulkFileUploading(false);
    }
  };

  const handleBulkFileChange = async (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => {
    if (e.target.files) {
      const selectedFiles = Array.from(e.target.files);

      try {
        const processedFiles = await Promise.all(
          selectedFiles.map(async (file) => {
            if (file.type.startsWith("image/")) {
              return await resizeImageClient(file);
            }
            return file;
          }),
        );
        setBulkUploadFiles(processedFiles);
      } catch (error) {
        console.error("Error processing media files:", error);
        setBulkUploadFiles(selectedFiles);
      }
    }
  };

  return {
    selectedTemplate,
    activeTab,
    selectedAssets,
    searchInput,
    bulkUploadFiles,
    showToast,
    toastMessage,
    uploadProvider,
    singleFileUploading,
    bulkFileUploading,
    textAssetFormRef,
    imageAssetFormRef,
    isOnChildRoute,
    deleteFetcher,
    scheduleFetcher,
    assetFetcher,
    setSelectedTemplate,
    setActiveTab,
    setSearchInput,
    handleAssetSelect,
    handleSelectAllAssets,
    handleBulkPostAssets,
    handleBulkDeleteAssets,
    handleSearch,
    handlePageChange,
    handleDeleteAsset,
    handleSingleFileUpload,
    handleBulkFileUpload,
    handleBulkFileChange,
  };
}

/**
 * Templates action handlers
 * Centralized action processing for templates page
 */

import { AssetType } from "@prisma/client";

import {
  createAsset,
  deleteAsset,
} from "~/models/asset.server";
import { deleteTemplate, getTemplates } from "~/models/template.server";

export async function handleTemplatesAction(
  formData: FormData,
  userId: string,
) {
  const _action = formData.get("_action");

  if (_action === "delete") {
    const templateId = formData.get("templateId");
    await deleteTemplate({ id: templateId as string, userId });
    return { success: true };
  }

  if (_action === "delete_asset") {
    const assetId = formData.get("assetId");
    await deleteAsset({ id: assetId as string, userId });
    return { success: true };
  }

  if (_action === "create_text_asset") {
    const title = formData.get("title") as string;
    const content = formData.get("content") as string;
    const tagsString = formData.get("tags") as string;
    const tags = tagsString
      ? tagsString
          .split(",")
          .map((tag) => tag.trim())
          .filter(Boolean)
      : [];

    const asset = await createAsset({
      userId,
      title,
      content,
      tags,
      assetType: AssetType.TEXT,
    });

    return { success: true, asset };
  }

  if (
    _action === "create_image_asset" ||
    _action === "create_video_asset" ||
    _action === "create_media_asset"
  ) {
    const title = formData.get("title") as string;
    const uploadResultRaw = formData.get("uploadResult");
    const uploadResultParsed: unknown = typeof uploadResultRaw === "string" ? JSON.parse(uploadResultRaw) : null;

    if (!uploadResultParsed || typeof uploadResultParsed !== "object" || Array.isArray(uploadResultParsed)) {
      return { error: "Invalid upload result format" };
    }

    const uploadResult = uploadResultParsed as unknown as { success?: unknown; file?: { url?: string; mimeType?: string } };

    const tagsString = formData.get("tags") as string;
    const tags = tagsString
      ? tagsString
          .split(",")
          .map((tag) => tag.trim())
          .filter(Boolean)
      : [];

    if (!uploadResult.success || !uploadResult.file?.url) {
      return { error: "No file uploaded or upload failed" };
    }

    const fileUrl = uploadResult.file.url;
    if (typeof fileUrl !== "string") {
      return { error: "Invalid file URL" };
    }

    // Determine asset type based on file URL extension or mime type
    let assetType: typeof AssetType.IMAGE | typeof AssetType.VIDEO = AssetType.IMAGE;
    const mimeType = typeof uploadResult.file.mimeType === "string" ? uploadResult.file.mimeType : "";
    const lower = fileUrl.toLowerCase();
    const videoExtensions = [
      ".mp4",
      ".webm",
      ".ogg",
      ".mov",
      ".avi",
      ".mkv",
      ".m4v",
    ];

    if (
      mimeType.startsWith("video/") ||
      videoExtensions.some((ext) => lower.includes(ext))
    ) {
      assetType = AssetType.VIDEO;
    }

    const asset = await createAsset({
      userId,
      title,
      fileUrl,
      tags,
      assetType,
    });

    return { success: true, asset };
  }

  if (
    _action === "bulk_create_image_assets" ||
    _action === "bulk_create_media_assets"
  ) {
    const uploadResultsRaw = formData.get("uploadResults");
    const uploadResultsParsed: unknown = typeof uploadResultsRaw === "string" ? JSON.parse(uploadResultsRaw) : null;

    if (!Array.isArray(uploadResultsParsed)) {
      return { error: "Invalid upload results format" };
    }

    const uploadResults = uploadResultsParsed as unknown as { success?: unknown; file?: { url?: string; mimeType?: string } | undefined; error?: string }[];
    const titles = formData.getAll("titles") as string[];
    const tagsInputs = formData.getAll("tags") as string[];

    if (uploadResults.length === 0) {
      return { error: "No files uploaded" };
    }

    // Check for failed uploads
    const failedUploads = uploadResults.filter(
      (result) => !result.success,
    );
    if (failedUploads.length > 0) {
      return { error: "Some uploads failed" };
    }

    const assets = await Promise.all(
      uploadResults.map(async (uploadResult, index: number) => {
        if (!uploadResult.file?.url) {
          throw new Error("File upload failed");
        }
        const fileUrl = uploadResult.file.url;
        if (typeof fileUrl !== "string") {
          throw new Error("Invalid file URL");
        }
        const mimeType = typeof uploadResult.file.mimeType === "string" ? uploadResult.file.mimeType : "";

        // Determine asset type based on file URL extension or mime type
        let assetType: typeof AssetType.IMAGE | typeof AssetType.VIDEO = AssetType.IMAGE;
        const lower = fileUrl.toLowerCase();
        const videoExtensions = [
          ".mp4",
          ".webm",
          ".ogg",
          ".mov",
          ".avi",
          ".mkv",
          ".m4v",
        ];

        if (
          mimeType.startsWith("video/") ||
          videoExtensions.some((ext) => lower.includes(ext))
        ) {
          assetType = AssetType.VIDEO;
        }

        const title =
          titles[index] ||
          `${assetType === AssetType.VIDEO ? "Video" : "Image"} ${index + 1}`;
        const tagsString = tagsInputs[index] || "";
        const tags = tagsString
          ? tagsString
              .split(",")
              .map((tag) => tag.trim())
              .filter(Boolean)
          : [];

        return createAsset({
          userId,
          title,
          fileUrl,
          tags,
          assetType,
        });
      }),
    );

    return { success: true, assets };
  }

  if (_action === "bulk_delete_assets") {
    const assetIds = formData.getAll("assetIds") as string[];

    if (assetIds.length === 0) {
      return { error: "No assets selected for deletion" };
    }

    await Promise.all(
      assetIds.map((assetId) => deleteAsset({ id: assetId, userId })),
    );

    return { success: true, deletedCount: assetIds.length };
  }

  if (_action === "schedule") {
    const templateId = formData.get("templateId");
    const templates = await getTemplates({ userId });
    const template = templates.find((t) => t.id === templateId);

    if (!template) {
      return { error: "Template not found" };
    }

    // Prepare template data for scheduling
    const localDate = new Date();
    localDate.setHours(localDate.getHours() + 1);

    const templateData = template.posts.map((post, index) => {
      const scheduleDate = new Date(localDate);
      scheduleDate.setHours(scheduleDate.getHours() + index);

      return {
        caption: post.caption || "",
        fileUrl: post.fileUrl,
        queueType: post.queueTypeId || "unassigned",
        scheduledFor: scheduleDate
          .toLocaleString("en-US", {
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false,
          })
          .replace(/(\d+)\/(\d+)\/(\d+),\s(\d+):(\d+)/, "$3-$1-$2T$4:$5"),
      };
    });

    return { scheduleData: templateData };
  }

  return { error: "Invalid action" };
}

// Type declaration for window.nostr is in app/types/window.d.ts

interface UploadResult {
  success: boolean;
  file?: {
    url: string;
    size: number;
    name: string;
    extension: string;
    sha256?: string;
    mimeType?: string;
    provider: "S3" | "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR";
  };
  error?: string;
}

/**
 * Upload a file using the user's preferred upload provider (S3 or Blossom)
 * This function handles client-side uploads and server-side processing
 */
export async function uploadFile(file: File): Promise<UploadResult> {
  try {
    // First, check what upload provider the user prefers
    const response = await fetch("/api/user-upload-provider");
    if (!response.ok) {
      throw new Error("Failed to get upload provider");
    }

    const data = (await response.json()) as {
      provider?: string;
      enableMirrorBlossom?: boolean;
      mirrorUploadUrls?: string[];
    };
    const uploadProvider = data.provider;
    const enableMirrorBlossom = data.enableMirrorBlossom;
    const mirrorUploadUrls = data.mirrorUploadUrls;

    if (
      uploadProvider === "BLOSSOM_PRIMAL" ||
      uploadProvider === "BLOSSOM_BLOSSTR" ||
      uploadProvider === "BLOSSOM"
    ) {
      return await uploadFileToBlossom(
        file,
        uploadProvider,
        enableMirrorBlossom,
        mirrorUploadUrls,
      );
    } else {
      return await uploadFileToS3(file);
    }
  } catch (error) {
    const { handleAsyncError, getErrorMessage } = await import("~/lib/error-handler.client");
    handleAsyncError(error, {
      component: "upload.client",
      action: "uploadFile",
    }, false); // Don't show toast, return error instead
    return {
      success: false,
      error: getErrorMessage(error) || "Upload failed",
    };
  }
}

/**
 * Upload file to S3 via server-side processing
 */
async function uploadFileToS3(file: File): Promise<UploadResult> {
  const formData = new FormData();
  formData.append("file", file);

  const response = await fetch("/api/upload", {
    method: "POST",
    body: formData,
  });

  const result = (await response.json()) as {
    success?: boolean;
    fileUrl?: string;
    error?: string;
  };

  if (result.success && result.fileUrl) {
    return {
      success: true,
      file: {
        url: result.fileUrl,
        size: file.size,
        name: file.name,
        extension: file.name.split(".").pop() ?? "",
        provider: "S3" as const,
      },
    };
  } else {
    return {
      success: false,
      error: result.error ?? "S3 upload failed",
    };
  }
}

/**
 * Upload file to Blossom via client-side processing
 */
async function uploadFileToBlossom(
  file: File,
  provider = "BLOSSOM_PRIMAL",
  enableMirrorBlossom = false,
  mirrorUploadUrls: string[] = [],
): Promise<UploadResult> {
  try {
    // Check if NOSTR is available
    if (!window.nostr) {
      throw new Error(
        "NOSTR extension not available. Please install a NOSTR browser extension like Alby, Amber, or nos2x.",
      );
    }

    // Dynamic import to avoid SSR issues
    const { BlossomUploader } = await import("@nostrify/nostrify/uploaders");

    // Determine primary server based on provider
    let primaryServerUrl;
    if (provider === "BLOSSOM_BLOSSTR") {
      primaryServerUrl = "https://blosstr.com";
    } else {
      // Default to Primal for BLOSSOM_PRIMAL or legacy BLOSSOM
      primaryServerUrl = "https://blossom.primal.net";
    }

    // Build servers array starting with primary server
    const servers = [primaryServerUrl];

    // Add mirror URLs if enabled and available
    if (
      enableMirrorBlossom &&
      Array.isArray(mirrorUploadUrls) &&
      mirrorUploadUrls.length > 0
    ) {
      servers.push(...mirrorUploadUrls);
    }

    // Create uploader with NOSTR signer and all servers
    const uploader = new BlossomUploader({
      servers: servers,
      signer: window.nostr,
    });

    // Upload the file
    const tags = await uploader.upload(file);

    // Validate that we got the expected tag format
    if (!Array.isArray(tags)) {
      throw new Error(
        "BlossomUploader returned invalid format - expected array of tags",
      );
    }

    // Send the result to server for processing
    const response = await fetch("/api/upload-blossom", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        tags,
        fileName: file.name,
      }),
    });

    const result = (await response.json()) as {
      success?: boolean;
      file?: { url: string };
      error?: string;
    };

    if (result.success && result.file) {
      return {
        success: true,
        file: {
          url: result.file.url,
          size: file.size,
          name: file.name,
          extension: file.name.split(".").pop() || "",
          provider: "BLOSSOM_PRIMAL" as const,
        },
      };
    } else {
      return {
        success: false,
        error: result.error || "Blossom upload failed",
      };
    }
  } catch (error) {
    const { handleAsyncError, getErrorMessage } = await import("~/lib/error-handler.client");
    handleAsyncError(error, {
      component: "upload.client",
      action: "uploadFileToBlossom",
      provider,
    }, false); // Don't show toast, return error instead
    return {
      success: false,
      error: getErrorMessage(error) || "Blossom upload failed",
    };
  }
}

/**
 * Upload multiple files
 */
export async function uploadMultipleFiles(
  files: File[],
): Promise<UploadResult[]> {
  const uploadPromises = files.map((file) => uploadFile(file));
  return Promise.all(uploadPromises);
}

/**
 * Upload file for EditorJS image tool compatibility
 * This specifically uses the EditorJS endpoint which handles image processing
 */
export async function uploadEditorJSImage(
  file: File,
): Promise<{ success: number; file?: { url: string } }> {
  try {
    const formData = new FormData();
    formData.append("image", file);

    const response = await fetch("/api/upload-editorjs-image", {
      method: "POST",
      body: formData,
    });

    const result = (await response.json()) as {
      success?: number;
      file?: { url: string };
      error?: { message?: string };
    };

    if (result.success === 1 && result.file) {
      return {
        success: 1,
        file: {
          url: result.file.url,
        },
      };
    } else {
      const { logClientError } = await import("~/lib/error-handler.client");
      logClientError(
        new Error(result.error?.message ?? "EditorJS upload failed"),
        {
          component: "upload.client",
          action: "uploadEditorJSImage",
        },
        "warning",
      );
      return {
        success: 0,
        // EditorJS expects no error property in success response
      };
    }
  } catch (error) {
    const { handleAsyncError } = await import("~/lib/error-handler.client");
    handleAsyncError(error, {
      component: "upload.client",
      action: "uploadEditorJSImage",
    }, false); // Don't show toast, return error code instead
    return {
      success: 0,
    };
  }
}

import { useNavigate } from "@remix-run/react";
import { useState, useCallback } from "react";
import { toast } from "react-hot-toast";
interface UploadProvider {
  provider: "S3" | "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR";
  isUsingBlossom: boolean;
  enableMirrorBlossom?: boolean;
  mirrorUploadUrls?: string[];
}

interface SubmitOptions {
  method: string;
  encType?: string;
  action?: string;
}

export function useBlossomAwareUpload() {
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [response, setResponse] = useState<Record<string, unknown> | null>(null);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const checkUploadProvider = async (): Promise<UploadProvider> => {
    try {
      const response = await fetch("/api/user-upload-provider");
      if (!response.ok) throw new Error("Failed to check provider");
      const data = (await response.json()) as {
        provider?: string;
        enableMirrorBlossom?: boolean;
        mirrorUploadUrls?: string[];
      };

      const {
        provider,
        enableMirrorBlossom = false,
        mirrorUploadUrls = [],
      } = data;

      // Handle legacy BLOSSOM value as BLOSSOM_PRIMAL
      if (provider === "BLOSSOM" || provider === "BLOSSOM_PRIMAL") {
        return {
          provider: "BLOSSOM_PRIMAL",
          isUsingBlossom: true,
          enableMirrorBlossom,
          mirrorUploadUrls,
        };
      }
      if (provider === "BLOSSOM_BLOSSTR") {
        return {
          provider: "BLOSSOM_BLOSSTR",
          isUsingBlossom: true,
          enableMirrorBlossom,
          mirrorUploadUrls,
        };
      }
      return {
        provider: "S3",
        isUsingBlossom: false,
        enableMirrorBlossom: false,
        mirrorUploadUrls: [],
      };
    } catch (error) {
      console.error("Failed to check upload provider:", error);
      return {
        provider: "S3",
        isUsingBlossom: false,
        enableMirrorBlossom: false,
        mirrorUploadUrls: [],
      };
    }
  };

  const createBlossomAuthHeaders = async (
    provider: "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR",
  ) => {
    if (!window.nostr) {
      throw new Error(
        "NOSTR extension not found. Please install Alby, Amber, or another NOSTR extension to upload to Blossom.",
      );
    }

    let _uploadUrl: string;
    if (provider === "BLOSSOM_PRIMAL") {
      _uploadUrl = "https://blossom.primal.net/upload";
    } else if (provider === "BLOSSOM_BLOSSTR") {
      _uploadUrl = "https://blosstr.com/upload";
    } else {
      throw new Error("Invalid blossom provider");
    }

    // Note: Authentication should be handled by the upload service directly
    throw new Error(
      "Blossom auth not implemented in useBlossomAwareUpload. Use upload.client.ts instead.",
    );
  };

  const submitForm = useCallback(
    async (formData: FormData, options: SubmitOptions) => {
      setIsUploading(true);
      setUploadProgress(10);
      setError(null);

      try {
        // Check upload provider
        const providerInfo = await checkUploadProvider();
        setUploadProgress(20);

        let headers: Record<string, string> = {};

        // If using any Blossom provider, create auth headers and show progress
        if (providerInfo.isUsingBlossom) {
          setUploadProgress(30);
          const providerName =
            providerInfo.provider === "BLOSSOM_PRIMAL" ? "Primal" : "Blosstr";

          // Log mirror configuration if enabled
          if (
            providerInfo.enableMirrorBlossom &&
            providerInfo.mirrorUploadUrls?.length
          ) {
            // Mirror configuration is active
          }

          toast.loading(
            `Signing upload request with NOSTR extension for ${providerName}...`,
            {
              id: "blossom-auth",
            },
          );
          try {
            headers = await createBlossomAuthHeaders(
              providerInfo.provider as "BLOSSOM_PRIMAL" | "BLOSSOM_BLOSSTR",
            );
            toast.success("Upload authorized!", { id: "blossom-auth" });
            setUploadProgress(60);
          } catch (authError: unknown) {
            const errorMessage = authError instanceof Error ? authError.message : String(authError);
            toast.error("Failed to authorize upload: " + errorMessage, {
              id: "blossom-auth",
            });
            throw authError;
          }
        }

        setUploadProgress(70);

        // Get the action URL (default to current page)
        const actionUrl = options.action || window.location.pathname;

        // Make the request with custom headers for Blossom Primal
        const fetchResponse = await fetch(actionUrl, {
          method: options.method,
          body: formData,
          headers: {
            ...headers,
            // Don't set Content-Type for FormData, let the browser set it
          },
        });

        setUploadProgress(90);

        if (!fetchResponse.ok) {
          let errorData: { error?: string };
          try {
            errorData = (await fetchResponse.json()) as { error?: string };
          } catch {
            // If response is not JSON, try to get text
            const errorText = await fetchResponse
              .text()
              .catch(() => `HTTP ${fetchResponse.status}`);
            errorData = {
              error: errorText.includes("<!DOCTYPE")
                ? `HTTP ${fetchResponse.status}`
                : errorText,
            };
          }
          throw new Error(errorData.error || "Upload failed");
        }

        let result;
        const responseText = await fetchResponse.text();

        try {
          // Try to parse as JSON first
          result = JSON.parse(responseText) as Record<string, unknown>;
        } catch (_parseError: unknown) {
          // If response is HTML (redirect or error page), handle gracefully
          if (
            responseText.includes("<!DOCTYPE") ||
            responseText.includes("<html")
          ) {
            if (
              responseText.includes("success") ||
              responseText.includes("uploaded") ||
              fetchResponse.status === 200
            ) {
              result = {
                success: true,
                redirect: true,
                message:
                  "Upload completed, but received HTML response instead of JSON",
              };
            } else {
              result = {
                success: false,
                error: "Server returned HTML instead of expected JSON response",
              };
            }
          } else {
            const parseError = _parseError as Error;
            throw new Error(
              "Invalid response format: " +
              (parseError?.message ?? "Unknown error") +
              ". Response: " +
              responseText.substring(0, 100),
            );
          }
        }

        setResponse(result);
        setUploadProgress(100);

        // Handle successful response
        if (result.success !== false) {
          // Check if this was a redirect response
          if (fetchResponse.redirected || result.redirect) {
            const redirectUrl = result.redirect || fetchResponse.url;
            navigate(redirectUrl);
          }
        }

        return result;
      } catch (error: unknown) {
        const { handleAsyncError } = await import("~/lib/error-handler.client");
        const errorMessage =
          error instanceof Error ? error.message : "Upload failed";
        handleAsyncError(error, {
          component: "useBlossomAwareUpload",
          action: "submitForm",
        });
        setError(errorMessage);
        throw error;
      } finally {
        setTimeout(() => {
          setIsUploading(false);
          setUploadProgress(0);
        }, 1000);
      }
    },
    [navigate],
  );

  return {
    submitForm,
    isUploading,
    uploadProgress,
    response,
    error,
  };
}

import { useFetcher } from "@remix-run/react";
import * as React from "react";

import { Avatar, AvatarImage, AvatarFallback } from "~/components/ui/avatar";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "~/components/ui/select";
import type { NostrEventData } from "~/features/nostr/types";
import { useSubscription } from "~/features/payments/types";
import { useOptionalUser } from "~/lib/remix-utils";

interface ChildAccount {
  npub: string;
  name?: string;
  displayName?: string;
  picture?: string;
}

export default function AccountSwitcher() {
  const user = useOptionalUser();
  const subscription = useSubscription();
  const fetcher = useFetcher<{ children: ChildAccount[] }>();
  const [children, setChildren] = React.useState<ChildAccount[]>([]);

  const planId = (subscription?.currentSubscription?.planId ?? "").toLowerCase();
  const planName = (subscription?.currentSubscription?.Plan?.name ?? "").toLowerCase();
  const hasAccountsAccess = planId === "premium" || planName === "premium" || planName === "founder";
  const isChild = !!user?.isChild;

  React.useEffect(() => {
    if (!isChild && hasAccountsAccess && fetcher.state === "idle" && !fetcher.data) {
      fetcher.load("/api/children");
    }
  }, [isChild, hasAccountsAccess, fetcher.state, fetcher]);

  React.useEffect(() => {
    if (fetcher.data?.children) {
      setChildren(fetcher.data.children);
    }
  }, [fetcher.data]);

  // Hide if not allowed or no children
  if (isChild || !hasAccountsAccess || children.length === 0) return null;

  const handleSwitch = async (childNpub: string) => {
    try {
      const { init } = await import("nostr-login");
      await init({
        methods: ["connect", "extension"],
        noBanner: true,
        onAuth: () => {
          void (async () => {
            if (window.nostr) {
              const randomKeys = () => Math.random().toString(36).slice(2, 12);
              const contentSign = `Switch account ${randomKeys()}`;
              const event = {
                kind: 27235,
                created_at: Math.floor(Date.now() / 1000),
                tags: [] as string[][],
                content: contentSign,
              };

              const signedEvent = await window.nostr.signEvent(event);
              if (signedEvent.pubkey !== childNpub) {
                alert("Please sign with the selected child's keys in your Nostr extension.");
                return;
              }

              const formData = new FormData();
              formData.append("pubkey", signedEvent.pubkey);
              formData.append("signature", signedEvent.sig);
              formData.append("event", JSON.stringify(signedEvent));
              formData.append("contentSign", contentSign);
              formData.append("redirectTo", "/dashboard");

              fetcher.submit(formData, { method: "post", action: "/nostr-auth" });
            }
          })();
        },
      });

      document.dispatchEvent(new CustomEvent("nlLaunch", { detail: "switch" }));
    } catch (e) {

      const { handleErrorSafely } = require("~/lib/error-handler.client") as unknown as { handleErrorSafely: (error: unknown, context: { component: string; action: string }) => void };
      handleErrorSafely(e, {
        component: "AccountSwitcher",
        action: "handleAccountSwitch",
      });
    }
  };

  return (
    <div className="flex items-center">
      <Select onValueChange={(value) => { void handleSwitch(value); }}>
        <SelectTrigger className="h-9 w-[220px] bg-white dark:bg-gray-900 text-sm">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {children.map((c) => {
            const label = c.name || c.displayName || `${c.npub.slice(0, 8)}...${c.npub.slice(-8)}`;
            return (
              <SelectItem key={c.npub} value={c.npub}>
                <div className="flex items-center gap-2">
                  <Avatar className="h-5 w-5">
                    {c.picture ? <AvatarImage src={c.picture} alt={label} /> : <AvatarFallback>C</AvatarFallback>}
                  </Avatar>
                  <span>{label}</span>
                </div>
              </SelectItem>
            );
          })}
        </SelectContent>
      </Select>
    </div>
  );
}

import type { User } from "@prisma/client";

import type { ProfileData } from "~/features/nostr/types";
import { prisma } from "~/lib/prisma.server";

/**
 * Gets basic user info (npub, isChild, parentNpub) by userId
 */
export async function getUserBasicInfo(
  userId: string,
): Promise<{ npub: string | null; isChild: boolean; parentNpub: string | null } | null> {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { npub: true, isChild: true, parentNpub: true },
  });
  if (!user) return null;
  return {
    npub: user.npub,
    isChild: user.isChild,
    parentNpub: user.parentNpub,
  };
}

/**
 * Gets users by an array of npubs with their profile info
 */

export async function getUsersByNpubs(
  npubs: string[],
): Promise<{ npub: string; nostrProfile: ProfileData | null }[]> {
  if (!npubs.length) return [];
  const users = await prisma.user.findMany({
    where: { npub: { in: npubs } },
    select: { npub: true, nostrProfile: true },
  });
  return users.map((user) => ({
    npub: user.npub,
    nostrProfile: user.nostrProfile ? (user.nostrProfile as ProfileData) : null,
  }));
}

/**
 * Gets a user by npub with their profile info
 */
export async function getUserByNpubWithProfile(
  npub: string,
): Promise<{ npub: string; nostrProfile: ProfileData | null } | null> {
  const user = await prisma.user.findUnique({
    where: { npub },
    select: { npub: true, nostrProfile: true },
  });
  if (!user) return null;
  return {
    npub: user.npub,
    nostrProfile: user.nostrProfile && typeof user.nostrProfile === "object" && !Array.isArray(user.nostrProfile)
      ? (user.nostrProfile as ProfileData)
      : null,
  };
}

/**
 * Gets user id by npub
 */
export async function getUserIdByNpub(npub: string): Promise<string | null> {
  const user = await prisma.user.findUnique({
    where: { npub },
    select: { id: true },
  });
  return user?.id ?? null;
}

/**
 * Counts total users in the database (used for healthcheck)
 */
export function countUsers(): Promise<number> {
  return prisma.user.count();
}

/**
 * Gets all enabled users with their subscriptions for cron job processing
 */
export async function getEnabledUsersWithSubscriptions() {
  return await prisma.user.findMany({
    where: {
      isEnabled: true,
    },
    include: {
      Subscription: {
        include: {
          Plan: true,
        },
      },
    },
  });
}

/**
 * Disables a user account
 */
export async function disableUserAccount(userId: string): Promise<User> {
  return await prisma.user.update({
    where: { id: userId },
    data: { isEnabled: false },
  });
