export function hexToNpub(hex: string): string | null {
  try {
    return nip19.npubEncode(hex);
  } catch (_error) {
    // This is a utility function, errors are expected and handled gracefully
    // No need to log conversion errors as they're not critical
    return null;
  }
}

export function npubToHex(npub: string): string | null {
  try {
    if (!npub.startsWith("npub")) {
      return npub;
    }
    const { data } = nip19.decode(npub);
    return data as string;
  } catch (_error) {
    // This is a utility function, errors are expected and handled gracefully
    // No need to log conversion errors as they're not critical
    return null;
  }
}

export const signEventFn = async (
  eventData: NostrEventData,
): Promise<SignEventResult> => {
  try {
    // Add retry logic to handle extension loading
    let retries = 0;
    const maxRetries = 5;

    while (retries < maxRetries) {
      // @ts-ignore - window.nostr is injected by browser extensions at runtime
      if (window.nostr) {
        const nostrEvent: NostrEvent = {
          content: eventData.content,
          created_at: eventData.created_at,
          kind: eventData.kind ?? 1,
          tags: eventData.tags ?? [],
        };

        // @ts-ignore - window.nostr is injected by browser extensions at runtime
        const signResult = await window.nostr.signEvent(nostrEvent);

        // Handle different return types from different extensions
        const signedEvent: SignedEvent = {
          id: signResult?.id ?? "unknown",
          pubkey: signResult?.pubkey ?? "unknown",
          created_at: nostrEvent.created_at,
          kind: nostrEvent.kind,
          tags: nostrEvent.tags,
          content: nostrEvent.content,
          sig:
            typeof signResult === "string"
              ? signResult
              : signResult?.sig ?? "unknown",
        };

        return { nostrEvent, signedEvent };
      }

      retries++;

      // Wait 500ms between retries
      await new Promise((resolve) => setTimeout(resolve, 500));
    }

    throw new Error(
      "Nostr extension not found after retries. Please install a Nostr extension.",
    );
  } catch (error) {
    // Only log on client side (these functions use window.nostr)
    if (typeof window !== "undefined") {
      // @ts-ignore - Dynamic imports work in client-side Remix bundles
      const { logClientError } = await import("~/lib/error-handler.client");
      logClientError(
        error instanceof Error ? error : new Error(String(error)),
        {
          component: "nostr",
          action: "signEventFn",
        },
        "error",
      );
    }
    throw error;
  }
};

export const signLongFormEvent = async (
  eventData: LongFormEventData,
): Promise<SignEventResult> => {
  try {
    // Add retry logic to handle extension loading
    let retries = 0;
    const maxRetries = 5;

    while (retries < maxRetries) {
      // @ts-ignore - window.nostr is injected by browser extensions at runtime
      if (window.nostr) {
        // Build NIP-23 tags
        const eventTags: string[][] = [];

        // Add title tag
        if (eventData.title) {
          eventTags.push(["title", eventData.title]);
        }
        // Add relay tag
        eventTags.push(["r", "wss://relay.primal.net/"]);
        // Add client tag
        eventTags.push(["client", "SmartFlow"]);
        // Add summary tag
        if (eventData.summary) {
          eventTags.push(["summary", eventData.summary]);
        }

        // Add image tag
        if (eventData.image) {
          eventTags.push(["image", eventData.image]);
        }

        // Add identifier tag (d tag for replaceable events)
        if (eventData.identifier) {
          eventTags.push(["d", eventData.identifier]);
        }

        // Add published_at tag
        if (eventData.publishedAt) {
          eventTags.push(["published_at", eventData.publishedAt.toString()]);
        }

        // Add topic tags (t tags)
        if (eventData.tags && eventData.tags.length > 0) {
          eventData.tags.forEach((tag) => {
            if (tag.trim()) {
              eventTags.push(["t", tag.trim().toLowerCase()]);
            }
          });
        }

        const nostrEvent: NostrEvent = {
          content: eventData.content,
          created_at: Math.floor(Date.now() / 1000),
          kind: 30023, // NIP-23 long-form content
          tags: eventTags,
        };

        // @ts-ignore - window.nostr is injected by browser extensions at runtime
        const signResult = await window.nostr.signEvent(nostrEvent);

        // Handle different return types from different extensions
        const signedEvent: SignedEvent = {
          id: signResult?.id ?? "unknown",
          pubkey: signResult?.pubkey ?? "unknown",
          created_at: nostrEvent.created_at,
          kind: nostrEvent.kind,
          tags: nostrEvent.tags,
          content: nostrEvent.content,
          sig:
            typeof signResult === "string"
              ? signResult
              : signResult?.sig ?? "unknown",
        };

        return { nostrEvent, signedEvent };
      }

      retries++;

      // Wait 500ms between retries
      await new Promise((resolve) => setTimeout(resolve, 500));
    }

    throw new Error(
      "Nostr extension not found after retries. Please install a Nostr extension.",
    );
  } catch (error) {
    // Only log on client side (these functions use window.nostr)
    if (typeof window !== "undefined") {
      // @ts-ignore - Dynamic imports work in client-side Remix bundles
      const { logClientError } = await import("~/lib/error-handler.client");
      logClientError(
        error instanceof Error ? error : new Error(String(error)),
        {
          component: "nostr",
          action: "signLongFormEvent",
        },
        "error",
      );
    }
    throw error;
  }
};

export function generateArticleIdentifier(title: string): string {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .trim()
    .substring(0, 64);
}

export function convertEditorJSToMarkdown(editorData: EditorJSOutput | string | null | undefined): string {
  // Handle string input (JSON string)
  let parsedData: EditorJSOutput | null = null;
  if (typeof editorData === "string") {
    try {
      parsedData = JSON.parse(editorData) as EditorJSOutput;
    } catch {
      return "";
    }
  } else if (editorData && typeof editorData === "object") {
    parsedData = editorData;
  }

  if (!parsedData?.blocks || !Array.isArray(parsedData.blocks)) {
    return "";
  }

  let markdown = "";

  parsedData.blocks.forEach((block: EditorJSBlock) => {
    const data = block.data;

    switch (block.type) {
      case "header": {
        const level = "#".repeat((typeof data.level === "number" ? data.level : 1));
        const text = typeof data.text === "string" ? data.text : "";
        markdown += `${level} ${text}\n\n`;
        break;
      }

      case "paragraph": {
        const text = typeof data.text === "string" ? data.text : "";
        markdown += `${text}\n\n`;
        break;
      }

      case "list": {
        const style = data.style;
        const items = Array.isArray(data.items) ? data.items : [];
        if (style === "ordered") {
          items.forEach((item: unknown, index: number) => {
            const itemText = typeof item === "string" ? item : String(item);
            markdown += `${index + 1}. ${itemText}\n`;
          });
        } else {
          items.forEach((item: unknown) => {
            const itemText = typeof item === "string" ? item : String(item);
            markdown += `- ${itemText}\n`;
          });
        }
        markdown += "\n";
        break;
      }

      case "quote": {
        const text = typeof data.text === "string" ? data.text : "";
        markdown += `> ${text}\n`;
        if (data.caption && typeof data.caption === "string") {
          markdown += `> \n> — ${data.caption}\n`;
        }
        markdown += "\n";
        break;
      }

      case "code": {
        const code = typeof data.code === "string" ? data.code : "";
        markdown += "```\n";
        markdown += code;
        markdown += "\n```\n\n";
        break;
      }

      case "linkTool": {
        const link = typeof data.link === "string" ? data.link : "";
        const meta = data.meta && typeof data.meta === "object" ? data.meta as Record<string, unknown> : {};
        const title = typeof meta.title === "string" ? meta.title : null;
        if (title) {
          markdown += `[${title}](${link})\n\n`;
        } else {
          markdown += `${link}\n\n`;
        }
        break;
      }

      case "embed": {
        const service = typeof data.service === "string" ? data.service : "";
        const source = typeof data.source === "string" ? data.source : "";
        if (service === "youtube") {
          markdown += `[![YouTube Video](https://img.youtube.com/vi/${source}/0.jpg)](${source})\n\n`;
        } else {
          markdown += `${source}\n\n`;
        }
        break;
      }

      case "image": {
        const file = data.file && typeof data.file === "object" ? data.file as Record<string, unknown> : null;
        const fileUrl = file && typeof file.url === "string" ? file.url : null;
        const url = typeof data.url === "string" ? data.url : null;
        const imageUrl = fileUrl ?? url;
        const caption = typeof data.caption === "string" ? data.caption : "";
        if (imageUrl) {
          if (caption && caption.trim()) {
            markdown += `![${caption}](${imageUrl})\n\n`;
          } else {
            markdown += `![](${imageUrl})\n\n`;
          }
        }
        break;
      }

      default: {
        const text = typeof data.text === "string" ? data.text : null;
        if (text) {
          markdown += `${text}\n\n`;
        }
        break;
      }
    }
  });

  return markdown.trim();
}

export function convertMarkdownToEditorJS(markdown: string): EditorJSOutput {
  if (!markdown || markdown.trim() === "") {
    return { blocks: [] };
  }

  const blocks: EditorJSBlock[] = [];
  const lines = markdown.split("\n");
  let i = 0;

  while (i < lines.length) {
    const line = lines[i].trim();

    if (line === "") {
      i++;
      continue;
    }

    // Headers
    if (line.startsWith("#")) {
      const level = line.match(/^#+/)?.[0].length ?? 1;
      const text = line.replace(/^#+\s*/, "");
      blocks.push({
        id: generateBlockId(),
        type: "header",
        data: {
          text: text,
          level: Math.min(Math.max(level, 1), 6),
        },
      });
    }
    // Images
    else if (line.match(/^!\[([^\]]*)\]\(([^)]+)\)$/)) {
      const match = line.match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
      if (match) {
        const [, caption, url] = match;
        blocks.push({
          id: generateBlockId(),
          type: "image",
          data: {
            file: {
              url: url,
            },
            caption: caption || "",
            withBorder: false,
            withBackground: false,
            stretched: false,
          },
        });
      }
    }
    // Blockquotes
    else if (line.startsWith("> ")) {
      let quoteText = "";
      let caption = "";

      // Collect all consecutive quote lines
      while (i < lines.length && lines[i].trim().startsWith("> ")) {
        const quoteLine = lines[i].trim().substring(2);
        if (quoteLine.startsWith("— ")) {
          caption = quoteLine.substring(2);
        } else if (quoteLine !== "") {
          if (quoteText) quoteText += " ";
          quoteText += quoteLine;
        }
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "quote",
        data: {
          text: quoteText,
          caption: caption,
        },
      });
    }
    // Code blocks
    else if (line === "```") {
      let code = "";
      i++; // Skip the opening ```

      while (i < lines.length && lines[i].trim() !== "```") {
        if (code) code += "\n";
        code += lines[i];
        i++;
      }

      blocks.push({
        id: generateBlockId(),
        type: "code",
        data: {
          code: code,
        },
      });
    }
    // Ordered lists
    else if (line.match(/^\d+\.\s/)) {
      const items: string[] = [];

      while (i < lines.length && lines[i].trim().match(/^\d+\.\s/)) {
        const item = lines[i].trim().replace(/^\d+\.\s/, "");
        items.push(item);
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "list",
        data: {
          style: "ordered",
          items: items,
        },
      });
    }
    // Unordered lists
    else if (line.startsWith("- ")) {
      const items: string[] = [];

      while (i < lines.length && lines[i].trim().startsWith("- ")) {
        const item = lines[i].trim().substring(2);
        items.push(item);
        i++;
      }
      i--; // Adjust for the loop increment

      blocks.push({
        id: generateBlockId(),
        type: "list",
        data: {
          style: "unordered",
          items: items,
        },
      });
    }
    // Links (simple detection)
    else if (line.match(/^\[([^\]]+)\]\(([^)]+)\)$/)) {
      const match = line.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      if (match) {
        const [, title, url] = match;
        blocks.push({
          id: generateBlockId(),
          type: "linkTool",
          data: {
            link: url,
            meta: {
              title: title,
            },
          },
        });
      }
    }
    // Regular paragraphs
    else if (line) {
      // Collect consecutive non-empty lines for paragraph
      let paragraphText = line;
      let j = i + 1;

      while (
        j < lines.length &&
        lines[j].trim() !== "" &&
        !lines[j].trim().startsWith("#") &&
        !lines[j].trim().startsWith("> ") &&
        !lines[j].trim().startsWith("- ") &&
        !lines[j].trim().match(/^\d+\.\s/) &&
        lines[j].trim() !== "```" &&
        !lines[j].trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/)
      ) {
        paragraphText += " " + lines[j].trim();
        j++;
      }

      blocks.push({
        id: generateBlockId(),
        type: "paragraph",
        data: {
          text: paragraphText,
        },
      });

      i = j - 1; // Set i to the last line we processed
    }

    i++;
  }

  return {
    blocks: blocks,
  };
}

function generateBlockId(): string {
  return Math.random().toString(36).substr(2, 9);
}

import { PrismaClient } from "@prisma/client";
import invariant from "tiny-invariant";

import { recordQueryMetrics } from "./query-metrics.server";
import { singleton } from "./singleton.server";
// Hard-code a unique key, so we can look up the client when this module gets re-imported
const prisma = singleton("prisma", getPrismaClient);

function getPrismaClient() {
  const { DATABASE_URL } = process.env;
  invariant(typeof DATABASE_URL === "string", "DATABASE_URL env var not set");

  const databaseUrl = new URL(DATABASE_URL);

  const isLocalHost = databaseUrl.hostname === "localhost";

  const PRIMARY_REGION = isLocalHost ? null : process.env.PRIMARY_REGION;
  const FLY_REGION = isLocalHost ? null : process.env.FLY_REGION;

  const isReadReplicaRegion = !PRIMARY_REGION || PRIMARY_REGION === FLY_REGION;

  if (!isLocalHost) {
    if (databaseUrl.host.endsWith(".internal")) {
      databaseUrl.host = `${String(FLY_REGION ?? '')}.${databaseUrl.host}`;
    }

    if (!isReadReplicaRegion) {
      // 5433 is the read-replica port
      databaseUrl.port = "5433";
    }
  }

  // NOTE: during development if you change anything in this function, remember
  // that this only runs once per server restart and won't automatically be
  // re-run per request like everything else is. So if you need to change
  // something in this file, you'll need to manually restart the server.
  const baseClient = new PrismaClient({
    datasources: {
      db: {
        url: databaseUrl.toString(),
      },
    },
    // Enable query logging in development for performance monitoring
    log: process.env.NODE_ENV === "development" 
      ? ["query", "info", "warn", "error"]
      : ["error"],
  });

  // Add query performance monitoring middleware using $extends (Prisma 5+)
  const client = baseClient.$extends({
    query: {
      $allModels: {
        async $allOperations({ model, operation, args, query }) {
          const before = Date.now();
          let error: Error | undefined;

          try {
            const result = await query(args);
            const after = Date.now();
            const duration = after - before;

            // Record metrics
            recordQueryMetrics(
              model || "unknown",
              operation,
              duration,
              true,
            );

            // Log slow queries (over 100ms)
            if (duration > 100) {

              console.warn(
                `⚠️ Slow query detected: ${model}.${operation} took ${duration}ms`,
                {
                  model,
                  operation,
                  duration,
                  args,
                },
              );
            }

            return result;
          } catch (err) {
            error = err instanceof Error ? err : new Error(String(err));
            const after = Date.now();
            const duration = after - before;

            // Record error metrics
            recordQueryMetrics(
              model || "unknown",
              operation,
              duration,
              false,
              error,
            );

            // Log query errors

            console.error(
              `❌ Query error: ${model}.${operation} failed after ${duration}ms`,
              {
                model,
                operation,
                error: error.message,
                duration,
              },
            );

            throw err;
          }
        },
      },
    },
  });

  // connect eagerly
  void client.$connect();

  return client;
}

