/**
 * Root Error Boundary
 * Catches errors thrown in loaders, actions, and components
 */
export function ErrorBoundary() {
  const error = useRouteError();

  // Determine error details
  let statusCode = 500;
  let errorMessage = "An unexpected error occurred";
  let errorTitle = "Oops!";
  const isDevelopment = process.env.NODE_ENV === "development";

  if (isRouteErrorResponse(error)) {
    statusCode = error.status;
    errorMessage = error.statusText || errorMessage;
    errorTitle = `${error.status} Error`;
  } else if (error instanceof Error) {
    const normalizedError = normalizeError(error);
    statusCode = normalizedError.statusCode;
    errorMessage = normalizedError.message;
    errorTitle = "Application Error";
  }

  return (
    <html lang="en" className="h-full">
      <head>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width,initial-scale=1" />
        <title>{errorTitle}</title>
        <Meta />
        <Links />
      </head>
      <body className="h-full">
        <div className="flex min-h-full flex-col bg-white dark:bg-gray-900">
          <main className="mx-auto flex w-full max-w-7xl flex-auto flex-col justify-center px-4 py-24 sm:px-6 lg:px-8">
            <div className="mx-auto max-w-2xl text-center">
              <h1 className="text-6xl font-semibold text-gray-900 dark:text-white">
                {statusCode}
              </h1>
              <h2 className="mt-4 text-2xl font-semibold text-gray-900 dark:text-white">
                {errorTitle}
              </h2>
              <p className="mt-4 text-lg text-gray-600 dark:text-gray-400">
                {errorMessage}
              </p>
              <div className="mt-10 flex justify-center">
                <a
                  href="/"
                  className="rounded-md bg-blue-600 px-6 py-3 text-base font-semibold text-white shadow-sm hover:bg-blue-500 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-600"
                >
                  Go back home
                </a>
              </div>
              {isDevelopment && error instanceof Error ? <details className="mt-10 text-left">
                  <summary className="cursor-pointer text-sm font-semibold text-gray-700 dark:text-gray-300">
                    Error Details (Development Only)
                  </summary>
                  <pre className="mt-4 overflow-auto rounded-lg bg-gray-100 p-4 text-xs text-gray-800 dark:bg-gray-800 dark:text-gray-200">
                    {error.stack || error.toString()}
                  </pre>
                </details> : null}
            </div>
          </main>
        </div>
        <Scripts />
      </body>
    </html>
  );
}

import type { LoaderFunctionArgs } from "@remix-run/node";

import {
  withErrorHandling,
  assert,
} from "~/lib/error-handler.server";
import {
  ValidationError,
  ExternalServiceError,
} from "~/lib/errors";

export const loader = withErrorHandling(
  async ({ request }: LoaderFunctionArgs) => {
    const url = new URL(request.url);
    const targetUrl = url.searchParams.get("url");

    assert(targetUrl !== null, "URL parameter is required", {
      searchParams: Array.from(url.searchParams.entries()),
    });

    // Validate URL format
    try {
      new URL(targetUrl);
    } catch {
      throw new ValidationError("Invalid URL format", { targetUrl });
    }

    assert(
      targetUrl.startsWith("http://") || targetUrl.startsWith("https://"),
      "URL must start with http:// or https://",
      { targetUrl },
    );

    // Fetch the URL
    let response: Response;
    try {
      response = await fetch(targetUrl, {
        headers: {
          "User-Agent": "Mozilla/5.0 (compatible; LinkPreview/1.0)",
        },
        signal: AbortSignal.timeout(5000),
      });
    } catch (error) {
      throw new ExternalServiceError(
        "Failed to fetch URL",
        502,
        {
          service: "LinkPreview",
          targetUrl,
          originalError: error instanceof Error ? error.message : String(error),
        },
      );
    }

    if (!response.ok) {
      throw new ExternalServiceError(
        `Failed to fetch URL: HTTP ${response.status}`,
        response.status >= 500 ? 502 : response.status,
        {
          service: "LinkPreview",
          targetUrl,
          status: response.status,
          statusText: response.statusText,
        },
      );
    }

    let html: string;
    try {
      html = await response.text();
    } catch (error) {
      throw new ExternalServiceError(
        "Failed to read response from URL",
        502,
        {
          service: "LinkPreview",
          targetUrl,
          originalError: error instanceof Error ? error.message : String(error),
        },
      );
    }

    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
    const descriptionMatch =
      html.match(
        /<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["'][^>]*>/i,
      ) ||
      html.match(
        /<meta[^>]*content=["']([^"']+)["'][^>]*name=["']description["'][^>]*>/i,
      );
    const imageMatch =
      html.match(
        /<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["'][^>]*>/i,
      ) ||
      html.match(
        /<meta[^>]*content=["']([^"']+)["'][^>]*property=["']og:image["'][^>]*>/i,
      );

    const title = titleMatch ? titleMatch[1].trim() : "";
    const description = descriptionMatch ? descriptionMatch[1].trim() : "";
    const image = imageMatch ? imageMatch[1].trim() : "";

    return {
      success: 1,
      meta: {
        title,
        description,
        image: {
          url: image,
        },
      },
    };
  },
);

import type { ActionFunctionArgs } from "@remix-run/node";
import { json } from "@remix-run/node";

import { requireUserId } from "~/features/auth/session.server";
import { loadUploadProviderSettings } from "~/features/user";
import {
  withActionErrorHandling,
  createSuccessResponse,
  assert,
} from "~/lib/error-handler.server";
import {
  ValidationError,
  AuthorizationError,
} from "~/lib/errors";

export const action = withActionErrorHandling(
  async ({ request }: ActionFunctionArgs) => {
    // Ensure user is authenticated
    const userId = await requireUserId(request);

    // Check if user has any Blossom provider as their preferred upload provider
    const { provider } = await loadUploadProviderSettings(userId);
    const uploadProvider = provider;
    if (!uploadProvider.includes("BLOSSOM")) {
      throw new AuthorizationError("Blossom uploads not enabled for this user", {
        userId,
        uploadProvider,
      });
    }

    // Parse the incoming data from client-side Blossom upload
    let data: { tags?: unknown; fileName?: string };
    try {
      data = await request.json() as { tags?: unknown; fileName?: string };
    } catch (error) {
      throw new ValidationError("Invalid JSON in request body", {
        originalError: error instanceof Error ? error.message : String(error),
      });
    }

    // The BlossomUploader returns the tags array directly, not wrapped in an object
    const tags = (Array.isArray(data.tags) ? data.tags : Array.isArray(data) ? data : []) as string[][];

    assert(
      Array.isArray(tags) && tags.length > 0,
      "Invalid Blossom upload data - tags must be an array",
      { tagsType: typeof tags, isArray: Array.isArray(tags) },
    );

    // Extract relevant information from the Blossom tags
    // Expected format: [['url', 'https://...'], ['x', 'hash'], ['size', '123'], ['m', 'image/jpeg']]
    const urlTag = tags.find((tag: string[]) => Array.isArray(tag) && tag[0] === "url");
    const hashTag = tags.find(
      (tag: string[]) => Array.isArray(tag) && (tag[0] === "x" || tag[0] === "ox"),
    );
    const sizeTag = tags.find((tag: string[]) => Array.isArray(tag) && tag[0] === "size");
    const mimeTypeTag = tags.find((tag: string[]) => Array.isArray(tag) && tag[0] === "m");

    assert(
      !!(urlTag && hashTag && sizeTag && urlTag[1] && hashTag[1] && sizeTag[1]),
      "Invalid Blossom upload data - missing required tags (url, x/ox, size)",
      {
        hasUrlTag: !!urlTag,
        hasHashTag: !!hashTag,
        hasSizeTag: !!sizeTag,
        tagsCount: tags.length,
      },
    );

    const fileUrl = urlTag[1];
    const sha256 = hashTag[1];
    const fileSize = parseInt(sizeTag[1], 10);
    const mimeType = mimeTypeTag?.[1]
      ? (mimeTypeTag[1])
      : "application/octet-stream";

    // Return success response with processed data
    // This matches the S3 upload response format for compatibility
    return createSuccessResponse({
      file: {
        url: fileUrl,
        size: fileSize,
        name: data.fileName || `blossom-${sha256.substring(0, 8)}`,
        extension: data.fileName ? data.fileName.split(".").pop() : "bin",
        sha256,
        mimeType,
        provider: uploadProvider,
      },
    });
  },
);

// Handle preflight requests for CORS
export async function loader() {
  return json({ message: "Blossom Upload API" });
}

import type { ActionFunctionArgs } from "@remix-run/node";
import { json ,
  unstable_composeUploadHandlers as composeUploadHandlers,
  unstable_createMemoryUploadHandler as createMemoryUploadHandler,
  unstable_parseMultipartFormData as parseMultipartFormData,
} from "@remix-run/node";

import { requireUserId } from "~/features/auth/session.server";
import {
  processImageForWeb,
  validateImageBuffer,
  getImageInfo,
} from "~/features/upload/image-resize.server";
import { uploadEditorJSImage } from "~/features/upload/s3.server";
import { loadUploadProviderSettings } from "~/features/user";
import {
  withActionErrorHandling,
  assert,
} from "~/lib/error-handler.server";
import {
  ValidationError,
  ExternalServiceError,
} from "~/lib/errors";

export const action = withActionErrorHandling(
  async ({ request }: ActionFunctionArgs) => {
    // Ensure user is authenticated
    const userId = await requireUserId(request);

    // Check user's upload provider preference
    const { provider } = await loadUploadProviderSettings(userId);
    const uploadProvider = provider;

    // If user prefers blossom, handle it differently
    if (uploadProvider.includes("BLOSSOM")) {
      throw new ValidationError(
        "EditorJS uploads with Blossom are not supported. Please use the Asset Browser to insert images into your content.",
      );
    }

    // Continue with S3 upload for EditorJS

    // Check content type
    const contentType = request.headers.get("content-type") || "";
    assert(
      contentType.includes("multipart/form-data"),
      "Request must be multipart/form-data",
      { contentType },
    );

    let formData: FormData;
    try {
      const uploadHandler = composeUploadHandlers(
        createMemoryUploadHandler({
          maxPartSize: 10 * 1024 * 1024, // 10MB max
        }),
      );
      formData = await parseMultipartFormData(request, uploadHandler);
    } catch (error) {
      throw new ExternalServiceError(
        "Failed to parse multipart form data",
        400,
        {
          originalError: error instanceof Error ? error.message : String(error),
        },
      );
    }

    const imageFile = formData.get("image") || formData.get("imageFile");
    assert(imageFile !== null, "No image file provided", {
      formDataKeys: Array.from(formData.keys()),
    });

    // Handle File object
    if (imageFile instanceof File) {
      // Validate file type
      assert(
        imageFile.type.startsWith("image/"),
        "File must be an image",
        { fileType: imageFile.type },
      );

      // Validate file size (5MB limit)
      assert(
        imageFile.size <= 5 * 1024 * 1024,
        "Image must be smaller than 5MB",
        { fileSize: imageFile.size, maxSize: 5 * 1024 * 1024 },
      );

      // Convert File to Buffer for upload
      const arrayBuffer = await imageFile.arrayBuffer();
      const buffer = Buffer.from(arrayBuffer);

      // Validate the image buffer
      const isValidImage = await validateImageBuffer(buffer);
      assert(isValidImage, "Invalid image file format");

      // Get image info for logging
      const _imageInfo = await getImageInfo(buffer);

      // Process the image with Sharp for optimization and metadata removal
      let processedBuffer: Buffer;
      try {
        processedBuffer = await processImageForWeb(buffer, {
          maxWidth: 1200,
          maxHeight: 1200,
          quality: 85,
          format: "jpeg",
        });
      } catch (error) {
        throw new ExternalServiceError(
          "Failed to process image",
          500,
          {
            service: "ImageProcessing",
            originalError: error instanceof Error ? error.message : String(error),
          },
        );
      }

      // Upload to S3 using EditorJS-specific function
      let imageUrl: string;
      try {
        imageUrl = await uploadEditorJSImage(
          processedBuffer,
          userId,
          imageFile.name,
        );
      } catch (error) {
        throw new ExternalServiceError(
          "Failed to upload image to storage",
          500,
          {
            service: "S3",
            fileName: imageFile.name,
            originalError: error instanceof Error ? error.message : String(error),
          },
        );
      }

      // Return EditorJS compatible response
      return json({
        success: 1,
        file: {
          url: imageUrl,
          size: processedBuffer.length,
          name: imageFile.name.replace(/\.[^/.]+$/, ".jpg"), // Always .jpg since we convert
          extension: "jpg",
        },
      });
    }

    // Handle string URL (if it's already a URL)
    if (typeof imageFile === "string" && imageFile.startsWith("https://")) {
      return json({
        success: 1,
        file: {
          url: imageFile,
          size: 0,
          name: "asset-image",
          extension: "jpg",
        },
      });
    }

    // Check if it's a File object
    const isFile = typeof imageFile === "object" && imageFile !== null && "name" in imageFile && "size" in imageFile;
    throw new ValidationError("Invalid file format", {
      fileType: typeof imageFile,
      isFile,
    });
  },
);

// Handle preflight requests for CORS
export async function loader() {
  return json({ message: "EditorJS Image Upload API" });
}

/**
 * Example: Refactored Upload Route with Centralized Error Handling
 * 
 * This shows how to refactor an existing route to use the new error handling system.
 * Compare this with the original api.upload.tsx to see the improvements.
 */

import {
  json,
  type ActionFunctionArgs,
  unstable_composeUploadHandlers as composeUploadHandlers,
  unstable_createMemoryUploadHandler as createMemoryUploadHandler,
  unstable_parseMultipartFormData as parseMultipartFormData,
} from "@remix-run/node";

import { requireUserId } from "~/features/auth/session.server";
import { createUploadHandler } from "~/features/upload/s3.server";
import {
  withActionErrorHandling,
  createSuccessResponse,
  assert,
} from "~/lib/error-handler.server";
import {
  ValidationError,
  ExternalServiceError,
} from "~/lib/errors";

/**
 * Refactored version using error handling wrapper
 */
export const action = withActionErrorHandling(
  async ({ request }: ActionFunctionArgs) => {
    // Ensure user is authenticated (requireUserId throws redirect, which is fine)
    const userId = await requireUserId(request);

    // Validate content type
    const contentType = request.headers.get("content-type") || "";
    assert(
      contentType.includes("multipart/form-data"),
      "Request must be multipart/form-data",
      { contentType },
    );

    // Parse the multipart form data
    let formData: FormData;
    try {
      const uploadHandler = composeUploadHandlers(
        createUploadHandler(userId),
        createMemoryUploadHandler({
          maxPartSize: 100 * 1024 * 1024, // 100MB max for videos
        }),
      );
      formData = await parseMultipartFormData(request, uploadHandler);
    } catch (error) {
      throw new ExternalServiceError(
        "Failed to parse multipart form data",
        400,
        { originalError: error instanceof Error ? error.message : String(error) },
      );
    }

    // Validate file exists
    const file = formData.get("file");
    assert(file !== null, "No file provided", { formDataKeys: Array.from(formData.keys()) });

    // Validate file was processed correctly
    assert(
      typeof file === "string" && file.startsWith("https://"),
      "File upload failed - no URL returned",
      { fileType: typeof file, fileValue: typeof file === "string" ? file.substring(0, 50) : "not a string" },
    );

    // Return success response
    return createSuccessResponse({ fileUrl: file });
  },
);

/**
 * Alternative: Manual error handling (if you need more control)
 */
export async function actionManual({ request }: ActionFunctionArgs) {
  try {
    const userId = await requireUserId(request);

    const contentType = request.headers.get("content-type") || "";
    if (!contentType.includes("multipart/form-data")) {
      throw new ValidationError("Request must be multipart/form-data", {
        contentType,
      });
    }

    const uploadHandler = composeUploadHandlers(
      createUploadHandler(userId),
      createMemoryUploadHandler({
        maxPartSize: 100 * 1024 * 1024,
      }),
    );

    let formData: FormData;
    try {
      formData = await parseMultipartFormData(request, uploadHandler);
    } catch (error) {
      throw new ExternalServiceError(
        "Failed to parse multipart form data",
        400,
        { originalError: error instanceof Error ? error.message : String(error) },
      );
    }

    const file = formData.get("file");
    if (!file) {
      throw new ValidationError("No file provided", {
        formDataKeys: Array.from(formData.keys()),
      });
    }

    if (typeof file !== "string" || !file.startsWith("https://")) {
      throw new ExternalServiceError("File upload failed - no URL returned", 500, {
        fileType: typeof file,
      });
    }

    return json(createSuccessResponse({ fileUrl: file }));
  } catch (error) {
    // Use centralized error handler
    const { handleActionError } = await import("~/lib/error-handler.server");
    return handleActionError(error);
  }
}

