import type { ActionFunctionArgs, LoaderFunctionArgs } from "@remix-run/node";
import { useLoaderData, useParams, useFetcher } from "@remix-run/react";

import { requireUserId } from "~/features/auth/session.server";
import {
  requireFeatureAccess,
  requireAnySubscription,
} from "~/features/payments/subscriptions.server";
import {
  PostDetailsModal,
  RecyclablesBulkActions,
  RecyclablesPagination,
  RecyclablesQueueTabs,
  RecyclablesSearch,
  RecyclablesTable,
  RecyclablesToast,
  useRecyclablesState,
  getRecyclableDashboardData,
  handleRecyclablePostAction,
} from "~/features/posts";
import type { PostData } from "~/features/posts/types";
import type { IndividualRepostFetcherData } from "~/features/posts/hooks/useRecyclablesState";
import { withErrorHandling, withActionErrorHandling } from "~/lib/error-handler.server";

async function loaderImpl({ request, params }: LoaderFunctionArgs) {
  const userId = await requireUserId(request);

  // Require that the user has at least a subscription record
  await requireAnySubscription(userId);
  // Check if user has access to recyclables feature
  await requireFeatureAccess(userId, "recyclables");

  const url = new URL(request.url);

  const data = await getRecyclableDashboardData({ userId, params, url });

  return data;
}

export const loader = withErrorHandling(loaderImpl);

export const action = withActionErrorHandling(async ({ request }: ActionFunctionArgs) => {
  const userId = await requireUserId(request);
  const formData = await request.formData();

  return handleRecyclablePostAction(formData, userId);
});

type LoaderData = Awaited<ReturnType<typeof loaderImpl>>;

interface RepostFetcherData {
  repostData?: unknown;
  scheduledRepostData?: unknown;
  quotePostData?: unknown;
}

export default function RecyclablesPosts() {
  const data = useLoaderData<LoaderData>();
  const posts = "posts" in data && Array.isArray(data.posts) ? data.posts : [];
  const pagination = "pagination" in data ? data.pagination : undefined;
  const stats = "stats" in data ? data.stats : undefined;
  const user = "user" in data ? data.user : null;
  const queueTypes = "queueTypes" in data && Array.isArray(data.queueTypes) ? data.queueTypes : [];
  const params = useParams();

  const deleteFetcher = useFetcher();
  const bulkDeleteFetcher = useFetcher();
  const repostFetcher = useFetcher<RepostFetcherData>();
  const individualRepostFetcher = useFetcher<IndividualRepostFetcherData>();

  // Type assertions for posts - ensure they match Post[] | PostData[]
  const typedPosts: (PostData[] | Array<{ id: string; caption?: string | null; postedAt: Date | null; fileUrl: string[]; signedEvent: { id: string }; queueType?: { name: string; color?: string | null } | null; status?: string; [key: string]: unknown }>) = Array.isArray(posts) ? posts.map((post: unknown) => {
    const p = post as { id: string; createdAt?: string | Date; postedAt?: string | Date | null; [key: string]: unknown };
    return {
      ...p,
      createdAt: p.createdAt instanceof Date ? p.createdAt : typeof p.createdAt === "string" ? new Date(p.createdAt) : new Date(),
      postedAt: p.postedAt instanceof Date ? p.postedAt : typeof p.postedAt === "string" ? new Date(p.postedAt) : p.postedAt === null ? null : null,
    } as PostData;
  }) : [];

  // Type assertions for stats - ensure it matches Stats type
  const typedStats: Record<string, {
    likes?: number;
    replies?: number;
    mentions?: number;
    reposts?: number;
    zaps?: number;
    satszapped?: number;
  }> = stats && typeof stats === "object" && !Array.isArray(stats) ? stats as Record<string, {
    likes?: number;
    replies?: number;
    mentions?: number;
    reposts?: number;
    zaps?: number;
    satszapped?: number;
  }> : {};

  // Type assertion for pagination
  const typedPagination = pagination && typeof pagination === "object" && !Array.isArray(pagination) && "total" in pagination && "pages" in pagination && "currentPage" in pagination && "limit" in pagination ? {
    total: typeof pagination.total === "number" ? pagination.total : 0,
    pages: typeof pagination.pages === "number" ? pagination.pages : 0,
    currentPage: typeof pagination.currentPage === "number" ? pagination.currentPage : 1,
    limit: typeof pagination.limit === "number" ? pagination.limit : 50,
  } : { total: 0, pages: 0, currentPage: 1, limit: 50 };

  const {
    sortConfig,
    searchTerm,
    selectedPost,
    selectedPosts,
    toast,
    filteredPosts,
    requestSort,
    setSearchTerm,
    setSelectedPost,
    togglePostSelection,
    toggleSelectAll,
    handleBulkDelete,
    handleBulkRepost,
    handleBulkScheduledRepost,
    handleBulkQuote,
    setToast,
  } = useRecyclablesState({
    posts: typedPosts,
    stats: typedStats,
    user: user || null,
    repostFetcher,
    bulkDeleteFetcher,
    bulkRepostFetcher: repostFetcher,
    individualRepostFetcher,
  });

  return (
    <div>
      <div className="mb-5 mt-5 flex flex-col gap-3 text-center sm:flex-row sm:items-center sm:justify-between sm:text-left">
        <div>
          <h3 className="mb-1 font-semibold">Recyclable Posts</h3>
        </div>
        <div className="flex items-center gap-2">
          <RecyclablesSearch
            searchTerm={searchTerm}
            onSearchChange={setSearchTerm}
          />
        </div>
      </div>

      <RecyclablesQueueTabs
        queueTypes={queueTypes}
        currentQueueType={params.queueType}
      />

      <RecyclablesBulkActions
        selectedCount={selectedPosts.size}
        onBulkRepost={handleBulkRepost}
        onBulkScheduledRepost={handleBulkScheduledRepost}
        onBulkQuote={handleBulkQuote}
        onBulkDelete={handleBulkDelete}
        repostFetcher={repostFetcher}
        bulkDeleteFetcher={bulkDeleteFetcher}
      />

      <RecyclablesTable
        posts={filteredPosts.map((post): { id: string; caption?: string | null; postedAt: Date | null; fileUrl: string[]; signedEvent: { id: string }; queueType?: { name: string; color?: string | null } | null; status?: string } => ({
          id: post.id,
          caption: post.caption ?? null,
          postedAt: post.postedAt instanceof Date ? post.postedAt : typeof post.postedAt === "string" ? new Date(post.postedAt) : post.postedAt === null ? null : null,
          fileUrl: Array.isArray(post.fileUrl) ? post.fileUrl : post.fileUrl ? [post.fileUrl] : [],
          signedEvent: post.signedEvent && typeof post.signedEvent === "object" && "id" in post.signedEvent ? { id: String(post.signedEvent.id) } : { id: "" },
          queueType: post.queueType ? { name: post.queueType.name, color: post.queueType.color ?? null } : null,
          status: typeof post.status === "string" ? post.status : undefined,
        }))}
        stats={typedStats}
        sortConfig={sortConfig}
        selectedPosts={selectedPosts}
        onRequestSort={requestSort}
        onPostClick={(post) => {
          // Find the original PostData from typedPosts array
          const originalPostData = typedPosts.find(p => p.id === post.id);
          if (originalPostData) {
            // Convert to the Post format expected by useRecyclablesState
            // useRecyclablesState expects Post with postedAt: Date | null, fileUrl: string[], signedEvent: { id: string }
            setSelectedPost({
              ...originalPostData,
              postedAt: originalPostData.postedAt instanceof Date ? originalPostData.postedAt : typeof originalPostData.postedAt === "string" ? new Date(originalPostData.postedAt) : null,
              fileUrl: Array.isArray(originalPostData.fileUrl) ? originalPostData.fileUrl : typeof originalPostData.fileUrl === "string" ? [originalPostData.fileUrl] : [],
              signedEvent: originalPostData.signedEvent && typeof originalPostData.signedEvent === "object" && "id" in originalPostData.signedEvent ? { id: String(originalPostData.signedEvent.id) } : { id: "" },
            });
          }
        }}
        onToggleSelect={togglePostSelection}
        onToggleSelectAll={toggleSelectAll}
        deleteFetcher={deleteFetcher}
        individualRepostFetcher={individualRepostFetcher}
        bulkDeleteFetcher={bulkDeleteFetcher}
      />

      <RecyclablesPagination pagination={typedPagination} />

      {selectedPost ? (
        <PostDetailsModal
              post={selectedPost as unknown as PostData}
          stats={(() => {
            const eventId = (selectedPost && typeof selectedPost === "object" && "signedEvent" in selectedPost && selectedPost.signedEvent && typeof selectedPost.signedEvent === "object" && "id" in selectedPost.signedEvent) ? String((selectedPost.signedEvent as { id?: string }).id) : "";
            const statsEntry = typedStats[eventId];
            // Ensure all required properties are present with defaults
            return statsEntry ? {
              likes: statsEntry.likes ?? 0,
              replies: statsEntry.replies ?? 0,
              mentions: statsEntry.mentions ?? 0,
              reposts: statsEntry.reposts ?? 0,
              zaps: statsEntry.zaps ?? 0,
              satszapped: statsEntry.satszapped ?? 0,
            } : undefined;
          })()}
          onClose={() => setSelectedPost(null)}
          showStats={true}
          showSignedEvent={true}
          type="posted"
          userTimezone={user?.timezone ?? undefined}
        />
      ) : null}

      <RecyclablesToast toast={toast} onClose={() => setToast(null)} />
    </div>
  );
}

import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@remix-run/node";
import {
  useLoaderData,
  useSearchParams,
} from "@remix-run/react";

import MediaModal from "~/components/ui/MediaModal";
import { requireUserId } from "~/features/auth/session.server";
import { requireFeatureAccess, requireAnySubscription } from "~/features/payments/subscriptions.server";
import {
  AllContentListing,
  BulkDeleteBar,
  DashboardHeader,
  EditPostModal,
  LongFormDetailsModal,
  LongFormListing,
  PostDetailsModal,
  PostsSearch,
  PostTypeTabs,
  QueueSelectionTabs,
  ScheduledPostsTable,
  SimpleRescheduleModal,
  useScheduledState,
  handleScheduledAction,
  loadScheduledData,
  type PostData,
  type LongFormPostData,
  type CombinedContent,
  type QueueType,
  type UserData,
  convertJsonValueToScheduleConfig,
} from "~/features/posts";
import { withErrorHandling, withActionErrorHandling } from "~/lib/error-handler.server";
import type { LongFormPost } from "~/models/longformpost.server";

async function loaderImpl({ request, params }: LoaderFunctionArgs) {
  const userId = await requireUserId(request);

  // Require that the user has at least a subscription record
  await requireAnySubscription(userId);
  // Check if user has access to scheduled posts feature
  await requireFeatureAccess(userId, "scheduled");

  const queueType = params.queueType || "all";

  const data = await loadScheduledData(userId, queueType);
  return data;
}

export const loader = withErrorHandling(loaderImpl);

export const action = withActionErrorHandling(async ({ request }: ActionFunctionArgs) => {
  const userId = await requireUserId(request);
  const formData = await request.formData();
  const result = await handleScheduledAction(formData, userId);

  if (result.error) {
    return json(result, { status: 400 });
  }

  return json(result);
});

type LoaderData = Awaited<ReturnType<typeof loaderImpl>>;

export default function ScheduledPosts() {
  const data = useLoaderData<LoaderData>();
  const postsRaw = "posts" in data && Array.isArray(data.posts) ? data.posts : [];
  const longformPostsRaw = "longformPosts" in data && Array.isArray(data.longformPosts) ? data.longformPosts : [];
  const allContentRaw = "allContent" in data && Array.isArray(data.allContent) ? data.allContent : [];
  const user = "user" in data ? data.user : null;
  const queueTypesRaw = "queueTypes" in data && Array.isArray(data.queueTypes) ? data.queueTypes : [];
  const hashTagPresets = "hashTagPresets" in data && Array.isArray(data.hashTagPresets) ? data.hashTagPresets : [];
  const [searchParams] = useSearchParams();

  // Get current tab from URL params - default to "all"
  const currentTab = searchParams.get("tab") || "all";

  // Type assertions for Remix JsonifyObject serialization
  const posts: PostData[] = Array.isArray(postsRaw) ? postsRaw as unknown as PostData[] : [];
  const longformPosts: LongFormPostData[] = Array.isArray(longformPostsRaw) ? longformPostsRaw as unknown as LongFormPostData[] : [];
  const allContent: CombinedContent[] = Array.isArray(allContentRaw) ? allContentRaw as unknown as CombinedContent[] : [];
  const queueTypes: QueueType[] = Array.isArray(queueTypesRaw) ? queueTypesRaw.map((qt: unknown) => {
    if (qt && typeof qt === "object" && qt !== null && "id" in qt && "name" in qt) {
      const q = qt as { id?: unknown; name?: unknown; color?: unknown; scheduleType?: unknown; scheduleConfig?: unknown; isEnabled?: unknown; userId?: unknown };
      const id = typeof q.id === "string" ? q.id : String(q.id ?? "");
      const name = typeof q.name === "string" ? q.name : String(q.name ?? "");
      const color = q.color !== null && q.color !== undefined ? (typeof q.color === "string" ? q.color : String(q.color)) : null;
      const scheduleType = typeof q.scheduleType === "string" && (q.scheduleType === "INTERVAL" || q.scheduleType === "FIXED_SLOTS") ? q.scheduleType : undefined;
      const scheduleConfig = convertJsonValueToScheduleConfig(q.scheduleConfig);
      const isEnabled = typeof q.isEnabled === "boolean" ? q.isEnabled : q.isEnabled !== false;
      const userId = typeof q.userId === "string" ? q.userId : "";
      const result: QueueType = {
        id,
        name,
        color,
        description: undefined,
        scheduleType,
        scheduleConfig,
        isEnabled,
        userId,
      };
      return result;
    }
    return null;
  }).filter((qt): qt is QueueType => qt !== null) : [];

  const {
    sortConfig,
    searchTerm,
    countdowns,
    selectedPost,
    selectedPosts,
    selectedMedia,
    isMediaModalOpen,
    selectedLongFormPost,
    showEditModal,
    showRescheduleModal,
    postToEdit,
    postToReschedule,
    filteredPosts,
    bulkDeleteFetcher,
    deleteFetcher: _deleteFetcher,
    requestSort,
    setSearchTerm,
    setSelectedPost,
    setSelectedLongFormPost,
    togglePostSelection,
    toggleSelectAll,
    handleBulkDelete,
    handleMediaClick,
    handleCloseMediaModal,
    handleEditPost,
    handleReschedulePost,
    handleCloseEditModal,
    handleCloseRescheduleModal,
    handleModalSuccess,
  } = useScheduledState({
    scheduledPosts: posts,
    userTimezone: user?.timezone ?? undefined,
    allContent,
    currentTab,
  });

  return (
    <div>
      <DashboardHeader
        currentTab={currentTab}
        allContentCount={allContent.length}
        postsCount={filteredPosts.length}
        longformCount={longformPosts.length}
      />

      {/* Post Type Tabs */}
      <PostTypeTabs
        currentTab={currentTab}
        allContent={allContent}
        posts={filteredPosts}
        longformPosts={longformPosts}
        basePath="/dashboard/scheduled"
      />

      {/* Queue Selection Tabs */}
      {currentTab === "all" ||
      currentTab === "posts" ||
      currentTab === "longform" ? (
        <QueueSelectionTabs
          currentTab={currentTab}
          queueTypes={queueTypes}
          basePath="/dashboard"
        />
      ) : null}

      {/* Content based on current tab */}
      {currentTab === "all" ? (
        <AllContentListing
          content={allContent}
          type="scheduled"
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
          userTimezone={user?.timezone ?? undefined}
          onPostSelect={(content) => {
            if (content.type === "post") {
              setSelectedPost(content.originalData as PostData);
            } else {
              setSelectedLongFormPost(content.originalData as LongFormPostData);
            }
          }}
          selectedItems={selectedPosts}
          onToggleSelection={togglePostSelection}
          onToggleSelectAll={toggleSelectAll}
          showBulkActions={true}
          onBulkDelete={handleBulkDelete}
          bulkDeleteState={bulkDeleteFetcher.state}
          onEditPost={handleEditPost}
          onReschedulePost={handleReschedulePost}
        />
      ) : currentTab === "posts" ? (
        <div>
          <PostsSearch searchTerm={searchTerm} onSearchChange={setSearchTerm} />

          <BulkDeleteBar
            selectedCount={selectedPosts.size}
            onBulkDelete={handleBulkDelete}
            isDeleting={bulkDeleteFetcher.state !== "idle"}
          />

          <ScheduledPostsTable
            posts={filteredPosts.map((post): { id: string; caption?: string | null; scheduledFor: string; fileUrl?: string[] | null; queueType?: { name: string; color?: string | null } | null; repost?: boolean; isQuotedPost?: boolean; isPostSigned?: boolean } => ({
              id: post.id,
              caption: post.caption ?? null,
              scheduledFor: (() => {
                const scheduledForValue: unknown = post.scheduledFor;
                if (typeof scheduledForValue === "string") return scheduledForValue;
                if (scheduledForValue instanceof Date) return scheduledForValue.toISOString();
                return "";
              })(),
              fileUrl: Array.isArray(post.fileUrl) ? post.fileUrl : post.fileUrl ? [post.fileUrl] : null,
              queueType: post.queueType ? { name: post.queueType.name, color: post.queueType.color ?? null } : null,
              repost: post.repost ?? false,
              isQuotedPost: post.isQuotedPost ?? false,
              isPostSigned: post.signedEvent ? true : false,
            }))}
            sortConfig={sortConfig}
            onRequestSort={requestSort}
            selectedPosts={selectedPosts}
            onToggleSelection={togglePostSelection}
            onToggleSelectAll={toggleSelectAll}
            countdowns={countdowns}
            userTimezone={user?.timezone ?? undefined}
            onPostClick={(post) => setSelectedPost(post as unknown as PostData)}
            onEditPost={(post) => handleEditPost(post as PostData | LongFormPostData)}
            onReschedulePost={(post) => handleReschedulePost(post as PostData | LongFormPostData)}
            onMediaClick={handleMediaClick}
            bulkDeleteState={bulkDeleteFetcher.state}
          />

          {selectedPost ? (
            <PostDetailsModal
              post={selectedPost}
              onClose={() => setSelectedPost(null)}
              showSignedEvent={true}
              type="scheduled"
              userTimezone={user?.timezone ?? undefined}
            />
          ) : null}

          {/* Media Modal */}
          {selectedMedia ? (
            <MediaModal
              src={selectedMedia}
              alt="Post media"
              isOpen={isMediaModalOpen}
              onClose={handleCloseMediaModal}
            />
          ) : null}
        </div>
      ) : (
        <LongFormListing
          posts={longformPosts as unknown as LongFormPost[]}
          type="scheduled"
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
          userTimezone={user?.timezone ?? undefined}
          onPostSelect={(post) => {
            setSelectedLongFormPost(post as unknown as LongFormPostData);
          }}
          onEditPost={(post) => handleEditPost(post as PostData | LongFormPostData)}
          onReschedulePost={(post) => handleReschedulePost(post as PostData | LongFormPostData)}
        />
      )}

      {/* Long Form Post Details Modal */}
      {selectedLongFormPost ? (
        <LongFormDetailsModal
          post={selectedLongFormPost as unknown as LongFormPost}
          onClose={() => setSelectedLongFormPost(null)}
          type="scheduled"
          showSignedEvent={true}
          userTimezone={user?.timezone ?? undefined}
        />
      ) : null}

      {/* Edit Post Modal */}
      {showEditModal && postToEdit ? (
        <EditPostModal
          post={postToEdit}
          onClose={handleCloseEditModal}
          onConfirm={handleModalSuccess}
          user={user ? (user as unknown as UserData) : undefined}
          queueTypes={queueTypes}
          hashTagPresets={Array.isArray(hashTagPresets) ? hashTagPresets as unknown as { id: string; name: string; tags: string; description?: string | null }[] : []}
        />
      ) : null}

      {/* Reschedule Post Modal */}
      {showRescheduleModal && postToReschedule ? (
        <SimpleRescheduleModal
          post={postToReschedule}
          onClose={handleCloseRescheduleModal}
          onConfirm={handleModalSuccess}
          user={user ? (user as unknown as UserData) : undefined}
          queueTypes={queueTypes}
        />
      ) : null}
    </div>
  );
}

import { json } from "@remix-run/node";
import { useLoaderData } from "@remix-run/react";

import { RelaysSettings } from "~/components/settings/RelaysSettings";
import { TimezoneSettings } from "~/components/settings/TimezoneSettings";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "~/components/ui/tabs";
import { requireUserId } from "~/features/auth/session.server";
import {
  MutedListSettings,
} from "~/features/engagement";
import {
  GiveawayBlacklistSettings,
} from "~/features/giveaway";
import {
  NWCSettings,
  SubscriptionSettings,
  requireFeatureAccess,
  requireAnySubscription,
} from "~/features/payments";
import {
  HashtagPresetsSettings,
  QueueTypesSettings,
  ScheduleIntervalsSettings,
  type HashTagPreset,
  type QueueType,
  convertJsonValueToScheduleConfig,
} from "~/features/posts";
import { handleSettingsAction } from "~/features/settings/settings-actions.server";
import { loadSettingsData } from "~/features/settings/settings-loader.server";
import {
  BlossomMediaMirrorsSettings,
  UploadProviderSettings,
} from "~/features/upload";
import { AccountsSettings } from "~/features/user";
export async function loader({ request }: { request: Request }) {
  const userId = await requireUserId(request);

  // Require that the user has at least a subscription record
  await requireAnySubscription(userId);
  // Check if user has access to settings feature (requires active subscription)
  await requireFeatureAccess(userId, "settings");

  const data = await loadSettingsData(userId);
  return json(data);
}

export async function action({ request }: { request: Request }) {
  const userId = await requireUserId(request);
  const formData = await request.formData();

  try {
    return await handleSettingsAction(userId, formData);
  } catch (error) {
    // Use centralized error handling
    const { handleActionError } = await import("~/lib/error-handler.server");
    const { logError } = await import("~/lib/error-logger.server");
    const { normalizeError } = await import("~/lib/errors");

    // Log additional context for debugging
    const normalizedError = normalizeError(error);
    logError(normalizedError, {
      userId,
      path: request.url,
      method: request.method,
      action: formData.get("_action"),
      formDataEntries: Object.fromEntries(formData.entries()),
    });

    return handleActionError(error);
  }
}

type QueueTypeSettings = QueueType & {
  isDefault: boolean;
  hashTagPreset?: {
    id: string;
    name: string;
    tags: string;
    description?: string;
  } | null;
  hashTagPresetId?: string;
};

export default function Settings() {
  const data = useLoaderData<typeof loader>();
  const {
    timezone,
    relays,
    giveawayBlacklist,
    scheduleIntervals,
    queueTypes: queueTypesRaw,
    uploadProvider,
    enableMirrorBlossom,
    mirrorUploadUrls,
    hashTagPresets: hashTagPresetsRaw,
    nwcEnabled,
    maskedNwcString,
    nwcLastUsed,
    subscription: subscriptionRaw,
    availablePlans: availablePlansRaw,
    paymentHistory: paymentHistoryRaw,
    isChild,
    hasAccountsAccess,
    accounts,
    mutedList: mutedListRaw,
    filterMuted,
    hidePostsFromLowTrustUsers,
  } = data;

  // Type assertions for Remix JsonifyObject serialization
  const queueTypes: QueueTypeSettings[] = Array.isArray(queueTypesRaw) ? queueTypesRaw.map((qt: unknown) => {
    if (qt && typeof qt === "object" && "id" in qt && "name" in qt) {
      const q = qt as { id: string; name: string; color?: string | null; scheduleType?: string; scheduleConfig?: unknown; isEnabled?: boolean; hashTagPresetId?: string; isDefault?: boolean; hashTagPreset?: { id: string; name: string; tags: string; description?: string } | null };
      const result: QueueTypeSettings = {
        id: q.id,
        name: q.name,
        color: q.color,
        description: undefined,
        scheduleType: q.scheduleType as "INTERVAL" | "FIXED_SLOTS" | undefined,
        scheduleConfig: convertJsonValueToScheduleConfig(q.scheduleConfig),
        isEnabled: q.isEnabled,
        isDefault: q.isDefault ?? false,
        hashTagPresetId: q.hashTagPresetId,
        hashTagPreset: q.hashTagPreset,
      };
      return result;
    }
    return null;
  }).filter((qt): qt is QueueTypeSettings => qt !== null) : [];
  const hashTagPresets: HashTagPreset[] = Array.isArray(hashTagPresetsRaw) ? hashTagPresetsRaw
    .filter((preset: unknown): preset is { id: string; name: string; tags: string; description?: unknown; createdAt?: unknown; updatedAt?: unknown; userId?: unknown } => 
      typeof preset === "object" && preset !== null && "id" in preset && "name" in preset && "tags" in preset &&
      typeof (preset as { id: unknown; name: unknown; tags: unknown }).id === "string" &&
      typeof (preset as { id: unknown; name: unknown; tags: unknown }).name === "string" &&
      typeof (preset as { id: unknown; name: unknown; tags: unknown }).tags === "string"
    )
    .map((preset) => ({
      id: preset.id,
      name: preset.name,
      tags: preset.tags,
      description: preset.description === null ? null : typeof preset.description === "string" ? preset.description : undefined,
      userId: typeof preset.userId === "string" ? preset.userId : undefined,
      createdAt: (() => {
        const createdAtValue: unknown = preset.createdAt;
        if (createdAtValue === null || createdAtValue === undefined) return undefined;
        if (createdAtValue instanceof Date) return createdAtValue;
        if (typeof createdAtValue === "string") return new Date(createdAtValue);
        return undefined;
      })(),
      updatedAt: (() => {
        const updatedAtValue: unknown = preset.updatedAt;
        if (updatedAtValue === null || updatedAtValue === undefined) return undefined;
        if (updatedAtValue instanceof Date) return updatedAtValue;
        if (typeof updatedAtValue === "string") return new Date(updatedAtValue);
        return undefined;
      })(),
    })) : [];
  const subscription = subscriptionRaw && typeof subscriptionRaw === "object" ? subscriptionRaw as unknown as { id: string; planId: string | null; status: string; currentPeriodEnd: Date | string | null } | null : null;
  const availablePlans = Array.isArray(availablePlansRaw) ? availablePlansRaw as unknown as { id: string; name: string; price: number }[] : [];
  const paymentHistory = Array.isArray(paymentHistoryRaw) ? paymentHistoryRaw.map((p: unknown) => {
    const ph = p as { id: string; amount: number; createdAt: Date | string };
    return {
      ...ph,
      createdAt: ph.createdAt instanceof Date ? ph.createdAt : new Date(ph.createdAt),
    };
  }) : [];
  const mutedList = mutedListRaw && typeof mutedListRaw === "object" && !Array.isArray(mutedListRaw) ? {
    npubs: Array.isArray(mutedListRaw.npubs) ? mutedListRaw.npubs as string[] : [],
    lastSynced: typeof mutedListRaw.lastSynced === "string" ? mutedListRaw.lastSynced : new Date().toISOString(),
  } : { npubs: [], lastSynced: new Date().toISOString() };

  // Get tab from URL search params
  const searchParams = new URLSearchParams(
    typeof window !== "undefined" ? window.location.search : "",
  );
  let defaultTab = searchParams.get("tab") || "general";
  if (
    (isChild && defaultTab === "subscription") ||
    (!hasAccountsAccess && defaultTab === "accounts")
  ) {
    defaultTab = "general";
  }

  return (
    <div className="container mx-auto p-6">
      <div className="mb-8">
        <h1 className="text-3xl font-bold tracking-tight">Settings</h1>
        <p className="mt-2 text-muted-foreground">
          Manage your account preferences and posting configurations
        </p>
      </div>

      <Tabs defaultValue={defaultTab} className="w-full">
        <TabsList
          className={`grid w-full ${!hasAccountsAccess && !isChild ? "grid-cols-5" : isChild ? "grid-cols-5" : "grid-cols-6"}`}
        >
          <TabsTrigger value="general">General</TabsTrigger>
          <TabsTrigger value="content">Content</TabsTrigger>
          {hasAccountsAccess ? <TabsTrigger value="accounts">Accounts</TabsTrigger> : null}
          <TabsTrigger value="network">Network</TabsTrigger>
          <TabsTrigger value="storage">Storage</TabsTrigger>
          {!isChild ? <TabsTrigger value="subscription">Subscription</TabsTrigger> : null}
        </TabsList>

        <TabsContent value="general" className="mt-6 space-y-6">
          <div className="grid gap-6 md:grid-cols-1">
            <TimezoneSettings timezone={timezone} />
            <ScheduleIntervalsSettings scheduleIntervals={scheduleIntervals} />
          </div>
        </TabsContent>

        <TabsContent value="content" className="mt-6 space-y-6">
          <div className="grid gap-6 md:grid-cols-1">
            <HashtagPresetsSettings presets={hashTagPresets.map((p) => ({
              id: p.id,
              name: p.name,
              tags: p.tags,
              description: p.description ?? null,
              createdAt: p.createdAt instanceof Date ? p.createdAt.toISOString() : typeof p.createdAt === "string" ? p.createdAt : new Date().toISOString(),
              updatedAt: p.updatedAt instanceof Date ? p.updatedAt.toISOString() : typeof p.updatedAt === "string" ? p.updatedAt : new Date().toISOString(),
            }))} />
            <QueueTypesSettings
              queueTypes={queueTypes}
              hashTagPresets={hashTagPresets.map((p) => ({ id: p.id, name: p.name, tags: p.tags, description: p.description ?? undefined }))}
            />
          </div>
        </TabsContent>

        <TabsContent value="network" className="mt-6 space-y-6">
          <div className="grid gap-6 md:grid-cols-1">
            <RelaysSettings relays={relays} />
            <GiveawayBlacklistSettings giveawayBlacklist={giveawayBlacklist} />
            <MutedListSettings
              mutedList={mutedList}
              filterMuted={filterMuted}
              hidePostsFromLowTrustUsers={hidePostsFromLowTrustUsers}
            />
          </div>
        </TabsContent>

        <TabsContent value="storage" className="mt-6 space-y-6">
          <div className="grid gap-6 md:grid-cols-1">
            <UploadProviderSettings uploadProvider={uploadProvider} />
            <BlossomMediaMirrorsSettings
              enableMirrorBlossom={enableMirrorBlossom}
              mirrorUploadUrls={mirrorUploadUrls}
            />
          </div>
        </TabsContent>

        {!isChild ? (
          <TabsContent value="subscription" className="mt-6 space-y-6">
            <div className="grid gap-6 md:grid-cols-1">
              <SubscriptionSettings
                subscription={subscription as unknown as { id: string; planId: string | null; status: string; startDate: Date; currentPeriodEnd: Date | null; nextPaymentDue: Date | null; cancelAtPeriodEnd: boolean; plan: { id: string; name: string; price: number; enableLifetimeAccess: boolean } | null } | null}
                availablePlans={availablePlans as unknown as { id: string; name: string; price: number; enableLifetimeAccess: boolean }[]}
                paymentHistory={paymentHistory as unknown as { id: string; amount: number; amountUsd: number | null; description: string | null; paidAt: Date | null; paymentMethod: string | null; paymentHash: string; planName?: string; planPrice?: number }[]}
              />
              <NWCSettings
                nwcEnabled={nwcEnabled}
                maskedNwcString={maskedNwcString ?? undefined}
                nwcLastUsed={nwcLastUsed}
              />
            </div>
          </TabsContent>
        ) : null}

        {hasAccountsAccess ? (
          <TabsContent value="accounts" className="mt-6 space-y-6">
            <div className="grid gap-6 md:grid-cols-1">
              {accounts ? (
                <AccountsSettings
                  parentNpub={accounts.parentNpub ?? undefined}
                  confirmedChildren={accounts.confirmedChildren}
                  pendingChildren={accounts.pendingChildren}
                  isChild={accounts.isChild}
                  parentUser={accounts.parentUser}
                />
              ) : (
                <div className="text-sm text-muted-foreground">
                  Your account npub is not available.
                </div>
              )}
            </div>
          </TabsContent>
        ) : null}
      </Tabs>
    </div>
  );
}

import { json, type LoaderFunctionArgs, type ActionFunctionArgs } from "@remix-run/node";
