// Use this to update a Nostr user's subscription status for testing
// Simply call this with:
// npx tsx ./tests/e2e/support/update-subscription-status.ts npub1xxx STATUS
//
// Where STATUS is one of: FREE, ACTIVE, EXPIRED, CANCELED, PAST_DUE

import { PrismaClient, SubscriptionStatus } from "@prisma/client";
import { installGlobals } from "@remix-run/node";
installGlobals();

const prisma = new PrismaClient();

type TestSubscriptionStatus = "FREE" | "ACTIVE" | "EXPIRED" | "CANCELED" | "PAST_DUE";

async function updateSubscriptionStatus(npub: string, targetStatus: TestSubscriptionStatus) {
    if (!npub) {
        throw new Error("npub required");
    }

    if (!targetStatus) {
        throw new Error("status required (FREE, ACTIVE, EXPIRED, CANCELED, PAST_DUE)");
    }

    // Find the user
    const user = await prisma.user.findUnique({
        where: { npub },
        include: { Subscription: true },
    });

    if (!user) {
        throw new Error(`User not found: ${npub}`);
    }

    if (targetStatus === "FREE") {
        // Delete any existing subscription to simulate free user
        if (user.Subscription) {
            await prisma.subscription.delete({
                where: { userId: user.id },
            });
        }

        console.log(`<status>FREE</status>`);
    } else if (targetStatus === "ACTIVE") {
        const now = new Date();
        const thirtyDaysFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update existing subscription to active
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.ACTIVE,
                    currentPeriodStart: now,
                    currentPeriodEnd: thirtyDaysFromNow,
                    cancelAtPeriodEnd: false,
                },
            });
        } else {
            // Create a new active subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.ACTIVE,
                    startDate: now,
                    currentPeriodStart: now,
                    currentPeriodEnd: thirtyDaysFromNow,
                },
            });
        }

        console.log(`<status>ACTIVE</status>`);
    } else if (targetStatus === "EXPIRED") {
        const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
        const sixtyDaysAgo = new Date(Date.now() - 60 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update subscription to expired (INACTIVE status with past end date)
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.INACTIVE,
                    currentPeriodStart: sixtyDaysAgo,
                    currentPeriodEnd: thirtyDaysAgo,
                    endDate: thirtyDaysAgo,
                },
            });
        } else {
            // Create an expired subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.INACTIVE,
                    startDate: sixtyDaysAgo,
                    currentPeriodStart: sixtyDaysAgo,
                    currentPeriodEnd: thirtyDaysAgo,
                    endDate: thirtyDaysAgo,
                },
            });
        }

        console.log(`<status>EXPIRED</status>`);
    } else if (targetStatus === "CANCELED") {
        const now = new Date();
        const thirtyDaysFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update subscription to canceled (still active until period end, but won't renew)
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.CANCELED,
                    currentPeriodEnd: thirtyDaysFromNow,
                    cancelAtPeriodEnd: true,
                },
            });
        } else {
            // Create a canceled subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.CANCELED,
                    startDate: now,
                    currentPeriodStart: now,
                    currentPeriodEnd: thirtyDaysFromNow,
                    cancelAtPeriodEnd: true,
                },
            });
        }

        console.log(`<status>CANCELED</status>`);
    } else if (targetStatus === "PAST_DUE") {
        const now = new Date();
        const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update subscription to past due
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.PAST_DUE,
                    currentPeriodEnd: sevenDaysAgo,
                },
            });
        } else {
            // Create a past due subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.PAST_DUE,
                    startDate: sevenDaysAgo,
                    currentPeriodStart: sevenDaysAgo,
                    currentPeriodEnd: sevenDaysAgo,
                },
            });
        }

        console.log(`<status>PAST_DUE</status>`);
    } else {
        throw new Error(`Unknown status: ${targetStatus}`);
    }

    await prisma.$disconnect();
}

updateSubscriptionStatus(process.argv[2], process.argv[3] as TestSubscriptionStatus);

/**
 * Asset factory for creating test assets
 * Uses builder pattern for flexible test data creation
 */

import type { Asset, AssetType } from "@prisma/client";

import { TEST_USER_ID } from "../utils/test-helpers";

export interface AssetFactoryOptions {
  id?: string;
  userId?: string;
  title?: string | null;
  content?: string | null;
  fileUrl?: string | null;
  tags?: string[];
  assetType?: AssetType;
  createdAt?: Date;
  updatedAt?: Date;
}

export class AssetFactory {
  private options: AssetFactoryOptions;

  constructor(options: AssetFactoryOptions = {}) {
    this.options = {
      id: `asset-${Date.now()}-${Math.random().toString(36).substring(7)}`,
      userId: TEST_USER_ID,
      title: "Test Asset",
      content: null,
      fileUrl: null,
      tags: [],
      assetType: "TEXT",
      createdAt: new Date(),
      updatedAt: new Date(),
      ...options,
    };
  }

  withId(id: string): this {
    this.options.id = id;
    return this;
  }

  withUserId(userId: string): this {
    this.options.userId = userId;
    return this;
  }

  withTitle(title: string): this {
    this.options.title = title;
    return this;
  }

  withContent(content: string): this {
    this.options.content = content;
    return this;
  }

  withFileUrl(fileUrl: string): this {
    this.options.fileUrl = fileUrl;
    return this;
  }

  withTags(tags: string[]): this {
    this.options.tags = tags;
    return this;
  }

  asText(): this {
    this.options.assetType = "TEXT";
    return this;
  }

  asImage(fileUrl: string): this {
    this.options.assetType = "IMAGE";
    this.options.fileUrl = fileUrl;
    return this;
  }

  asVideo(fileUrl: string): this {
    this.options.assetType = "VIDEO";
    this.options.fileUrl = fileUrl;
    return this;
  }

  build(): Asset {
    return {
      id: this.options.id!,
      userId: this.options.userId!,
      title: this.options.title ?? null,
      content: this.options.content ?? null,
      fileUrl: this.options.fileUrl ?? null,
      tags: this.options.tags ?? [],
      assetType: this.options.assetType || "TEXT",
      createdAt: this.options.createdAt || new Date(),
      updatedAt: this.options.updatedAt || new Date(),
    } as Asset;
  }
}

/**
 * Convenience functions for common asset types
 */
export const assetFactory = {
  /**
   * Create a text asset
   */
  text: (overrides?: AssetFactoryOptions) => {
    return new AssetFactory(overrides).asText().build();
  },

  /**
   * Create an image asset
   */
  image: (fileUrl: string, overrides?: AssetFactoryOptions) => {
    return new AssetFactory(overrides).asImage(fileUrl).build();
  },

  /**
   * Create a video asset
   */
  video: (fileUrl: string, overrides?: AssetFactoryOptions) => {
    return new AssetFactory(overrides).asVideo(fileUrl).build();
  },

  /**
   * Create multiple assets
   */
  many: (count: number, overrides?: AssetFactoryOptions) => {
    return Array.from({ length: count }, (_, i) =>
      new AssetFactory({ ...overrides, id: `asset-${i + 1}` }).build(),
    );
  },
};

/**
 * Example test demonstrating factory usage
 * This file shows how to use factories in tests
 */

import { describe, it, expect } from "vitest";

import {
  postFactory,
  longFormPostFactory,
  userFactory,
  queueTypeFactory,
  hashTagPresetFactory,
  paymentFactory,
  PostFactory,
  UserFactory,
} from "./index";

describe("Factory Usage Examples", () => {
  it("should create a draft post using convenience function", () => {
    const post = postFactory.draft();

    expect(post.draft).toBe(true);
    expect(post.isPosted).toBe(false);
    expect(post.isScheduled).toBe(false);
  });

  it("should create a scheduled post using builder pattern", () => {
    const scheduledFor = new Date(Date.now() + 3600000);
    const post = new PostFactory()
      .withCaption("Scheduled post")
      .withImages(["https://example.com/image.jpg"])
      .asScheduled(scheduledFor)
      .build();

    expect(post.isScheduled).toBe(true);
    expect(post.draft).toBe(false);
    expect(post.scheduledFor).toBeDefined();
  });

  it("should create related entities", () => {
    const user = userFactory.basic({ id: "user-1" });
    const queue = queueTypeFactory.interval(4, { userId: user.id });
    const preset = hashTagPresetFactory.basic({ userId: user.id });
    const post = postFactory.draft({
      userId: user.id,
      queueTypeId: queue.id,
      hashTagPresetId: preset.id,
    });

    expect(post.userId).toBe(user.id);
    expect(post.queueTypeId).toBe(queue.id);
    expect(post.hashTagPresetId).toBe(preset.id);
  });

  it("should create multiple posts", () => {
    const posts = postFactory.many(5, { draft: true });

    expect(posts).toHaveLength(5);
    posts.forEach((post) => {
      expect(post.draft).toBe(true);
    });
  });

  it("should create a user with specific settings", () => {
    const user = new UserFactory()
      .withTimezone("America/New_York")
      .withRelays(["wss://relay1.com"])
      .withHashTagsInPosts(true)
      .build();

    expect(user.timezone).toBe("America/New_York");
    expect(user.userRelays).toEqual(["wss://relay1.com"]);
    expect(user.showHashTagsinPosts).toBe(true);
  });

  it("should create a payment with different statuses", () => {
    const pending = paymentFactory.pending();
    const paid = paymentFactory.paid();
    const failed = paymentFactory.failed("Insufficient funds");

    expect(pending.status).toBe("PENDING");
    expect(paid.status).toBe("COMPLETED");
    expect(failed.status).toBe("FAILED");
  });
});

/**
 * HashTagPreset factory for creating test hashtag presets
 * Uses builder pattern for flexible test data creation
 */

import type { HashTagPreset } from "@prisma/client";

import { TEST_USER_ID } from "../utils/test-helpers";

export interface HashTagPresetFactoryOptions {
  id?: string;
  userId?: string;
  name?: string;
  tags?: string;
  description?: string | null;
  createdAt?: Date;
  updatedAt?: Date;
}

export class HashTagPresetFactory {
  private options: HashTagPresetFactoryOptions;

  constructor(options: HashTagPresetFactoryOptions = {}) {
    this.options = {
      id: `preset-${Date.now()}-${Math.random().toString(36).substring(7)}`,
      userId: TEST_USER_ID,
      name: "Test Preset",
      tags: "#test #hashtags",
      description: null,
      createdAt: new Date(),
      updatedAt: new Date(),
