/**
 * Edge Case Tests for Database Connection Failures
 * 
 * Tests how the application handles database failures:
 * - Connection timeouts
 * - Connection lost during operation
 * - Transaction failures
 * - Query timeouts
 */

import { describe, it, expect, vi, beforeEach } from "vitest";
// Mock Prisma
const { mockPrisma } = vi.hoisted(() => {
  const mockPrisma = {
    post: {
      findMany: vi.fn(),
      findUnique: vi.fn(),
      create: vi.fn(),
      update: vi.fn(),
      delete: vi.fn(),
    },
    user: {
      findUnique: vi.fn(),
      update: vi.fn(),
    },
    subscription: {
      findUnique: vi.fn(),
    },
    $transaction: vi.fn(),
    $connect: vi.fn(),
    $disconnect: vi.fn(),
    $use: vi.fn(),
  };
  return { mockPrisma };
});

vi.mock("~/lib/prisma.server", () => ({
  prisma: mockPrisma,
}));

import { prisma } from "~/lib/prisma.server";
import { createPost, updatePost } from "~/models/post.commands.server";
import { getScheduledPosts } from "~/models/post.queries.server";
import { getUserById } from "~/models/user.server";

describe("Database Failure Edge Cases", () => {
  const TEST_USER_ID = "user-123";
  const TEST_POST_ID = "post-123";

  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe("Connection Failures", () => {
    it("should handle database connection timeout", async () => {
      (mockPrisma.post.findMany as ReturnType<typeof vi.fn>).mockImplementation(() => {
        return new Promise((_, reject) => {
          setTimeout(
            () => reject(new Error("Connection timeout after 30s")),
            100,
          );
        });
      });

      await expect(
        getScheduledPosts({ userId: TEST_USER_ID, queueType: "all" }),
      ).rejects.toThrow("Connection timeout");
    });

    it("should handle connection lost during query", async () => {
      (mockPrisma.user.findUnique as ReturnType<typeof vi.fn>).mockRejectedValue(
        new Error("Connection lost: server closed the connection unexpectedly"),
      );

      await expect(
        getUserById(TEST_USER_ID),
      ).rejects.toThrow("Connection lost");
    });

    it("should handle database unavailable error", async () => {
      (mockPrisma.post.create as ReturnType<typeof vi.fn>).mockRejectedValue(
        new Error("Database unavailable: connection refused"),
      );

      await expect(
        createPost({
          userId: TEST_USER_ID,
          content: "Test",
          postType: "TEXT",
          fileUrl: [],
          tags: [],
          isScheduled: false,
          isPosted: false,
        }),
      ).rejects.toThrow("Database unavailable");
    });
  });

  describe("Transaction Failures", () => {
    it("should handle transaction rollback on error", async () => {
      // updatePost doesn't use transactions, so we'll test with a function that does
      // For now, test that updatePost handles database errors
      mockPrisma.post.update.mockRejectedValue(
        new Error("Transaction failed: deadlock detected"),
      );

      await expect(
        updatePost({
          id: TEST_POST_ID,
          userId: TEST_USER_ID,
          data: { content: "Updated" },
        }),
      ).rejects.toThrow("Transaction failed");
    });

    it("should handle transaction timeout", async () => {
      mockPrisma.post.update.mockImplementation(() => {
        return new Promise((_, reject) => {
          setTimeout(
            () => reject(new Error("Transaction timeout")),
            100,
          );
        });
      });

      await expect(
        updatePost({
          id: TEST_POST_ID,
          userId: TEST_USER_ID,
          data: { content: "Updated" },
        }),
      ).rejects.toThrow("Transaction timeout");
    });
  });

  describe("Query Failures", () => {
    it("should handle query timeout", async () => {
      (mockPrisma.post.findMany as ReturnType<typeof vi.fn>).mockImplementation(() => {
        return new Promise((_, reject) => {
          setTimeout(() => reject(new Error("Query timeout")), 100);
        });
      });

      await expect(
        getScheduledPosts({ userId: TEST_USER_ID, queueType: "all" }),
      ).rejects.toThrow("Query timeout");
    });

    it("should handle constraint violation errors", async () => {
      (mockPrisma.post.create as ReturnType<typeof vi.fn>).mockRejectedValue(
        new Error("Unique constraint violation on post.id"),
      );

      await expect(
        createPost({
          userId: TEST_USER_ID,
          content: "Test",
          postType: "TEXT",
          fileUrl: [],
          tags: [],
          isScheduled: false,
          isPosted: false,
        }),
      ).rejects.toThrow("Unique constraint violation");
    });

    it("should handle foreign key constraint errors", async () => {
      (mockPrisma.post.create as ReturnType<typeof vi.fn>).mockRejectedValue(
        new Error("Foreign key constraint violation on userId"),
      );

      await expect(
        createPost({
          userId: "non-existent-user",
          content: "Test",
          postType: "TEXT",
          fileUrl: [],
          tags: [],
          isScheduled: false,
          isPosted: false,
        }),
      ).rejects.toThrow("Foreign key constraint violation");
    });
  });

  describe("Connection Recovery", () => {
    it("should handle reconnection after failure", async () => {
      // First call fails, second succeeds
      (mockPrisma.user.findUnique as ReturnType<typeof vi.fn>)
        .mockRejectedValueOnce(new Error("Connection lost"))
        .mockResolvedValueOnce({ 
          id: TEST_USER_ID, 
          npub: "npub123",
          hashTagPresets: [],
        });

      // Mock subscription.findUnique (called by getUserById) - succeeds on retry
      (mockPrisma.subscription.findUnique as ReturnType<typeof vi.fn>)
        .mockResolvedValue(null);

      // First attempt fails
      await expect(getUserById(TEST_USER_ID)).rejects.toThrow("Connection lost");

      // Second attempt succeeds (simulating reconnection)
      const result = await getUserById(TEST_USER_ID);
      expect(result).toBeDefined();
      expect(result).toHaveProperty("id");
      expect(result).toHaveProperty("npub");
      expect(result?.id).toBe(TEST_USER_ID);
    });
  });
});

/**
 * Example Database Integration Test
 * 
 * This file demonstrates how to write tests that use a real database
 * with transaction-based isolation for safety
 */

import { describe, it, expect, beforeAll, afterAll, vi } from "vitest";

import { createPost } from "~/models/post.commands.server";
import { getUserById } from "~/models/user.server";

import {
  describeDatabase,
  withDatabase,
  createMinimalFixtures,
  fixtures,
} from "../database/database-test-helpers";
import { getTestPrisma } from "../database/test-db";

// Don't mock Prisma - this test uses the real database
// Model functions will use the real Prisma client from getTestPrisma()
// We need to ensure prisma.server.ts uses getTestPrisma() in test mode
// For now, we'll mock it minimally to prevent $use errors, but the actual
// database operations will use the real client from withDatabase
vi.mock("~/lib/prisma.server", async () => {
  // Return a proxy that forwards to getTestPrisma() when accessed
  const { getTestPrisma } = await import("../database/test-db");
  return {
    get prisma() {
      return getTestPrisma();
    },
  };
});

// Example: Test with database using transactions
describeDatabase("Database Integration Example", () => {
  it("should create and retrieve a user", async () => {
    await withDatabase(async (prisma) => {
      // Create user
      const user = await prisma.user.create({
        data: {
          npub: "npub-test-123",
          isEnabled: true,
        },
      });

      expect(user).toBeDefined();
      expect(user.npub).toBe("npub-test-123");

      // Retrieve user
      const retrieved = await prisma.user.findUnique({
        where: { id: user.id },
      });

      expect(retrieved).toBeDefined();
      expect(retrieved?.id).toBe(user.id);
    });
    // Transaction is automatically rolled back - no cleanup needed!
  });

  it("should create user with fixtures", async () => {
    const testFixtures = createMinimalFixtures();

    await withDatabase(async (prisma) => {
      // Fixtures are automatically applied
      const user = await prisma.user.findFirst({
        where: { id: testFixtures.users![0].id },
      });

      expect(user).toBeDefined();
    }, testFixtures);
  });

  it("should test model functions with real database", async () => {
    await withDatabase(async (prisma) => {
      // Create user first
      const user = await prisma.user.create({
        data: {
          npub: "npub-test-456",
          isEnabled: true,
        },
      });

      // Test model function
      const retrieved = await getUserById(user.id);

      expect(retrieved).toBeDefined();
      expect(retrieved?.id).toBe(user.id);
    });
  });

  it("should test relationships", async () => {
    const testFixtures = fixtures.userWithQueues();

    await withDatabase(async (prisma) => {
      const user = await prisma.user.findUnique({
        where: { id: testFixtures.users![0].id },
        include: {
          queueTypes: true,
        },
      });

      expect(user).toBeDefined();
      expect(user?.queueTypes).toHaveLength(2);
    }, testFixtures);
  });

  it("should test post creation with queue", async () => {
    const testFixtures = fixtures.userWithQueues();

    await withDatabase(async (prisma) => {
      const user = testFixtures.users![0];
      const queue = testFixtures.queueTypes![0];

      // Create post using model function
      const post = await createPost({
        userId: user.id!,
        content: "Test post",
        queueTypeId: queue.id!,
        fileUrl: [],
        tags: [],
        isScheduled: false,
        isPosted: false,
        postType: "TEXT",
      });

      expect(post).toBeDefined();
      expect(post.userId).toBe(user.id);
      expect(post.queueTypeId).toBe(queue.id);
    }, testFixtures);
  });
});

