      (queueClient.enqueue as ReturnType<typeof vi.fn>).mockResolvedValue({
        success: true,
        jobId: "job-123",
      });

      await enqueueLongFormPostJob("longform-123", TEST_USER_ID, mockSignedEvent, 0);

      expect(queueClient.enqueue).toHaveBeenCalledWith(
        "scheduled-longform-posts",
        "publish-longform-post",
        {
          postId: "longform-123",
          userId: TEST_USER_ID,
          signedEvent: mockSignedEvent,
        },
        { delay: 0 },
      );
    });

    it("should throw error when longform enqueue fails", async () => {
      const mockSignedEvent: SignedEvent = { id: "event-123", kind: 30023, pubkey: "test-pubkey", created_at: Date.now(), tags: [], content: "", sig: "test-sig" } as SignedEvent;

      (queueClient.enqueue as ReturnType<typeof vi.fn>).mockResolvedValue({
        success: false,
        error: "Queue error",
      });

      await expect(
        enqueueLongFormPostJob("longform-123", TEST_USER_ID, mockSignedEvent, 0),
      ).rejects.toThrow("Queue error");
    });

    it("should cancel longform post job by postId", async () => {
      (queueClient.cancelByData as ReturnType<typeof vi.fn>).mockResolvedValue(true);

      const result = await cancelLongFormPostJob("longform-123");

      expect(queueClient.cancelByData).toHaveBeenCalledWith(
        "scheduled-longform-posts",
        "postId",
        "longform-123",
      );
      expect(result).toBe(true);
    });

    it("should return false when longform post job not found", async () => {
      (queueClient.cancelByData as ReturnType<typeof vi.fn>).mockResolvedValue(false);

      const result = await cancelLongFormPostJob("longform-123");

      expect(result).toBe(false);
    });
  });

  describe("Post Checker Job Operations", () => {
    it("should enqueue post checker job with default delay", async () => {
      (queueClient.enqueue as ReturnType<typeof vi.fn>).mockResolvedValue({
        success: true,
        jobId: "job-123",
      });

      await enqueuePostCheckerJob();

      expect(queueClient.enqueue).toHaveBeenCalledWith(
        "post-checker",
        "check-due-posts",
        {},
        { delay: 0 },
      );
    });

    it("should enqueue post checker job with custom delay", async () => {
      (queueClient.enqueue as ReturnType<typeof vi.fn>).mockResolvedValue({
        success: true,
        jobId: "job-123",
      });

      await enqueuePostCheckerJob(5000);

      expect(queueClient.enqueue).toHaveBeenCalledWith(
        "post-checker",
        "check-due-posts",
        {},
        { delay: 5000 },
      );
    });

    it("should throw error when post checker enqueue fails", async () => {
      (queueClient.enqueue as ReturnType<typeof vi.fn>).mockResolvedValue({
        success: false,
        error: "Queue error",
      });

      await expect(enqueuePostCheckerJob()).rejects.toThrow("Queue error");
    });
  });
});

/**
 * Edge Case Tests for Queue Workers
 * 
 * Tests critical edge cases for queue worker processing:
 * - Worker crashes mid-processing
 * - Duplicate job processing
 * - Queue backpressure
 * - Redis connection failures
 * - Job retry scenarios
 */

import type { Job } from "bullmq";
import { describe, it, expect, vi, beforeEach, beforeAll } from "vitest";

// Mock BullMQ Worker
vi.mock("bullmq", () => {
  class MockWorker {
    queueName: string;
    process: ((job: import("bullmq").Job) => Promise<unknown>) | undefined;
    close: ReturnType<typeof vi.fn>;

    constructor(queueName: string, processor: ((job: import("bullmq").Job) => Promise<unknown>) | undefined, options?: unknown) {
      this.queueName = queueName;
      // Store the processor function so tests can call it
      this.process = processor;
      this.close = vi.fn();
    }
  }

  return {
    Worker: MockWorker,
    Queue: vi.fn(),
    Job: vi.fn(),
  };
});

// Mock dependencies
vi.mock("~/lib/prisma.server", () => ({
  prisma: {
    post: {
      findUnique: vi.fn(),
      update: vi.fn(),
    },
    longFormPost: {
      findUnique: vi.fn(),
      update: vi.fn(),
    },
    $use: vi.fn(),
  },
}));

vi.mock("~/models/post.commands.server", () => ({
  updatePostStatus: vi.fn(),
}));

vi.mock("~/models/longformpost.server", () => ({
  updateLongFormPostStatus: vi.fn(),
}));

vi.mock("~/models/user.server", () => ({
  getUserById: vi.fn(),
}));

vi.mock("~/infra/queue", () => ({
  getQueueInstance: vi.fn(() => ({
    add: vi.fn(),
  })),
  redis: {
    quit: vi.fn(),
  },
  closeAllQueues: vi.fn(),
}));

// Mock global fetch
global.fetch = vi.fn();

import { prisma } from "~/lib/prisma.server";
import { updateLongFormPostStatus } from "~/models/longformpost.server";
import { updatePostStatus } from "~/models/post.commands.server";
import { getUserById } from "~/models/user.server";

import { TEST_USER_ID, createMockPost } from "../utils/test-helpers";

// Import workers after mocks are set up
interface MockWorkerType {
  process?: (job: Job) => Promise<unknown>;
  close: ReturnType<typeof vi.fn>;
}
let scheduledPostsWorker: MockWorkerType | undefined;
let scheduledLongFormPostsWorker: MockWorkerType | undefined;

beforeAll(async () => {
  const module = await import("~/features/posts/queues.server");
  scheduledPostsWorker = module.scheduledPostsWorker as unknown as MockWorkerType;
  scheduledLongFormPostsWorker = module.scheduledLongFormPostsWorker as unknown as MockWorkerType;
});

describe("Queue Worker Edge Cases", () => {
  const TEST_POST_ID = "post-123";
  const TEST_SIGNED_EVENT = {
    id: "event-123",
    kind: 1,
    content: "Test post",
    pubkey: "pubkey-123",
    created_at: Math.floor(Date.now() / 1000),
    tags: [],
    sig: "sig-123",
  };

  beforeEach(() => {
    vi.clearAllMocks();
    process.env.NOSTR_PUBLISHER_URL = "https://api.nostr-publisher.com/publish";
  });

  describe("Worker Crash Scenarios", () => {
    it("should handle database error during post status update", async () => {
      (prisma.post.findUnique as ReturnType<typeof vi.fn>).mockResolvedValue({
        id: TEST_POST_ID,
        isPosted: false,
        nostrEventId: null,
      });

      (updatePostStatus as ReturnType<typeof vi.fn>).mockRejectedValue(
        new Error("Database connection lost"),
      );

      const mockJobData = {
        postId: TEST_POST_ID,
        userId: TEST_USER_ID,
        signedEvent: TEST_SIGNED_EVENT,
      };
      const mockJob: Job = {
        data: mockJobData,
      } as unknown as Job;

      // Worker processor function should throw error (BullMQ will handle retry)
      // The processor is the function passed to Worker constructor
      if (!scheduledPostsWorker?.process) {
        throw new Error("scheduledPostsWorker.process is not defined");
      }
      const processor = scheduledPostsWorker.process;
      await expect(
        processor(mockJob),
      ).rejects.toThrow("Database connection lost");
    });

    it("should handle user not found error gracefully", async () => {
      (prisma.post.findUnique as ReturnType<typeof vi.fn>).mockResolvedValue({
        id: TEST_POST_ID,
        isPosted: false,
        nostrEventId: null,
      });

      (updatePostStatus as ReturnType<typeof vi.fn>).mockResolvedValue(undefined);
      (getUserById as ReturnType<typeof vi.fn>).mockResolvedValue(null);

      const mockJobData = {
        postId: TEST_POST_ID,
        userId: TEST_USER_ID,
        signedEvent: TEST_SIGNED_EVENT,
      };
      const mockJob: Job = {
        data: mockJobData,
      } as unknown as Job;

      if (!scheduledPostsWorker?.process) {
        throw new Error("scheduledPostsWorker.process is not defined");
      }
      await expect(
        scheduledPostsWorker.process(mockJob),
      ).rejects.toThrow(`User ${TEST_USER_ID} not found`);
    });

    it("should handle Nostr publisher API failure", async () => {
      (prisma.post.findUnique as ReturnType<typeof vi.fn>).mockResolvedValue({
        id: TEST_POST_ID,
        isPosted: false,
        nostrEventId: null,
      });

      (updatePostStatus as ReturnType<typeof vi.fn>).mockResolvedValue(undefined);
      (getUserById as ReturnType<typeof vi.fn>).mockResolvedValue({
        userRelays: ["wss://relay1.com"],
      });

      (global.fetch as ReturnType<typeof vi.fn>).mockResolvedValue({
        ok: false,
        status: 500,
        statusText: "Internal Server Error",
      });

      const mockJobData = {
        postId: TEST_POST_ID,
        userId: TEST_USER_ID,
        signedEvent: TEST_SIGNED_EVENT,
      };
      const mockJob: Job = {
        data: mockJobData,
      } as unknown as Job;

      if (!scheduledPostsWorker?.process) {
        throw new Error("scheduledPostsWorker.process is not defined");
      }
      await expect(
        scheduledPostsWorker.process(mockJob),
      ).rejects.toThrow("Failed to post to nostr publisher");

      // Post should still be marked as posted (idempotency prevents duplicate)
      expect(updatePostStatus).toHaveBeenCalled();
    });

    it("should handle network timeout when publishing", async () => {
      (prisma.post.findUnique as ReturnType<typeof vi.fn>).mockResolvedValue({
        id: TEST_POST_ID,
        isPosted: false,
        nostrEventId: null,
      });

      (updatePostStatus as ReturnType<typeof vi.fn>).mockResolvedValue(undefined);
      (getUserById as ReturnType<typeof vi.fn>).mockResolvedValue({
        userRelays: ["wss://relay1.com"],
      });

      (global.fetch as ReturnType<typeof vi.fn>).mockImplementation(() => {
        return new Promise((_, reject) => {
          setTimeout(() => reject(new Error("Network timeout")), 100);
        });
      });

      const mockJobData = {
        postId: TEST_POST_ID,
        userId: TEST_USER_ID,
        signedEvent: TEST_SIGNED_EVENT,
      };
      const mockJob: Job = {
        data: mockJobData,
      } as unknown as Job;

      if (!scheduledPostsWorker?.process) {
        throw new Error("scheduledPostsWorker.process is not defined");
      }
      await expect(
        scheduledPostsWorker.process(mockJob),
      ).rejects.toThrow("Network timeout");
    });
  });

  describe("Idempotency Edge Cases", () => {
    it("should skip processing if post already posted (duplicate job)", async () => {
      (prisma.post.findUnique as ReturnType<typeof vi.fn>).mockResolvedValue({
        id: TEST_POST_ID,
        isPosted: true, // Already posted
        nostrEventId: "event-123",
      });

      const mockJobData = {
        postId: TEST_POST_ID,
        userId: TEST_USER_ID,
        signedEvent: TEST_SIGNED_EVENT,
      };
      const mockJob: Job = {
        data: mockJobData,
      } as unknown as Job;

      if (!scheduledPostsWorker?.process) {
        throw new Error("scheduledPostsWorker.process is not defined");
      }
      const result = await scheduledPostsWorker.process(mockJob);

      expect(result).toEqual({
        success: true,
        postId: TEST_POST_ID,
        skipped: true,
      });
      expect(updatePostStatus).not.toHaveBeenCalled();
      expect(global.fetch).not.toHaveBeenCalled();
    });

    it("should handle race condition: post becomes posted between check and update", async () => {
      // First call: post not posted
      // Second call (simulating race): post is posted
      (prisma.post.findUnique as ReturnType<typeof vi.fn>)
        .mockResolvedValueOnce({
          id: TEST_POST_ID,
          isPosted: false,
          nostrEventId: null,
        })
        .mockResolvedValueOnce({
          id: TEST_POST_ID,
          isPosted: true, // Another worker posted it
          nostrEventId: "event-123",
        });

      (updatePostStatus as ReturnType<typeof vi.fn>).mockRejectedValue(
        new Error("Post already posted"), // Simulate unique constraint violation
