      fc.assert(
        fc.property(
          fc.float({ min: 0, max: Math.fround(10000) }),
          (usdAmount: number) => {
            const sats = Math.round((usdAmount / 2500) * 100000000);
            return sats >= 0;
          },
        ),
        { numRuns: 100 },
